/* Alpha Academy Cambodia — Chinese–English Daily Conversation: lesson bank
   ---------------------------------------------------------------------------
   100 everyday situations in 10 chapters. Read by assets/js/zhc.js.

   Per situation:  n, ch (chapter index), title, titleZh, titleKm,
   art (scene spec for kcm-scenes.js: "setting prop outfit sex [age]"),
   scene, dialogue [{who, hz, py, en, km}], phrases [{hz, py, en, km}],
   tips [{label, html, culture}].

   hz = Chinese characters (what the voice reads), py = pinyin with tone
   marks, en = English (may carry <em>), km = Khmer meaning (plain text).
   A dialogue turn whose `who` is "You" is the learner's line: role-play
   hides exactly those. Quizzes are generated from the phrases and dialogue
   every time, so they need no separate bank.                               */
window.ZHC = {"chapters":[{"en":"Greetings & Introductions","zh":"问候与介绍","km":"ការស្វាគមន៍ និងការណែនាំខ្លួន"},{"en":"Time, Dates & Weather","zh":"时间、日期和天气","km":"ពេលវេលា កាលបរិច្ឆេទ និងអាកាសធាតុ"},{"en":"Food & Drink","zh":"饮食","km":"ម្ហូបអាហារ និងភេសជ្ជៈ"},{"en":"Shopping & Money","zh":"购物和付钱","km":"ការទិញទំនិញ និងលុយកាក់"},{"en":"Getting Around & Hotels","zh":"交通和住宿","km":"ការធ្វើដំណើរ និងសណ្ឋាគារ"},{"en":"Home & Daily Life","zh":"家庭和日常生活","km":"ផ្ទះ និងជីវិតប្រចាំថ្ងៃ"},{"en":"Work & Business","zh":"工作和商务","km":"ការងារ និងអាជីវកម្ម"},{"en":"School & Study","zh":"学校和学习","km":"សាលារៀន និងការសិក្សា"},{"en":"Health & Emergencies","zh":"健康和紧急情况","km":"សុខភាព និងគ្រាអាសន្ន"},{"en":"Friends, Hobbies & Travel","zh":"朋友、爱好和旅行","km":"មិត្តភក្តិ ចំណូលចិត្ត និងទេសចរណ៍"}],"key":{"tones":[{"py":"mā","hz":"妈","name":"1st tone — high and flat","nameKm":"សំនៀងទី ១ — ខ្ពស់ និងស្មើ","desc":"Hold it high and level, like singing one note. <em>mā</em> = mum","descKm":"រក្សាសំឡេងខ្ពស់ និងស្មើ ដូចច្រៀងសូរមួយ។ mā = ម្តាយ"},{"py":"má","hz":"麻","name":"2nd tone — rising","nameKm":"សំនៀងទី ២ — ឡើង","desc":"Rise from the middle to the top, like asking “what?” <em>má</em> = hemp","descKm":"ឡើងពីកណ្តាលទៅខ្ពស់ ដូចពេលសួរថា «អី?»។ má = ក្រចៅ"},{"py":"mǎ","hz":"马","name":"3rd tone — low dip","nameKm":"សំនៀងទី ៣ — ចុះទាប","desc":"Go low and stay low (it rises again only at the end of a phrase). <em>mǎ</em> = horse","descKm":"បញ្ចុះទាប ហើយនៅទាប (ឡើងវិញតែនៅចុងឃ្លា)។ mǎ = សេះ"},{"py":"mà","hz":"骂","name":"4th tone — falling","nameKm":"សំនៀងទី ៤ — ធ្លាក់","desc":"Drop sharply from high to low, like a firm “No!” <em>mà</em> = to scold","descKm":"ធ្លាក់ខ្លាំងពីខ្ពស់ទៅទាប ដូចពាក្យ «ទេ!» យ៉ាងម៉ឺងម៉ាត់។ mà = ស្តីបន្ទោស"},{"py":"ma","hz":"吗","name":"Neutral tone — light","nameKm":"សំនៀងស្រាល","desc":"No mark: short and light. <em>ma</em> turns a sentence into a question","descKm":"គ្មានសញ្ញា៖ ខ្លី និងស្រាល។ ma ធ្វើឱ្យប្រយោគក្លាយជាសំណួរ"}],"sounds":[{"sym":"q","exp":"like <em>ch</em> in <em>cheese</em>, lips spread","hz":"去","py":"qù"},{"sym":"x","exp":"like <em>sh</em> in <em>she</em>, lips spread","hz":"谢","py":"xiè"},{"sym":"j","exp":"like <em>j</em> in <em>jeep</em>, lips spread","hz":"叫","py":"jiào"},{"sym":"zh","exp":"like <em>j</em> in <em>jar</em>, tongue curled back","hz":"中","py":"zhōng"},{"sym":"ch","exp":"like <em>ch</em> in <em>church</em>, tongue curled back","hz":"吃","py":"chī"},{"sym":"sh","exp":"like <em>sh</em> in <em>shirt</em>, tongue curled back","hz":"是","py":"shì"},{"sym":"r","exp":"between <em>r</em> in <em>run</em> and <em>s</em> in <em>pleasure</em>","hz":"人","py":"rén"},{"sym":"z","exp":"like <em>ds</em> in <em>kids</em>","hz":"在","py":"zài"},{"sym":"c","exp":"like <em>ts</em> in <em>cats</em>, with a puff of air","hz":"菜","py":"cài"},{"sym":"ü","exp":"say <em>ee</em> with rounded lips (written <em>u</em> after j, q, x, y)","hz":"女","py":"nǚ"},{"sym":"e","exp":"like <em>u</em> in <em>bun</em>, from the throat","hz":"喝","py":"hē"},{"sym":"-i","exp":"after z, c, s, zh, ch, sh, r it is a buzz, not <em>ee</em>","hz":"四","py":"sì"}],"notes":[{"label":"Two third tones","html":"When two third tones meet, the first becomes a rising tone: <span class=\"zh\">你好</span> is written <em>nǐ hǎo</em> but said <em>ní hǎo</em>."},{"label":"不 and 一","html":"<span class=\"zh\">不</span> <em>bù</em> and <span class=\"zh\">一</span> <em>yī</em> change tone before other words. This course writes the tone you actually say: <em>bú shì</em>, <em>yí ge</em>, <em>yìdiǎnr</em>."}]},"sits":[
{"n":1,"ch":0,"title":"Saying Hello","titleZh":"打招呼","titleKm":"ការនិយាយសួស្តី","art":"office coffee suit f","scene":"It is your first morning at a Chinese company in Phnom Penh. A colleague smiles at you by the coffee machine.","dialogue":[{"who":"Colleague","hz":"早上好！","py":"Zǎoshang hǎo!","en":"Good morning!","km":"អរុណសួស្តី!"},{"who":"You","hz":"早上好！你好！","py":"Zǎoshang hǎo! Nǐ hǎo!","en":"Good morning! Hello!","km":"អរុណសួស្តី! សួស្តី!"},{"who":"Colleague","hz":"你是新同事吧？","py":"Nǐ shì xīn tóngshì ba?","en":"You're the new colleague, right?","km":"អ្នកជាមិត្តរួមការងារថ្មីមែនទេ?"},{"who":"You","hz":"对，我是新来的。","py":"Duì, wǒ shì xīn lái de.","en":"Yes, I'm the new one.","km":"បាទ/ចាស ខ្ញុំទើបមកថ្មី។"},{"who":"Colleague","hz":"欢迎欢迎！你最近好吗？","py":"Huānyíng huānyíng! Nǐ zuìjìn hǎo ma?","en":"Welcome! How have you been lately?","km":"សូមស្វាគមន៍! ថ្មីៗនេះអ្នកសុខសប្បាយទេ?"},{"who":"You","hz":"我很好，谢谢。你呢？","py":"Wǒ hěn hǎo, xièxie. Nǐ ne?","en":"I'm very well, thanks. And you?","km":"ខ្ញុំសុខសប្បាយ អរគុណ។ ចុះអ្នកវិញ?"},{"who":"Colleague","hz":"我也很好。","py":"Wǒ yě hěn hǎo.","en":"I'm fine too.","km":"ខ្ញុំក៏សុខសប្បាយដែរ។"}],"phrases":[{"hz":"你好","py":"nǐ hǎo","en":"Hello","km":"សួស្តី"},{"hz":"早上好","py":"zǎoshang hǎo","en":"Good morning","km":"អរុណសួស្តី"},{"hz":"你好吗？","py":"nǐ hǎo ma?","en":"How are you?","km":"អ្នកសុខសប្បាយទេ?"},{"hz":"我很好","py":"wǒ hěn hǎo","en":"I'm (very) well","km":"ខ្ញុំសុខសប្បាយ"},{"hz":"你呢？","py":"nǐ ne?","en":"And you?","km":"ចុះអ្នកវិញ?"},{"hz":"欢迎","py":"huānyíng","en":"Welcome","km":"សូមស្វាគមន៍"}],"tips":[{"label":"Two third tones","html":"<span class=\"zh\">你好</span> is written <em>nǐ hǎo</em>, but when two third tones meet, the first one rises: say <em>ní hǎo</em>. The spelling never changes — only the sound.","culture":false},{"label":"Hello to many","html":"To greet a group, say <span class=\"zh\">大家好</span> <em>dàjiā hǎo</em> — “hello, everyone”.","culture":true}]},
{"n":2,"ch":0,"title":"Introducing Yourself","titleZh":"自我介绍","titleKm":"ការណែនាំខ្លួន","art":"classroom nametag shirt f","scene":"On the first day of a Chinese class, the teacher asks each student to stand up and say who they are.","dialogue":[{"who":"Teacher","hz":"你好！请介绍一下你自己。","py":"Nǐ hǎo! Qǐng jièshào yíxià nǐ zìjǐ.","en":"Hello! Please introduce yourself.","km":"សួស្តី! សូមណែនាំខ្លួនឯងបន្តិច។"},{"who":"You","hz":"大家好！我叫索披。","py":"Dàjiā hǎo! Wǒ jiào Suǒ Pī.","en":"Hello, everyone! My name is Sophy.","km":"សួស្តីអ្នកទាំងអស់គ្នា! ខ្ញុំឈ្មោះសុភី។"},{"who":"Teacher","hz":"你姓什么？","py":"Nǐ xìng shénme?","en":"What is your family name?","km":"តើអ្នកមាននាមត្រកូលអ្វី?"},{"who":"You","hz":"我姓陈。我是学生。","py":"Wǒ xìng Chén. Wǒ shì xuésheng.","en":"My family name is Chen. I'm a student.","km":"ខ្ញុំត្រកូលចាន់។ ខ្ញុំជាសិស្ស។"},{"who":"Teacher","hz":"很好。你为什么学中文？","py":"Hěn hǎo. Nǐ wèishénme xué Zhōngwén?","en":"Very good. Why are you learning Chinese?","km":"ល្អណាស់។ ហេតុអ្វីបានជាអ្នករៀនភាសាចិន?"},{"who":"You","hz":"因为我想去中国工作。","py":"Yīnwèi wǒ xiǎng qù Zhōngguó gōngzuò.","en":"Because I want to work in China.","km":"ព្រោះខ្ញុំចង់ទៅធ្វើការនៅប្រទេសចិន។"},{"who":"Teacher","hz":"太好了！认识你很高兴。","py":"Tài hǎo le! Rènshi nǐ hěn gāoxìng.","en":"Great! Nice to meet you.","km":"ល្អណាស់! រីករាយដែលបានស្គាល់អ្នក។"},{"who":"You","hz":"认识您我也很高兴。","py":"Rènshi nín wǒ yě hěn gāoxìng.","en":"Nice to meet you too.","km":"ខ្ញុំក៏រីករាយដែលបានស្គាល់លោកគ្រូដែរ។"}],"phrases":[{"hz":"我叫……","py":"wǒ jiào…","en":"My name is…","km":"ខ្ញុំឈ្មោះ…"},{"hz":"你叫什么名字？","py":"nǐ jiào shénme míngzi?","en":"What's your name?","km":"តើអ្នកឈ្មោះអ្វី?"},{"hz":"我姓……","py":"wǒ xìng…","en":"My family name is…","km":"ខ្ញុំត្រកូល…"},{"hz":"我是学生","py":"wǒ shì xuésheng","en":"I am a student","km":"ខ្ញុំជាសិស្ស"},{"hz":"认识你很高兴","py":"rènshi nǐ hěn gāoxìng","en":"Nice to meet you","km":"រីករាយដែលបានស្គាល់អ្នក"},{"hz":"请介绍一下","py":"qǐng jièshào yíxià","en":"Please introduce…","km":"សូមណែនាំបន្តិច"}],"tips":[{"label":"您 for respect","html":"<span class=\"zh\">您</span> <em>nín</em> is the polite “you”. Use it for teachers, older people and customers; <span class=\"zh\">你</span> <em>nǐ</em> for friends and people your age.","culture":true},{"label":"Family name first","html":"Chinese names put the family name first: in <span class=\"zh\">王小明</span>, <span class=\"zh\">王</span> is the family name.","culture":false}]},
{"n":3,"ch":0,"title":"Where Are You From?","titleZh":"你是哪国人？","titleKm":"តើអ្នកមកពីប្រទេសណា?","art":"cafe globe apron m","scene":"You are buying a drink in a café in Beijing. The friendly owner notices your accent.","dialogue":[{"who":"Owner","hz":"你的中文不错！你是哪国人？","py":"Nǐ de Zhōngwén búcuò! Nǐ shì nǎ guó rén?","en":"Your Chinese is good! Which country are you from?","km":"ភាសាចិនរបស់អ្នកល្អណាស់! តើអ្នកជាជនជាតិអ្វី?"},{"who":"You","hz":"谢谢！我是柬埔寨人。","py":"Xièxie! Wǒ shì Jiǎnpǔzhài rén.","en":"Thank you! I'm Cambodian.","km":"អរគុណ! ខ្ញុំជាជនជាតិខ្មែរ។"},{"who":"Owner","hz":"柬埔寨！你住在哪儿？","py":"Jiǎnpǔzhài! Nǐ zhù zài nǎr?","en":"Cambodia! Where do you live?","km":"កម្ពុជា! តើអ្នករស់នៅឯណា?"},{"who":"You","hz":"我住在金边。你去过柬埔寨吗？","py":"Wǒ zhù zài Jīnbiān. Nǐ qùguo Jiǎnpǔzhài ma?","en":"I live in Phnom Penh. Have you been to Cambodia?","km":"ខ្ញុំរស់នៅភ្នំពេញ។ តើអ្នកធ្លាប់ទៅកម្ពុជាទេ?"},{"who":"Owner","hz":"没去过，但是我很想去吴哥窟。","py":"Méi qùguo, dànshì wǒ hěn xiǎng qù Wúgē Kū.","en":"Never, but I'd love to visit Angkor Wat.","km":"មិនធ្លាប់ទេ ប៉ុន្តែខ្ញុំចង់ទៅអង្គរវត្តណាស់។"},{"who":"You","hz":"欢迎你来柬埔寨玩儿！","py":"Huānyíng nǐ lái Jiǎnpǔzhài wánr!","en":"You're welcome to come and visit Cambodia!","km":"សូមស្វាគមន៍មកលេងកម្ពុជា!"}],"phrases":[{"hz":"你是哪国人？","py":"nǐ shì nǎ guó rén?","en":"Which country are you from?","km":"តើអ្នកជាជនជាតិអ្វី?"},{"hz":"我是柬埔寨人","py":"wǒ shì Jiǎnpǔzhài rén","en":"I'm Cambodian","km":"ខ្ញុំជាជនជាតិខ្មែរ"},{"hz":"我住在金边","py":"wǒ zhù zài Jīnbiān","en":"I live in Phnom Penh","km":"ខ្ញុំរស់នៅភ្នំពេញ"},{"hz":"你住在哪儿？","py":"nǐ zhù zài nǎr?","en":"Where do you live?","km":"តើអ្នករស់នៅឯណា?"},{"hz":"你去过……吗？","py":"nǐ qùguo… ma?","en":"Have you been to…?","km":"តើអ្នកធ្លាប់ទៅ…ទេ?"},{"hz":"中国人","py":"Zhōngguó rén","en":"Chinese (person)","km":"ជនជាតិចិន"}],"tips":[{"label":"Country + 人","html":"Add <span class=\"zh\">人</span> <em>rén</em> (person) to a country: <span class=\"zh\">美国人</span> American, <span class=\"zh\">泰国人</span> Thai, <span class=\"zh\">越南人</span> Vietnamese.","culture":false},{"label":"Modest answers","html":"Praise like <span class=\"zh\">你的中文很好</span> is often answered with <span class=\"zh\">哪里哪里</span> <em>nǎli nǎli</em> — “not at all” — instead of “thank you”.","culture":true}]},
{"n":4,"ch":0,"title":"Thank You & Sorry","titleZh":"谢谢和对不起","titleKm":"អរគុណ និងសុំទោស","art":"street bag shirt f","scene":"On a busy street you bump into a woman and she drops her bag. You help her pick it up.","dialogue":[{"who":"You","hz":"哎呀，对不起！","py":"Āiyā, duìbuqǐ!","en":"Oh no, I'm sorry!","km":"អូ៎ សុំទោស!"},{"who":"Woman","hz":"没关系。","py":"Méi guānxi.","en":"It's all right.","km":"មិនអីទេ។"},{"who":"You","hz":"我来帮你。这是你的手机。","py":"Wǒ lái bāng nǐ. Zhè shì nǐ de shǒujī.","en":"Let me help you. This is your phone.","km":"ឱ្យខ្ញុំជួយ។ នេះជាទូរសព្ទរបស់អ្នក។"},{"who":"Woman","hz":"太谢谢你了！","py":"Tài xièxie nǐ le!","en":"Thank you so much!","km":"អរគុណអ្នកច្រើនណាស់!"},{"who":"You","hz":"不客气。你没事吧？","py":"Bú kèqi. Nǐ méi shì ba?","en":"You're welcome. Are you OK?","km":"មិនអីទេ។ អ្នកមិនអីទេឬ?"},{"who":"Woman","hz":"我没事。你真好！","py":"Wǒ méi shì. Nǐ zhēn hǎo!","en":"I'm fine. You're very kind!","km":"ខ្ញុំមិនអីទេ។ អ្នកចិត្តល្អណាស់!"}],"phrases":[{"hz":"谢谢","py":"xièxie","en":"Thank you","km":"អរគុណ"},{"hz":"不客气","py":"bú kèqi","en":"You're welcome","km":"មិនអីទេ (ចំពោះការអរគុណ)"},{"hz":"对不起","py":"duìbuqǐ","en":"Sorry","km":"សុំទោស"},{"hz":"没关系","py":"méi guānxi","en":"It doesn't matter","km":"មិនអីទេ"},{"hz":"不好意思","py":"bù hǎoyìsi","en":"Excuse me / sorry (light)","km":"សុំទោស (បន្តិចបន្តួច)"},{"hz":"你没事吧？","py":"nǐ méi shì ba?","en":"Are you OK?","km":"អ្នកមិនអីទេឬ?"}],"tips":[{"label":"Light or heavy","html":"<span class=\"zh\">不好意思</span> is a soft “sorry / excuse me” for small things, like squeezing past someone. Keep <span class=\"zh\">对不起</span> for real mistakes.","culture":false}]},
{"n":5,"ch":0,"title":"Saying Goodbye","titleZh":"说再见","titleKm":"ការនិយាយលាគ្នា","art":"lane sun shirt m","scene":"You have been chatting with a Chinese neighbour outside your building. It is getting late.","dialogue":[{"who":"You","hz":"不早了，我得走了。","py":"Bù zǎo le, wǒ děi zǒu le.","en":"It's getting late, I have to go.","km":"យប់ហើយ ខ្ញុំត្រូវទៅហើយ។"},{"who":"Neighbour","hz":"好的，路上小心！","py":"Hǎo de, lùshang xiǎoxīn!","en":"OK, take care on the way!","km":"បាទ/ចាស ធ្វើដំណើរប្រុងប្រយ័ត្នផង!"},{"who":"You","hz":"谢谢。明天见！","py":"Xièxie. Míngtiān jiàn!","en":"Thanks. See you tomorrow!","km":"អរគុណ។ ជួបគ្នាថ្ងៃស្អែក!"},{"who":"Neighbour","hz":"明天见！晚安。","py":"Míngtiān jiàn! Wǎn'ān.","en":"See you tomorrow! Good night.","km":"ជួបគ្នាថ្ងៃស្អែក! រាត្រីសួស្តី។"},{"who":"You","hz":"晚安！替我问你妈妈好。","py":"Wǎn'ān! Tì wǒ wèn nǐ māma hǎo.","en":"Good night! Say hello to your mum for me.","km":"រាត្រីសួស្តី! ជួយសួរសុខទុក្ខម្តាយអ្នកផង។"},{"who":"Neighbour","hz":"好，一定。再见！","py":"Hǎo, yídìng. Zàijiàn!","en":"Sure, I will. Goodbye!","km":"បាទ/ចាស ប្រាកដណាស់។ លាហើយ!"}],"phrases":[{"hz":"再见","py":"zàijiàn","en":"Goodbye","km":"លាហើយ"},{"hz":"明天见","py":"míngtiān jiàn","en":"See you tomorrow","km":"ជួបគ្នាថ្ងៃស្អែក"},{"hz":"一会儿见","py":"yíhuìr jiàn","en":"See you soon","km":"ជួបគ្នាបន្តិចទៀត"},{"hz":"晚安","py":"wǎn'ān","en":"Good night","km":"រាត្រីសួស្តី"},{"hz":"我得走了","py":"wǒ děi zǒu le","en":"I have to go","km":"ខ្ញុំត្រូវទៅហើយ"},{"hz":"路上小心","py":"lùshang xiǎoxīn","en":"Take care on the way","km":"ធ្វើដំណើរប្រុងប្រយ័ត្ន"}],"tips":[{"label":"Seeing guests off","html":"Chinese hosts often walk guests to the door or lift. Guests answer <span class=\"zh\">别送了</span> <em>bié sòng le</em> — “no need to see me out”.","culture":true}]},
{"n":6,"ch":0,"title":"Meeting a Friend's Family","titleZh":"见朋友的家人","titleKm":"ជួបក្រុមគ្រួសាររបស់មិត្តភក្តិ","art":"home tea shirt f e","scene":"Your friend Xiaoli invites you home for the first time. Her grandmother opens the door.","dialogue":[{"who":"Grandma","hz":"你好，快请进！","py":"Nǐ hǎo, kuài qǐng jìn!","en":"Hello, come in, come in!","km":"សួស្តី អញ្ជើញចូលមក!"},{"who":"You","hz":"奶奶好！这是给您的水果。","py":"Nǎinai hǎo! Zhè shì gěi nín de shuǐguǒ.","en":"Hello, Grandma! This fruit is for you.","km":"ជម្រាបសួរលោកយាយ! នេះជាផ្លែឈើជូនលោកយាយ។"},{"who":"Grandma","hz":"太客气了！请坐，喝茶吧。","py":"Tài kèqi le! Qǐng zuò, hē chá ba.","en":"You're too kind! Please sit and have some tea.","km":"គួរសមពេកហើយ! អញ្ជើញអង្គុយ ពិសាតែសិន។"},{"who":"You","hz":"谢谢奶奶。您身体好吗？","py":"Xièxie nǎinai. Nín shēntǐ hǎo ma?","en":"Thank you, Grandma. Are you keeping well?","km":"អរគុណលោកយាយ។ លោកយាយសុខភាពល្អទេ?"},{"who":"Grandma","hz":"很好，很好。你家有几口人？","py":"Hěn hǎo, hěn hǎo. Nǐ jiā yǒu jǐ kǒu rén?","en":"Very well. How many people are in your family?","km":"ល្អណាស់។ គ្រួសារអ្នកមានប៉ុន្មាននាក់?"},{"who":"You","hz":"我家有五口人：爸爸、妈妈、哥哥、妹妹和我。","py":"Wǒ jiā yǒu wǔ kǒu rén: bàba, māma, gēge, mèimei hé wǒ.","en":"There are five of us: dad, mum, my older brother, younger sister and me.","km":"គ្រួសារខ្ញុំមានប្រាំនាក់៖ ប៉ា ម៉ាក់ បងប្រុស ប្អូនស្រី និងខ្ញុំ។"}],"phrases":[{"hz":"请进","py":"qǐng jìn","en":"Please come in","km":"អញ្ជើញចូល"},{"hz":"请坐","py":"qǐng zuò","en":"Please sit down","km":"អញ្ជើញអង្គុយ"},{"hz":"你家有几口人？","py":"nǐ jiā yǒu jǐ kǒu rén?","en":"How many people are in your family?","km":"គ្រួសារអ្នកមានប៉ុន្មាននាក់?"},{"hz":"爸爸、妈妈","py":"bàba, māma","en":"Dad, mum","km":"ប៉ា ម៉ាក់"},{"hz":"哥哥、姐姐","py":"gēge, jiějie","en":"Older brother, older sister","km":"បងប្រុស បងស្រី"},{"hz":"弟弟、妹妹","py":"dìdi, mèimei","en":"Younger brother, younger sister","km":"ប្អូនប្រុស ប្អូនស្រី"}],"tips":[{"label":"Bring a small gift","html":"Fruit, tea or sweets are good gifts for a first visit. Avoid clocks — <span class=\"zh\">送钟</span> “giving a clock” sounds like “seeing someone off to death”.","culture":true},{"label":"口 for family","html":"Count family members with <span class=\"zh\">口</span> <em>kǒu</em> (mouth): <span class=\"zh\">三口人</span> = three people.","culture":false}]},
{"n":7,"ch":0,"title":"What Do You Do?","titleZh":"你做什么工作？","titleKm":"តើអ្នកធ្វើការអ្វី?","art":"park briefcase suit m","scene":"At a friend's party you start talking to a man in a suit.","dialogue":[{"who":"Man","hz":"你做什么工作？","py":"Nǐ zuò shénme gōngzuò?","en":"What do you do for work?","km":"តើអ្នកធ្វើការអ្វី?"},{"who":"You","hz":"我是老师，我教英语。你呢？","py":"Wǒ shì lǎoshī, wǒ jiāo Yīngyǔ. Nǐ ne?","en":"I'm a teacher, I teach English. And you?","km":"ខ្ញុំជាគ្រូ ខ្ញុំបង្រៀនភាសាអង់គ្លេស។ ចុះអ្នកវិញ?"},{"who":"Man","hz":"我在一家银行工作。","py":"Wǒ zài yì jiā yínháng gōngzuò.","en":"I work at a bank.","km":"ខ្ញុំធ្វើការនៅធនាគារមួយ។"},{"who":"You","hz":"你的工作忙不忙？","py":"Nǐ de gōngzuò máng bu máng?","en":"Is your job busy?","km":"ការងាររបស់អ្នករវល់ទេ?"},{"who":"Man","hz":"挺忙的。你喜欢当老师吗？","py":"Tǐng máng de. Nǐ xǐhuan dāng lǎoshī ma?","en":"Quite busy. Do you like being a teacher?","km":"រវល់ដែរ។ តើអ្នកចូលចិត្តធ្វើជាគ្រូទេ?"},{"who":"You","hz":"很喜欢，我的学生都很可爱。","py":"Hěn xǐhuan, wǒ de xuésheng dōu hěn kě'ài.","en":"I love it — my students are all lovely.","km":"ចូលចិត្តណាស់ សិស្សរបស់ខ្ញុំគួរឱ្យស្រឡាញ់ទាំងអស់។"}],"phrases":[{"hz":"你做什么工作？","py":"nǐ zuò shénme gōngzuò?","en":"What do you do?","km":"តើអ្នកធ្វើការអ្វី?"},{"hz":"我是老师","py":"wǒ shì lǎoshī","en":"I'm a teacher","km":"ខ្ញុំជាគ្រូ"},{"hz":"我在银行工作","py":"wǒ zài yínháng gōngzuò","en":"I work at a bank","km":"ខ្ញុំធ្វើការនៅធនាគារ"},{"hz":"医生","py":"yīshēng","en":"Doctor","km":"វេជ្ជបណ្ឌិត"},{"hz":"工程师","py":"gōngchéngshī","en":"Engineer","km":"វិស្វករ"},{"hz":"忙不忙？","py":"máng bu máng?","en":"Busy or not?","km":"រវល់ឬអត់?"}],"tips":[{"label":"Yes-no with A-not-A","html":"Instead of <span class=\"zh\">吗</span>, you can ask “busy-not-busy?”: <span class=\"zh\">忙不忙？</span>, <span class=\"zh\">好不好？</span>, <span class=\"zh\">是不是？</span>","culture":false}]},
{"n":8,"ch":0,"title":"I Don't Understand","titleZh":"我听不懂","titleKm":"ខ្ញុំស្តាប់មិនយល់","art":"market question apron f","scene":"A stall owner at a Chinese market talks to you very fast. You catch only one word.","dialogue":[{"who":"Seller","hz":"这个今天特价，买二送一，要不要？","py":"Zhège jīntiān tèjià, mǎi èr sòng yī, yào bu yào?","en":"This is on special today — buy two, get one free. Want some?","km":"នេះមានតម្លៃពិសេសថ្ងៃនេះ ទិញពីរ ថែមមួយ។ យកទេ?"},{"who":"You","hz":"对不起，我听不懂。","py":"Duìbuqǐ, wǒ tīng bu dǒng.","en":"Sorry, I don't understand.","km":"សុំទោស ខ្ញុំស្តាប់មិនយល់។"},{"who":"Seller","hz":"哦，买两个，送一个。","py":"Ò, mǎi liǎng ge, sòng yí ge.","en":"Oh — buy two, get one free.","km":"អូ ទិញពីរ ថែមមួយ។"},{"who":"You","hz":"请你说慢一点儿，好吗？","py":"Qǐng nǐ shuō màn yìdiǎnr, hǎo ma?","en":"Could you speak a bit slower, please?","km":"សូមនិយាយយឺតបន្តិចបានទេ?"},{"who":"Seller","hz":"好。买——两——个，送——一——个。","py":"Hǎo. Mǎi — liǎng — ge, sòng — yí — ge.","en":"OK. Buy — two — get — one — free.","km":"បាទ/ចាស។ ទិញ—ពីរ—ថែម—មួយ។"},{"who":"You","hz":"啊，我懂了！谢谢！","py":"À, wǒ dǒng le! Xièxie!","en":"Ah, I get it now! Thanks!","km":"អា ខ្ញុំយល់ហើយ! អរគុណ!"}],"phrases":[{"hz":"我听不懂","py":"wǒ tīng bu dǒng","en":"I don't understand (hearing)","km":"ខ្ញុំស្តាប់មិនយល់"},{"hz":"请说慢一点儿","py":"qǐng shuō màn yìdiǎnr","en":"Please speak more slowly","km":"សូមនិយាយយឺតបន្តិច"},{"hz":"请再说一遍","py":"qǐng zài shuō yí biàn","en":"Please say it again","km":"សូមនិយាយម្តងទៀត"},{"hz":"我懂了","py":"wǒ dǒng le","en":"I understand now","km":"ខ្ញុំយល់ហើយ"},{"hz":"……是什么意思？","py":"… shì shénme yìsi?","en":"What does … mean?","km":"…មានន័យថាអ្វី?"},{"hz":"你会说英语吗？","py":"nǐ huì shuō Yīngyǔ ma?","en":"Can you speak English?","km":"តើអ្នកចេះនិយាយភាសាអង់គ្លេសទេ?"}],"tips":[{"label":"Hearing vs reading","html":"<span class=\"zh\">听不懂</span> = can't understand by listening; <span class=\"zh\">看不懂</span> = can't understand by reading. Both are very useful!","culture":false}]},
{"n":9,"ch":0,"title":"Age & Birthday","titleZh":"年龄和生日","titleKm":"អាយុ និងថ្ងៃកំណើត","art":"home gift shirt f c","scene":"You visit a Chinese family and meet their little daughter, who is holding a present.","dialogue":[{"who":"You","hz":"小朋友，你今年几岁了？","py":"Xiǎo péngyou, nǐ jīnnián jǐ suì le?","en":"Hi there, how old are you this year?","km":"ប្អូនតូច ឆ្នាំនេះប្អូនអាយុប៉ុន្មានហើយ?"},{"who":"Girl","hz":"我七岁了！","py":"Wǒ qī suì le!","en":"I'm seven!","km":"ខ្ញុំអាយុប្រាំពីរឆ្នាំហើយ!"},{"who":"You","hz":"你的生日是几月几号？","py":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","en":"When is your birthday?","km":"ថ្ងៃកំណើតរបស់ប្អូនថ្ងៃទីប៉ុន្មាន ខែអ្វី?"},{"who":"Girl","hz":"就是今天！十月五号。","py":"Jiù shì jīntiān! Shí yuè wǔ hào.","en":"It's today! October the fifth.","km":"គឺថ្ងៃនេះតែម្តង! ថ្ងៃទីប្រាំ ខែតុលា។"},{"who":"You","hz":"真的吗？祝你生日快乐！","py":"Zhēn de ma? Zhù nǐ shēngrì kuàilè!","en":"Really? Happy birthday!","km":"ពិតមែនឬ? រីករាយថ្ងៃកំណើត!"},{"who":"Girl","hz":"谢谢！你多大了？","py":"Xièxie! Nǐ duō dà le?","en":"Thank you! How old are you?","km":"អរគុណ! ចុះបងអាយុប៉ុន្មានហើយ?"},{"who":"You","hz":"我二十五岁。","py":"Wǒ èrshíwǔ suì.","en":"I'm twenty-five.","km":"បងអាយុម្ភៃប្រាំឆ្នាំ។"}],"phrases":[{"hz":"你几岁了？","py":"nǐ jǐ suì le?","en":"How old are you? (to a child)","km":"ប្អូនអាយុប៉ុន្មានហើយ? (សួរក្មេង)"},{"hz":"你多大了？","py":"nǐ duō dà le?","en":"How old are you? (to an adult)","km":"អ្នកអាយុប៉ុន្មានហើយ? (សួរមនុស្សពេញវ័យ)"},{"hz":"我二十五岁","py":"wǒ èrshíwǔ suì","en":"I'm twenty-five","km":"ខ្ញុំអាយុម្ភៃប្រាំឆ្នាំ"},{"hz":"你的生日是几月几号？","py":"nǐ de shēngrì shì jǐ yuè jǐ hào?","en":"When is your birthday?","km":"ថ្ងៃកំណើតរបស់អ្នកនៅថ្ងៃណា?"},{"hz":"祝你生日快乐！","py":"zhù nǐ shēngrì kuàilè!","en":"Happy birthday!","km":"រីករាយថ្ងៃកំណើត!"},{"hz":"今年","py":"jīnnián","en":"This year","km":"ឆ្នាំនេះ"}],"tips":[{"label":"Asking an elder","html":"For older people, ask politely: <span class=\"zh\">您多大年纪了？</span> <em>Nín duō dà niánjì le?</em>","culture":true}]},
{"n":10,"ch":0,"title":"Adding Each Other on WeChat","titleZh":"加微信","titleKm":"បន្ថែមគ្នាលើ WeChat","art":"cafe phone shirt m","scene":"You have had a great chat with a Chinese student at a language exchange. You want to stay in touch.","dialogue":[{"who":"You","hz":"我们加个微信吧！","py":"Wǒmen jiā ge Wēixìn ba!","en":"Let's add each other on WeChat!","km":"យើងបន្ថែមគ្នាក្នុង WeChat ណា!"},{"who":"Student","hz":"好啊！我扫你还是你扫我？","py":"Hǎo a! Wǒ sǎo nǐ háishi nǐ sǎo wǒ?","en":"Sure! Shall I scan yours, or will you scan mine?","km":"បាន! ខ្ញុំស្កេនរបស់អ្នក ឬអ្នកស្កេនរបស់ខ្ញុំ?"},{"who":"You","hz":"我扫你吧。你的二维码在哪儿？","py":"Wǒ sǎo nǐ ba. Nǐ de èrwéimǎ zài nǎr?","en":"I'll scan you. Where's your QR code?","km":"ខ្ញុំស្កេនរបស់អ្នក។ QR code របស់អ្នកនៅឯណា?"},{"who":"Student","hz":"在这儿。加上了吗？","py":"Zài zhèr. Jiāshàng le ma?","en":"Here. Did it work?","km":"នៅទីនេះ។ បន្ថែមបានហើយឬនៅ?"},{"who":"You","hz":"加上了。你的电话号码是多少？","py":"Jiāshàng le. Nǐ de diànhuà hàomǎ shì duōshao?","en":"Yes, done. What's your phone number?","km":"បានហើយ។ លេខទូរសព្ទរបស់អ្នកលេខប៉ុន្មាន?"},{"who":"Student","hz":"一三八，五六七八，九零一二。","py":"Yāo sān bā, wǔ liù qī bā, jiǔ líng yāo èr.","en":"138-5678-9012.","km":"មួយ បី ប្រាំបី, ប្រាំ ប្រាំមួយ ប្រាំពីរ ប្រាំបី, ប្រាំបួន សូន្យ មួយ ពីរ។"},{"who":"You","hz":"好，有空联系！","py":"Hǎo, yǒu kòng liánxì!","en":"Great, let's keep in touch!","km":"ល្អ ពេលទំនេរទាក់ទងគ្នាណា!"}],"phrases":[{"hz":"加个微信吧","py":"jiā ge Wēixìn ba","en":"Let's add each other on WeChat","km":"បន្ថែមគ្នាលើ WeChat ណា"},{"hz":"二维码","py":"èrwéimǎ","en":"QR code","km":"QR code"},{"hz":"扫一下","py":"sǎo yíxià","en":"Scan it","km":"ស្កេនបន្តិច"},{"hz":"你的电话号码是多少？","py":"nǐ de diànhuà hàomǎ shì duōshao?","en":"What's your phone number?","km":"លេខទូរសព្ទរបស់អ្នកលេខប៉ុន្មាន?"},{"hz":"有空联系","py":"yǒu kòng liánxì","en":"Keep in touch","km":"ពេលទំនេរទាក់ទងគ្នា"},{"hz":"发消息","py":"fā xiāoxi","en":"Send a message","km":"ផ្ញើសារ"}],"tips":[{"label":"幺 for one","html":"In phone and room numbers, <span class=\"zh\">一</span> is read <em>yāo</em> so it is not confused with <span class=\"zh\">七</span> <em>qī</em>.","culture":false},{"label":"WeChat everywhere","html":"In China, WeChat is used for chatting, paying and even booking doctors. Asking to add someone is normal and friendly.","culture":true}]},
{"n":11,"ch":1,"title":"What Time Is It?","titleZh":"现在几点？","titleKm":"ឥឡូវម៉ោងប៉ុន្មាន?","art":"street clock shirt m","scene":"Your phone battery is dead and you need to catch a bus. You ask a man waiting at the stop.","dialogue":[{"who":"You","hz":"请问，现在几点？","py":"Qǐngwèn, xiànzài jǐ diǎn?","en":"Excuse me, what time is it now?","km":"សុំសួរ ឥឡូវម៉ោងប៉ុន្មានហើយ?"},{"who":"Man","hz":"现在两点半。","py":"Xiànzài liǎng diǎn bàn.","en":"It's half past two.","km":"ឥឡូវម៉ោងពីរកន្លះ។"},{"who":"You","hz":"谢谢。三路车几点来？","py":"Xièxie. Sān lù chē jǐ diǎn lái?","en":"Thanks. What time does the number 3 bus come?","km":"អរគុណ។ ឡានក្រុងលេខបីមកម៉ោងប៉ុន្មាន?"},{"who":"Man","hz":"两点四十五分。还有一刻钟。","py":"Liǎng diǎn sìshíwǔ fēn. Hái yǒu yí kè zhōng.","en":"At 2:45. Another quarter of an hour.","km":"ម៉ោងពីរ សែសិបប្រាំនាទី។ នៅសល់មួយភាគបួនម៉ោងទៀត។"},{"who":"You","hz":"还来得及。谢谢您！","py":"Hái láidejí. Xièxie nín!","en":"I still have time. Thank you!","km":"នៅទាន់ពេល។ អរគុណលោក!"},{"who":"Man","hz":"不客气。","py":"Bú kèqi.","en":"You're welcome.","km":"មិនអីទេ។"}],"phrases":[{"hz":"现在几点？","py":"xiànzài jǐ diǎn?","en":"What time is it now?","km":"ឥឡូវម៉ោងប៉ុន្មាន?"},{"hz":"两点半","py":"liǎng diǎn bàn","en":"Half past two","km":"ម៉ោងពីរកន្លះ"},{"hz":"三点一刻","py":"sān diǎn yí kè","en":"Quarter past three","km":"ម៉ោងបីដប់ប្រាំនាទី"},{"hz":"差五分八点","py":"chà wǔ fēn bā diǎn","en":"Five to eight","km":"ម៉ោងប្រាំបីខ្វះប្រាំនាទី"},{"hz":"几点来？","py":"jǐ diǎn lái?","en":"What time does it come?","km":"មកម៉ោងប៉ុន្មាន?"},{"hz":"来得及","py":"láidejí","en":"There's still time","km":"នៅទាន់ពេល"}],"tips":[{"label":"两 for two o'clock","html":"Say <span class=\"zh\">两点</span> <em>liǎng diǎn</em>, never <em>èr diǎn</em>, for two o'clock. <span class=\"zh\">两</span> is the “two” used before measure words.","culture":false}]},
{"n":12,"ch":1,"title":"Days of the Week","titleZh":"星期几？","titleKm":"ថ្ងៃអ្វី?","art":"office calendar suit f","scene":"You and a colleague are trying to find a day for a team lunch.","dialogue":[{"who":"Colleague","hz":"今天星期几？","py":"Jīntiān xīngqī jǐ?","en":"What day is it today?","km":"ថ្ងៃនេះថ្ងៃអ្វី?"},{"who":"You","hz":"今天星期一。","py":"Jīntiān xīngqīyī.","en":"Today is Monday.","km":"ថ្ងៃនេះថ្ងៃច័ន្ទ។"},{"who":"Colleague","hz":"我们星期三一起吃午饭，怎么样？","py":"Wǒmen xīngqīsān yìqǐ chī wǔfàn, zěnmeyàng?","en":"How about lunch together on Wednesday?","km":"ថ្ងៃពុធយើងញ៉ាំអាហារថ្ងៃត្រង់ជាមួយគ្នា យ៉ាងម៉េចដែរ?"},{"who":"You","hz":"星期三我有会。星期四可以吗？","py":"Xīngqīsān wǒ yǒu huì. Xīngqīsì kěyǐ ma?","en":"I have a meeting on Wednesday. Is Thursday OK?","km":"ថ្ងៃពុធខ្ញុំមានប្រជុំ។ ថ្ងៃព្រហស្បតិ៍បានទេ?"},{"who":"Colleague","hz":"可以！星期四中午十二点。","py":"Kěyǐ! Xīngqīsì zhōngwǔ shí'èr diǎn.","en":"Sure! Thursday at twelve noon.","km":"បាន! ថ្ងៃព្រហស្បតិ៍ ម៉ោងដប់ពីរថ្ងៃត្រង់។"},{"who":"You","hz":"好，不见不散！","py":"Hǎo, bú jiàn bú sàn!","en":"Great — see you there!","km":"ល្អ ជួបគ្នានៅទីនោះ!"}],"phrases":[{"hz":"今天星期几？","py":"jīntiān xīngqī jǐ?","en":"What day is it today?","km":"ថ្ងៃនេះថ្ងៃអ្វី?"},{"hz":"星期一","py":"xīngqīyī","en":"Monday","km":"ថ្ងៃច័ន្ទ"},{"hz":"星期五","py":"xīngqīwǔ","en":"Friday","km":"ថ្ងៃសុក្រ"},{"hz":"星期天","py":"xīngqītiān","en":"Sunday","km":"ថ្ងៃអាទិត្យ"},{"hz":"……怎么样？","py":"… zěnmeyàng?","en":"How about …?","km":"…យ៉ាងម៉េចដែរ?"},{"hz":"不见不散","py":"bú jiàn bú sàn","en":"Be there! (we won't leave till we meet)","km":"មិនជួបមិនបែក (ត្រូវមកជួបគ្នា)"}],"tips":[{"label":"Days are numbers","html":"Monday to Saturday are just <span class=\"zh\">星期</span> + 1 to 6. Sunday is <span class=\"zh\">星期天</span> or <span class=\"zh\">星期日</span>. Many people also say <span class=\"zh\">周一</span>, <span class=\"zh\">周二</span>…","culture":false}]},
{"n":13,"ch":1,"title":"What's the Date?","titleZh":"今天几号？","titleKm":"ថ្ងៃនេះថ្ងៃទីប៉ុន្មាន?","art":"bank calendar suit m","scene":"You are filling in a form at a bank and need to write today's date.","dialogue":[{"who":"You","hz":"不好意思，今天几号？","py":"Bù hǎoyìsi, jīntiān jǐ hào?","en":"Excuse me, what's the date today?","km":"សុំទោស ថ្ងៃនេះថ្ងៃទីប៉ុន្មាន?"},{"who":"Clerk","hz":"今天十月五号。","py":"Jīntiān shí yuè wǔ hào.","en":"Today is the fifth of October.","km":"ថ្ងៃនេះថ្ងៃទីប្រាំ ខែតុលា។"},{"who":"You","hz":"日期要怎么写？","py":"Rìqī yào zěnme xiě?","en":"How should I write the date?","km":"កាលបរិច្ឆេទត្រូវសរសេរយ៉ាងម៉េច?"},{"who":"Clerk","hz":"先写年，再写月和日。","py":"Xiān xiě nián, zài xiě yuè hé rì.","en":"Write the year first, then the month and day.","km":"សរសេរឆ្នាំមុន បន្ទាប់មកខែ និងថ្ងៃ។"},{"who":"You","hz":"二零二六年十月五号，对吗？","py":"Èr líng èr liù nián shí yuè wǔ hào, duì ma?","en":"October 5th, 2026 — is that right?","km":"ថ្ងៃទីប្រាំ ខែតុលា ឆ្នាំ២០២៦ ត្រូវទេ?"},{"who":"Clerk","hz":"对。然后在这儿签名。","py":"Duì. Ránhòu zài zhèr qiānmíng.","en":"Right. Then sign here.","km":"ត្រូវហើយ។ បន្ទាប់មកចុះហត្ថលេខានៅទីនេះ។"}],"phrases":[{"hz":"今天几号？","py":"jīntiān jǐ hào?","en":"What's the date today?","km":"ថ្ងៃនេះថ្ងៃទីប៉ុន្មាន?"},{"hz":"十月五号","py":"shí yuè wǔ hào","en":"October 5th","km":"ថ្ងៃទីប្រាំ ខែតុលា"},{"hz":"二零二六年","py":"èr líng èr liù nián","en":"The year 2026","km":"ឆ្នាំ២០២៦"},{"hz":"昨天","py":"zuótiān","en":"Yesterday","km":"ម្សិលមិញ"},{"hz":"明天","py":"míngtiān","en":"Tomorrow","km":"ថ្ងៃស្អែក"},{"hz":"在这儿签名","py":"zài zhèr qiānmíng","en":"Sign here","km":"ចុះហត្ថលេខានៅទីនេះ"}],"tips":[{"label":"Big to small","html":"Chinese dates go from big to small: year → month → day → time. <span class=\"zh\">2026年10月5日</span>. Read years digit by digit: <em>èr líng èr liù</em>.","culture":false}]},
{"n":14,"ch":1,"title":"Phone Numbers","titleZh":"电话号码","titleKm":"លេខទូរសព្ទ","art":"shop phone uniform f","scene":"You are ordering a cake by phone and the shop assistant needs your number.","dialogue":[{"who":"Assistant","hz":"请留一下您的电话号码。","py":"Qǐng liú yíxià nín de diànhuà hàomǎ.","en":"Please leave your phone number.","km":"សូមទុកលេខទូរសព្ទរបស់អ្នក។"},{"who":"You","hz":"零一二，三四五，六七八。","py":"Líng yāo èr, sān sì wǔ, liù qī bā.","en":"012 345 678.","km":"សូន្យ មួយ ពីរ, បី បួន ប្រាំ, ប្រាំមួយ ប្រាំពីរ ប្រាំបី។"},{"who":"Assistant","hz":"零一二，三四五，六七八，对吗？","py":"Líng yāo èr, sān sì wǔ, liù qī bā, duì ma?","en":"012 345 678 — is that right?","km":"សូន្យ មួយ ពីរ, បី បួន ប្រាំ, ប្រាំមួយ ប្រាំពីរ ប្រាំបី ត្រូវទេ?"},{"who":"You","hz":"对。蛋糕几点可以拿？","py":"Duì. Dàngāo jǐ diǎn kěyǐ ná?","en":"Yes. What time can I pick up the cake?","km":"ត្រូវហើយ។ នំខេកម៉ោងប៉ុន្មានអាចមកយកបាន?"},{"who":"Assistant","hz":"明天下午四点以后。做好了我给您打电话。","py":"Míngtiān xiàwǔ sì diǎn yǐhòu. Zuò hǎo le wǒ gěi nín dǎ diànhuà.","en":"After 4 pm tomorrow. I'll call you when it's ready.","km":"ថ្ងៃស្អែក ក្រោយម៉ោងបួនរសៀល។ ធ្វើរួចខ្ញុំនឹងទូរសព្ទទៅអ្នក។"},{"who":"You","hz":"好的，麻烦你了。","py":"Hǎo de, máfan nǐ le.","en":"OK, thanks for your trouble.","km":"បាទ/ចាស រំខានអ្នកហើយ។"}],"phrases":[{"hz":"电话号码","py":"diànhuà hàomǎ","en":"Phone number","km":"លេខទូរសព្ទ"},{"hz":"请留一下电话","py":"qǐng liú yíxià diànhuà","en":"Please leave your number","km":"សូមទុកលេខទូរសព្ទ"},{"hz":"我给你打电话","py":"wǒ gěi nǐ dǎ diànhuà","en":"I'll call you","km":"ខ្ញុំនឹងទូរសព្ទទៅអ្នក"},{"hz":"零","py":"líng","en":"Zero","km":"សូន្យ"},{"hz":"下午","py":"xiàwǔ","en":"Afternoon","km":"រសៀល"},{"hz":"麻烦你了","py":"máfan nǐ le","en":"Sorry for the trouble / thanks","km":"រំខានអ្នកហើយ"}],"tips":[{"label":"Read digit by digit","html":"Phone numbers are read one digit at a time, often in groups of three or four. Remember <span class=\"zh\">一</span> becomes <em>yāo</em>.","culture":false}]},
{"n":15,"ch":1,"title":"Talking About the Weather","titleZh":"聊天气","titleKm":"និយាយអំពីអាកាសធាតុ","art":"park sunrain shirt f","scene":"You meet a friend in the park. The sky is getting dark.","dialogue":[{"who":"Friend","hz":"今天好热啊！","py":"Jīntiān hǎo rè a!","en":"It's so hot today!","km":"ថ្ងៃនេះក្តៅណាស់!"},{"who":"You","hz":"是啊，三十五度呢。","py":"Shì a, sānshíwǔ dù ne.","en":"Yes, it's thirty-five degrees.","km":"មែនហើយ សាមសិបប្រាំដឺក្រេ។"},{"who":"Friend","hz":"你看，天阴了，可能要下雨。","py":"Nǐ kàn, tiān yīn le, kěnéng yào xià yǔ.","en":"Look, it's clouding over — it might rain.","km":"មើលហ្ន៎ មេឃងងឹតហើយ ប្រហែលជាភ្លៀង។"},{"who":"You","hz":"天气预报说下午有雷阵雨。","py":"Tiānqì yùbào shuō xiàwǔ yǒu léizhènyǔ.","en":"The forecast says there'll be thunderstorms this afternoon.","km":"ព្យាករណ៍អាកាសធាតុថា រសៀលនេះមានភ្លៀងផ្គររន្ទះ។"},{"who":"Friend","hz":"你带伞了吗？","py":"Nǐ dài sǎn le ma?","en":"Did you bring an umbrella?","km":"អ្នកយកឆ័ត្រមកទេ?"},{"who":"You","hz":"带了。我们一起走吧。","py":"Dài le. Wǒmen yìqǐ zǒu ba.","en":"Yes. Let's walk together.","km":"យកមក។ យើងដើរជាមួយគ្នាទៅ។"}],"phrases":[{"hz":"今天天气怎么样？","py":"jīntiān tiānqì zěnmeyàng?","en":"What's the weather like today?","km":"ថ្ងៃនេះអាកាសធាតុយ៉ាងម៉េច?"},{"hz":"好热啊","py":"hǎo rè a","en":"It's so hot","km":"ក្តៅណាស់"},{"hz":"很冷","py":"hěn lěng","en":"Very cold","km":"ត្រជាក់ណាស់"},{"hz":"下雨","py":"xià yǔ","en":"To rain","km":"ភ្លៀង"},{"hz":"晴天","py":"qíngtiān","en":"Sunny day","km":"ថ្ងៃមេឃស្រឡះ"},{"hz":"天气预报","py":"tiānqì yùbào","en":"Weather forecast","km":"ព្យាករណ៍អាកាសធាតុ"}],"tips":[{"label":"Small talk starter","html":"Weather is a safe way to start a chat with anyone in Chinese — and so is <span class=\"zh\">吃了吗？</span> “have you eaten?”","culture":true}]},
{"n":16,"ch":1,"title":"Making an Appointment","titleZh":"约时间","titleKm":"ណាត់ពេល","art":"salon scissors apron f","scene":"You call a hair salon to book a haircut.","dialogue":[{"who":"Stylist","hz":"您好，美美发廊。","py":"Nín hǎo, Měiměi Fàláng.","en":"Hello, Meimei Hair Salon.","km":"ជម្រាបសួរ ហាងកាត់សក់ម៉ីម៉ី។"},{"who":"You","hz":"你好，我想预约剪头发。","py":"Nǐ hǎo, wǒ xiǎng yùyuē jiǎn tóufa.","en":"Hello, I'd like to book a haircut.","km":"សួស្តី ខ្ញុំចង់កក់កាត់សក់។"},{"who":"Stylist","hz":"您想约什么时候？","py":"Nín xiǎng yuē shénme shíhou?","en":"When would you like to come?","km":"តើអ្នកចង់ណាត់ពេលណា?"},{"who":"You","hz":"明天上午十点有空吗？","py":"Míngtiān shàngwǔ shí diǎn yǒu kòng ma?","en":"Are you free at 10 am tomorrow?","km":"ថ្ងៃស្អែក ម៉ោងដប់ព្រឹក ទំនេរទេ?"},{"who":"Stylist","hz":"十点满了，十一点可以吗？","py":"Shí diǎn mǎn le, shíyī diǎn kěyǐ ma?","en":"Ten is full — is eleven OK?","km":"ម៉ោងដប់ពេញហើយ ម៉ោងដប់មួយបានទេ?"},{"who":"You","hz":"可以。我叫索披。","py":"Kěyǐ. Wǒ jiào Suǒ Pī.","en":"That's fine. My name is Sophy.","km":"បាន។ ខ្ញុំឈ្មោះសុភី។"},{"who":"Stylist","hz":"好的，明天十一点见。","py":"Hǎo de, míngtiān shíyī diǎn jiàn.","en":"OK, see you tomorrow at eleven.","km":"បាទ/ចាស ជួបគ្នាថ្ងៃស្អែកម៉ោងដប់មួយ។"}],"phrases":[{"hz":"我想预约","py":"wǒ xiǎng yùyuē","en":"I'd like to make a booking","km":"ខ្ញុំចង់កក់ពេល"},{"hz":"什么时候？","py":"shénme shíhou?","en":"When?","km":"ពេលណា?"},{"hz":"有空吗？","py":"yǒu kòng ma?","en":"Are you free?","km":"ទំនេរទេ?"},{"hz":"上午","py":"shàngwǔ","en":"Morning (a.m.)","km":"ពេលព្រឹក"},{"hz":"满了","py":"mǎn le","en":"It's full","km":"ពេញហើយ"},{"hz":"……可以吗？","py":"… kěyǐ ma?","en":"Is … OK?","km":"…បានទេ?"}],"tips":[{"label":"Time before action","html":"Time words come before the verb: <span class=\"zh\">我明天十一点去</span> — “I tomorrow eleven o'clock go”.","culture":false}]},
{"n":17,"ch":1,"title":"Running Late","titleZh":"我要迟到了","titleKm":"ខ្ញុំនឹងមកយឺត","art":"street phone helmet m","scene":"You are stuck in traffic and will be late meeting a friend. You call to let him know.","dialogue":[{"who":"You","hz":"喂，大卫，我要迟到了。","py":"Wéi, Dàwèi, wǒ yào chídào le.","en":"Hello, David, I'm going to be late.","km":"អាឡូ ដាវីដ ខ្ញុំនឹងមកយឺតហើយ។"},{"who":"Friend","hz":"没事。你在哪儿？","py":"Méi shì. Nǐ zài nǎr?","en":"No problem. Where are you?","km":"មិនអីទេ។ អ្នកនៅឯណា?"},{"who":"You","hz":"我在路上，堵车堵得很厉害。","py":"Wǒ zài lùshang, dǔchē dǔ de hěn lìhai.","en":"I'm on the way — the traffic is terrible.","km":"ខ្ញុំនៅតាមផ្លូវ ស្ទះចរាចរណ៍ខ្លាំងណាស់។"},{"who":"Friend","hz":"大概还要多久？","py":"Dàgài hái yào duō jiǔ?","en":"About how much longer?","km":"ប្រហែលប៉ុន្មានទៀត?"},{"who":"You","hz":"二十分钟左右。真不好意思！","py":"Èrshí fēnzhōng zuǒyòu. Zhēn bù hǎoyìsi!","en":"Around twenty minutes. I'm really sorry!","km":"ប្រហែលម្ភៃនាទី។ សុំទោសណាស់!"},{"who":"Friend","hz":"别着急，我先点咖啡。","py":"Bié zháojí, wǒ xiān diǎn kāfēi.","en":"Don't worry, I'll order coffee first.","km":"កុំប្រញាប់ ខ្ញុំកុម្ម៉ង់កាហ្វេសិន។"}],"phrases":[{"hz":"我要迟到了","py":"wǒ yào chídào le","en":"I'm going to be late","km":"ខ្ញុំនឹងមកយឺតហើយ"},{"hz":"堵车","py":"dǔchē","en":"Traffic jam","km":"ស្ទះចរាចរណ៍"},{"hz":"还要多久？","py":"hái yào duō jiǔ?","en":"How much longer?","km":"ប៉ុន្មានទៀត?"},{"hz":"二十分钟左右","py":"èrshí fēnzhōng zuǒyòu","en":"About twenty minutes","km":"ប្រហែលម្ភៃនាទី"},{"hz":"别着急","py":"bié zháojí","en":"Don't worry / no rush","km":"កុំប្រញាប់"},{"hz":"喂","py":"wéi","en":"Hello (on the phone)","km":"អាឡូ"}],"tips":[{"label":"Phone hello","html":"On the phone, “hello” is <span class=\"zh\">喂</span> <em>wéi</em> — usually said with a rising tone — not <span class=\"zh\">你好</span>.","culture":false}]},
{"n":18,"ch":1,"title":"My Daily Routine","titleZh":"我的一天","titleKm":"មួយថ្ងៃរបស់ខ្ញុំ","art":"home clock shirt m","scene":"A Chinese friend staying with you asks about your usual day.","dialogue":[{"who":"Friend","hz":"你每天几点起床？","py":"Nǐ měi tiān jǐ diǎn qǐchuáng?","en":"What time do you get up every day?","km":"អ្នកក្រោកពីគេងម៉ោងប៉ុន្មានរៀងរាល់ថ្ងៃ?"},{"who":"You","hz":"六点起床，七点吃早饭。","py":"Liù diǎn qǐchuáng, qī diǎn chī zǎofàn.","en":"I get up at six and have breakfast at seven.","km":"ក្រោកម៉ោងប្រាំមួយ ញ៉ាំអាហារពេលព្រឹកម៉ោងប្រាំពីរ។"},{"who":"Friend","hz":"那么早！你几点上班？","py":"Nàme zǎo! Nǐ jǐ diǎn shàngbān?","en":"So early! What time do you start work?","km":"ព្រឹកម្ល៉េះ! អ្នកចូលធ្វើការម៉ោងប៉ុន្មាន?"},{"who":"You","hz":"八点上班，下午五点下班。","py":"Bā diǎn shàngbān, xiàwǔ wǔ diǎn xiàbān.","en":"I start at eight and finish at five.","km":"ចូលធ្វើការម៉ោងប្រាំបី ចេញពីការងារម៉ោងប្រាំល្ងាច។"},{"who":"Friend","hz":"下班以后你做什么？","py":"Xiàbān yǐhòu nǐ zuò shénme?","en":"What do you do after work?","km":"ក្រោយចេញពីការងារ អ្នកធ្វើអ្វី?"},{"who":"You","hz":"我去跑步，然后回家做饭。","py":"Wǒ qù pǎobù, ránhòu huí jiā zuò fàn.","en":"I go running, then go home and cook.","km":"ខ្ញុំទៅរត់ ហើយបន្ទាប់មកត្រឡប់ទៅផ្ទះធ្វើម្ហូប។"},{"who":"Friend","hz":"你一般几点睡觉？","py":"Nǐ yìbān jǐ diǎn shuìjiào?","en":"What time do you usually go to bed?","km":"ជាធម្មតាអ្នកចូលគេងម៉ោងប៉ុន្មាន?"},{"who":"You","hz":"十点半左右。","py":"Shí diǎn bàn zuǒyòu.","en":"Around half past ten.","km":"ប្រហែលម៉ោងដប់កន្លះ។"}],"phrases":[{"hz":"起床","py":"qǐchuáng","en":"To get up","km":"ក្រោកពីគេង"},{"hz":"吃早饭","py":"chī zǎofàn","en":"To eat breakfast","km":"ញ៉ាំអាហារពេលព្រឹក"},{"hz":"上班","py":"shàngbān","en":"To go to / start work","km":"ចូលធ្វើការ"},{"hz":"下班","py":"xiàbān","en":"To finish work","km":"ចេញពីការងារ"},{"hz":"睡觉","py":"shuìjiào","en":"To sleep / go to bed","km":"គេង"},{"hz":"然后","py":"ránhòu","en":"Then / after that","km":"បន្ទាប់មក"}],"tips":[{"label":"上 and 下","html":"<span class=\"zh\">上</span> (up) and <span class=\"zh\">下</span> (down) pair up: <span class=\"zh\">上班/下班</span> start/finish work, <span class=\"zh\">上课/下课</span> start/finish class.","culture":false}]},
{"n":19,"ch":1,"title":"Weekend Plans","titleZh":"周末计划","titleKm":"គម្រោងចុងសប្តាហ៍","art":"office calendar shirt f","scene":"It is Friday afternoon. A colleague asks what you are doing this weekend.","dialogue":[{"who":"Colleague","hz":"这个周末你有什么打算？","py":"Zhège zhōumò nǐ yǒu shénme dǎsuàn?","en":"What are your plans for this weekend?","km":"ចុងសប្តាហ៍នេះ អ្នកមានគម្រោងអ្វី?"},{"who":"You","hz":"星期六我要去看电影。","py":"Xīngqīliù wǒ yào qù kàn diànyǐng.","en":"On Saturday I'm going to see a movie.","km":"ថ្ងៃសៅរ៍ ខ្ញុំនឹងទៅមើលកុន។"},{"who":"Colleague","hz":"星期天呢？","py":"Xīngqītiān ne?","en":"And Sunday?","km":"ចុះថ្ងៃអាទិត្យ?"},{"who":"You","hz":"还没想好。可能在家休息。你呢？","py":"Hái méi xiǎng hǎo. Kěnéng zài jiā xiūxi. Nǐ ne?","en":"I haven't decided. Maybe rest at home. And you?","km":"មិនទាន់គិតរួចទេ។ ប្រហែលសម្រាកនៅផ្ទះ។ ចុះអ្នក?"},{"who":"Colleague","hz":"我们去海边玩儿，你想一起去吗？","py":"Wǒmen qù hǎibiān wánr, nǐ xiǎng yìqǐ qù ma?","en":"We're going to the beach — want to come?","km":"ពួកយើងទៅលេងមាត់សមុទ្រ អ្នកចង់ទៅជាមួយទេ?"},{"who":"You","hz":"好啊！几点出发？","py":"Hǎo a! Jǐ diǎn chūfā?","en":"Sure! What time are you leaving?","km":"បាន! ចេញដំណើរម៉ោងប៉ុន្មាន?"},{"who":"Colleague","hz":"早上八点，我开车来接你。","py":"Zǎoshang bā diǎn, wǒ kāichē lái jiē nǐ.","en":"Eight in the morning — I'll drive over and pick you up.","km":"ម៉ោងប្រាំបីព្រឹក ខ្ញុំបើកឡានមកទទួលអ្នក។"}],"phrases":[{"hz":"周末","py":"zhōumò","en":"Weekend","km":"ចុងសប្តាហ៍"},{"hz":"你有什么打算？","py":"nǐ yǒu shénme dǎsuàn?","en":"What are your plans?","km":"អ្នកមានគម្រោងអ្វី?"},{"hz":"看电影","py":"kàn diànyǐng","en":"To see a movie","km":"មើលកុន"},{"hz":"在家休息","py":"zài jiā xiūxi","en":"To rest at home","km":"សម្រាកនៅផ្ទះ"},{"hz":"你想一起去吗？","py":"nǐ xiǎng yìqǐ qù ma?","en":"Do you want to come along?","km":"អ្នកចង់ទៅជាមួយទេ?"},{"hz":"我来接你","py":"wǒ lái jiē nǐ","en":"I'll pick you up","km":"ខ្ញុំមកទទួលអ្នក"}],"tips":[{"label":"要 for plans","html":"<span class=\"zh\">要</span> before a verb means “going to”: <span class=\"zh\">我要去</span> = I'm going to go.","culture":false}]},
{"n":20,"ch":1,"title":"Chinese New Year","titleZh":"过春节","titleKm":"ការចូលឆ្នាំចិន","art":"street lantern shirt f","scene":"Red lanterns are everywhere. You visit a Chinese family on the first day of the new year.","dialogue":[{"who":"You","hz":"新年快乐！恭喜发财！","py":"Xīnnián kuàilè! Gōngxǐ fācái!","en":"Happy New Year! Wishing you wealth!","km":"សួស្តីឆ្នាំថ្មី! សូមឱ្យមានលុយច្រើន!"},{"who":"Auntie","hz":"新年快乐！快进来坐。","py":"Xīnnián kuàilè! Kuài jìnlái zuò.","en":"Happy New Year! Come in and sit down.","km":"សួស្តីឆ្នាំថ្មី! អញ្ជើញចូលមកអង្គុយ។"},{"who":"You","hz":"春节你们一般做什么？","py":"Chūnjié nǐmen yìbān zuò shénme?","en":"What do you usually do at Spring Festival?","km":"បុណ្យចូលឆ្នាំ ជាធម្មតាអ្នកធ្វើអ្វីខ្លះ?"},{"who":"Auntie","hz":"全家一起吃年夜饭，包饺子，给孩子红包。","py":"Quán jiā yìqǐ chī niányèfàn, bāo jiǎozi, gěi háizi hóngbāo.","en":"The whole family has the New Year's Eve dinner, makes dumplings and gives the kids red envelopes.","km":"គ្រួសារទាំងមូលញ៉ាំអាហារល្ងាចចូលឆ្នាំជាមួយគ្នា ខ្ចប់នំចំហុយ និងឱ្យអាំងប៉ាវដល់ក្មេងៗ។"},{"who":"You","hz":"在柬埔寨，很多人也过春节。","py":"Zài Jiǎnpǔzhài, hěn duō rén yě guò Chūnjié.","en":"In Cambodia, lots of people celebrate it too.","km":"នៅកម្ពុជា មនុស្សជាច្រើនក៏ចូលឆ្នាំចិនដែរ។"},{"who":"Auntie","hz":"真的吗？来，吃个饺子吧！","py":"Zhēn de ma? Lái, chī ge jiǎozi ba!","en":"Really? Here, have a dumpling!","km":"ពិតមែនឬ? មក ញ៉ាំនំចំហុយមួយទៅ!"}],"phrases":[{"hz":"新年快乐！","py":"xīnnián kuàilè!","en":"Happy New Year!","km":"សួស្តីឆ្នាំថ្មី!"},{"hz":"恭喜发财！","py":"gōngxǐ fācái!","en":"Wishing you wealth!","km":"សូមឱ្យរកស៊ីមានបាន!"},{"hz":"春节","py":"Chūnjié","en":"Spring Festival (Chinese New Year)","km":"បុណ្យចូលឆ្នាំចិន"},{"hz":"红包","py":"hóngbāo","en":"Red envelope (lucky money)","km":"អាំងប៉ាវ"},{"hz":"饺子","py":"jiǎozi","en":"Dumplings","km":"នំចំហុយ (ចៀវហ្ស៊ី)"},{"hz":"年夜饭","py":"niányèfàn","en":"New Year's Eve dinner","km":"អាហារល្ងាចចូលឆ្នាំ"}],"tips":[{"label":"Red for luck","html":"Red means luck and joy. Give and take red envelopes with both hands, and don't open them in front of the giver.","culture":true}]},
{"n":21,"ch":2,"title":"Ordering at a Restaurant","titleZh":"点菜","titleKm":"ការកុម្ម៉ង់ម្ហូប","art":"restaurant menu apron m","scene":"You sit down in a busy Chinese restaurant. The waiter brings a menu.","dialogue":[{"who":"Waiter","hz":"您好，几位？","py":"Nín hǎo, jǐ wèi?","en":"Hello, how many people?","km":"ជម្រាបសួរ ប៉ុន្មាននាក់?"},{"who":"You","hz":"两位。有菜单吗？","py":"Liǎng wèi. Yǒu càidān ma?","en":"Two. Do you have a menu?","km":"ពីរនាក់។ មានម៉ឺនុយទេ?"},{"who":"Waiter","hz":"这是菜单。您想吃点儿什么？","py":"Zhè shì càidān. Nín xiǎng chī diǎnr shénme?","en":"Here's the menu. What would you like to eat?","km":"នេះជាម៉ឺនុយ។ តើអ្នកចង់ញ៉ាំអ្វី?"},{"who":"You","hz":"你们有什么拿手菜？","py":"Nǐmen yǒu shénme náshǒu cài?","en":"What are your specialities?","km":"ហាងមានម្ហូបពិសេសអ្វីខ្លះ?"},{"who":"Waiter","hz":"宫保鸡丁和红烧鱼都很好吃。","py":"Gōngbǎo jīdīng hé hóngshāo yú dōu hěn hǎochī.","en":"Kung pao chicken and braised fish are both delicious.","km":"សាច់មាន់កុងប៉ាវ និងត្រីខសុទ្ធតែឆ្ងាញ់។"},{"who":"You","hz":"那我们要一个宫保鸡丁，两碗米饭。","py":"Nà wǒmen yào yí ge gōngbǎo jīdīng, liǎng wǎn mǐfàn.","en":"Then we'll have a kung pao chicken and two bowls of rice.","km":"ចឹងយើងយកសាច់មាន់កុងប៉ាវមួយ និងបាយពីរចាន។"},{"who":"Waiter","hz":"好的，喝点儿什么？","py":"Hǎo de, hē diǎnr shénme?","en":"OK, anything to drink?","km":"បាទ ចុះភេសជ្ជៈវិញ?"},{"who":"You","hz":"一壶绿茶，谢谢。","py":"Yì hú lǜchá, xièxie.","en":"A pot of green tea, thanks.","km":"តែបៃតងមួយប៉ាន់ អរគុណ។"}],"phrases":[{"hz":"几位？","py":"jǐ wèi?","en":"How many people?","km":"ប៉ុន្មាននាក់?"},{"hz":"菜单","py":"càidān","en":"Menu","km":"ម៉ឺនុយ"},{"hz":"我要……","py":"wǒ yào…","en":"I'd like…","km":"ខ្ញុំយក…"},{"hz":"一碗米饭","py":"yì wǎn mǐfàn","en":"A bowl of rice","km":"បាយមួយចាន"},{"hz":"好吃","py":"hǎochī","en":"Delicious","km":"ឆ្ងាញ់"},{"hz":"喝点儿什么？","py":"hē diǎnr shénme?","en":"What would you like to drink?","km":"ផឹកអ្វីដែរ?"}],"tips":[{"label":"Sharing dishes","html":"In China, dishes are put in the middle and everyone shares. Order about one dish per person, plus rice or noodles.","culture":true}]},
{"n":22,"ch":2,"title":"Not Too Spicy, Please","titleZh":"少放辣","titleKm":"សូមកុំហឹរពេក","art":"restaurant chili apron f","scene":"You order a Sichuan dish but you are worried it will be too hot.","dialogue":[{"who":"You","hz":"这个菜辣不辣？","py":"Zhège cài là bu là?","en":"Is this dish spicy?","km":"ម្ហូបនេះហឹរទេ?"},{"who":"Waitress","hz":"很辣，是四川菜。","py":"Hěn là, shì Sìchuān cài.","en":"Very spicy — it's Sichuan food.","km":"ហឹរណាស់ ជាម្ហូបស៊ីឈួន។"},{"who":"You","hz":"可以少放点儿辣椒吗？","py":"Kěyǐ shǎo fàng diǎnr làjiāo ma?","en":"Could you put in less chilli?","km":"អាចដាក់ម្ទេសតិចបន្តិចបានទេ?"},{"who":"Waitress","hz":"可以，做微辣的。还要别的吗？","py":"Kěyǐ, zuò wēi là de. Hái yào bié de ma?","en":"Sure, I'll make it mild. Anything else?","km":"បាន ធ្វើហឹរតិចៗ។ យកអ្វីផ្សេងទៀតទេ?"},{"who":"You","hz":"再要一个不辣的菜，有吗？","py":"Zài yào yí ge bú là de cài, yǒu ma?","en":"I'd also like a dish that isn't spicy — do you have one?","km":"យកម្ហូបមួយទៀតដែលមិនហឹរ មានទេ?"},{"who":"Waitress","hz":"番茄炒蛋，一点儿也不辣。","py":"Fānqié chǎo dàn, yìdiǎnr yě bú là.","en":"Tomato and egg stir-fry — not spicy at all.","km":"ពងមាន់ឆាប៉េងប៉ោះ មិនហឹរសោះ។"},{"who":"You","hz":"好，就要这个！","py":"Hǎo, jiù yào zhège!","en":"Great, I'll have that!","km":"ល្អ យកមួយនេះ!"}],"phrases":[{"hz":"辣不辣？","py":"là bu là?","en":"Is it spicy?","km":"ហឹរទេ?"},{"hz":"少放辣","py":"shǎo fàng là","en":"Less spicy","km":"ដាក់ហឹរតិច"},{"hz":"不要辣","py":"bú yào là","en":"No chilli","km":"កុំដាក់ហឹរ"},{"hz":"微辣","py":"wēi là","en":"Mildly spicy","km":"ហឹរតិចៗ"},{"hz":"还要别的吗？","py":"hái yào bié de ma?","en":"Anything else?","km":"យកអ្វីផ្សេងទៀតទេ?"},{"hz":"一点儿也不……","py":"yìdiǎnr yě bù…","en":"Not … at all","km":"មិន…សោះ"}],"tips":[{"label":"Spice levels","html":"Many restaurants let you choose <span class=\"zh\">微辣</span> mild, <span class=\"zh\">中辣</span> medium or <span class=\"zh\">特辣</span> extra hot. When in doubt, start with mild!","culture":false}]},
{"n":23,"ch":2,"title":"At the Bubble Tea Shop","titleZh":"买奶茶","titleKm":"ទិញតែទឹកដោះគោ","art":"cafe icedcoffee apron f","scene":"You are thirsty after school and go to a popular bubble tea shop.","dialogue":[{"who":"Staff","hz":"欢迎光临！要喝点儿什么？","py":"Huānyíng guānglín! Yào hē diǎnr shénme?","en":"Welcome! What would you like?","km":"សូមស្វាគមន៍! ចង់ផឹកអ្វីដែរ?"},{"who":"You","hz":"我要一杯珍珠奶茶。","py":"Wǒ yào yì bēi zhēnzhū nǎichá.","en":"I'd like a bubble milk tea.","km":"ខ្ញុំយកតែទឹកដោះគោគុជមួយកែវ។"},{"who":"Staff","hz":"大杯还是中杯？","py":"Dà bēi háishi zhōng bēi?","en":"Large or medium?","km":"កែវធំ ឬកែវមធ្យម?"},{"who":"You","hz":"大杯。少糖，少冰。","py":"Dà bēi. Shǎo táng, shǎo bīng.","en":"Large. Less sugar, less ice.","km":"កែវធំ។ ស្ករតិច ទឹកកកតិច។"},{"who":"Staff","hz":"在这儿喝还是带走？","py":"Zài zhèr hē háishi dàizǒu?","en":"For here or to go?","km":"ផឹកនៅទីនេះ ឬខ្ចប់យកទៅ?"},{"who":"You","hz":"带走。多少钱？","py":"Dàizǒu. Duōshao qián?","en":"To go. How much is it?","km":"ខ្ចប់យកទៅ។ ថ្លៃប៉ុន្មាន?"},{"who":"Staff","hz":"十五块。","py":"Shíwǔ kuài.","en":"Fifteen yuan.","km":"ដប់ប្រាំយ័ន។"}],"phrases":[{"hz":"一杯奶茶","py":"yì bēi nǎichá","en":"A cup of milk tea","km":"តែទឹកដោះគោមួយកែវ"},{"hz":"大杯还是中杯？","py":"dà bēi háishi zhōng bēi?","en":"Large or medium?","km":"កែវធំ ឬមធ្យម?"},{"hz":"少糖","py":"shǎo táng","en":"Less sugar","km":"ស្ករតិច"},{"hz":"去冰","py":"qù bīng","en":"No ice","km":"មិនដាក់ទឹកកក"},{"hz":"带走","py":"dàizǒu","en":"To take away","km":"ខ្ចប់យកទៅ"},{"hz":"多少钱？","py":"duōshao qián?","en":"How much is it?","km":"ថ្លៃប៉ុន្មាន?"}],"tips":[{"label":"还是 for choices","html":"In questions, “or” is <span class=\"zh\">还是</span>: <span class=\"zh\">茶还是咖啡？</span> tea or coffee?","culture":false}]},
{"n":24,"ch":2,"title":"Paying the Bill","titleZh":"买单","titleKm":"គិតលុយ","art":"restaurant receipt apron f","scene":"You have finished dinner with a Chinese friend. You call the waiter over for the bill.","dialogue":[{"who":"You","hz":"服务员，买单！","py":"Fúwùyuán, mǎidān!","en":"Waiter, the bill please!","km":"អ្នកបម្រើ សុំគិតលុយ!"},{"who":"Friend","hz":"我看看，一共两百八十块。","py":"Wǒ kànkan, yígòng liǎngbǎi bāshí kuài.","en":"Let me see — two hundred and eighty yuan altogether.","km":"ខ្ញុំមើលសិន សរុបពីររយប៉ែតសិបយ័ន។"},{"who":"Friend","hz":"我来，我来！今天我请客。","py":"Wǒ lái, wǒ lái! Jīntiān wǒ qǐngkè.","en":"Let me, let me! It's my treat today.","km":"ខ្ញុំ ខ្ញុំ! ថ្ងៃនេះខ្ញុំជាអ្នកចេញ។"},{"who":"You","hz":"不行，上次是你请的。这次我来。","py":"Bù xíng, shàng cì shì nǐ qǐng de. Zhè cì wǒ lái.","en":"No way — you paid last time. This time it's me.","km":"មិនបានទេ លើកមុនអ្នកចេញហើយ។ លើកនេះខ្ញុំវិញ។"},{"who":"Friend","hz":"那好吧，下次我请。","py":"Nà hǎo ba, xià cì wǒ qǐng.","en":"All right then, next time is on me.","km":"អញ្ចឹងក៏បាន លើកក្រោយខ្ញុំចេញ។"},{"who":"You","hz":"这儿可以扫码吗？","py":"Zhèr kěyǐ sǎo mǎ ma?","en":"Can you pay by QR code here?","km":"នៅទីនេះអាចស្កេនកូដបង់បានទេ?"},{"who":"Friend","hz":"可以，桌子上有二维码。","py":"Kěyǐ, zhuōzi shang yǒu èrwéimǎ.","en":"Yes, there's a QR code on the table.","km":"បាន មាន QR code នៅលើតុ។"}],"phrases":[{"hz":"买单！","py":"mǎidān!","en":"The bill, please!","km":"សុំគិតលុយ!"},{"hz":"一共多少钱？","py":"yígòng duōshao qián?","en":"How much altogether?","km":"សរុបប៉ុន្មាន?"},{"hz":"我请客","py":"wǒ qǐngkè","en":"It's my treat","km":"ខ្ញុំជាអ្នកចេញ"},{"hz":"下次我请","py":"xià cì wǒ qǐng","en":"Next time is on me","km":"លើកក្រោយខ្ញុំចេញ"},{"hz":"可以扫码吗？","py":"kěyǐ sǎo mǎ ma?","en":"Can I pay by QR code?","km":"អាចស្កេនកូដបានទេ?"},{"hz":"服务员","py":"fúwùyuán","en":"Waiter / waitress","km":"អ្នកបម្រើ"}],"tips":[{"label":"Fighting over the bill","html":"It is polite to try hard to pay — friends often “fight” for the bill. Splitting it is called <span class=\"zh\">AA制</span> <em>AA zhì</em>.","culture":true}]},
{"n":25,"ch":2,"title":"Breakfast at a Street Stall","titleZh":"吃早点","titleKm":"ញ៉ាំអាហារពេលព្រឹកនៅតូប","art":"stall bowl apron m e","scene":"Early in the morning you stop at a breakfast stall with steaming baskets.","dialogue":[{"who":"Uncle","hz":"早！吃点儿什么？","py":"Zǎo! Chī diǎnr shénme?","en":"Morning! What'll you have?","km":"អរុណសួស្តី! ញ៉ាំអ្វីដែរ?"},{"who":"You","hz":"包子是什么馅儿的？","py":"Bāozi shì shénme xiànr de?","en":"What's in the steamed buns?","km":"នំប៉ាវមានស្នូលអ្វី?"},{"who":"Uncle","hz":"有猪肉的，也有菜的。","py":"Yǒu zhūròu de, yě yǒu cài de.","en":"There's pork, and there's vegetable.","km":"មានសាច់ជ្រូក ហើយក៏មានបន្លែដែរ។"},{"who":"You","hz":"来两个肉包子，一杯豆浆。","py":"Lái liǎng ge ròu bāozi, yì bēi dòujiāng.","en":"Two meat buns and a soy milk, please.","km":"យកនំប៉ាវសាច់ពីរ និងទឹកសណ្តែកមួយកែវ។"},{"who":"Uncle","hz":"豆浆要甜的还是咸的？","py":"Dòujiāng yào tián de háishi xián de?","en":"Sweet or salty soy milk?","km":"ទឹកសណ្តែកយកផ្អែម ឬប្រៃ?"},{"who":"You","hz":"甜的。一共多少钱？","py":"Tián de. Yígòng duōshao qián?","en":"Sweet. How much altogether?","km":"ផ្អែម។ សរុបប៉ុន្មាន?"},{"who":"Uncle","hz":"八块。慢走！","py":"Bā kuài. Màn zǒu!","en":"Eight yuan. Take care!","km":"ប្រាំបីយ័ន។ ដើរយឺតៗ!"}],"phrases":[{"hz":"早点 / 早饭","py":"zǎodiǎn / zǎofàn","en":"Breakfast","km":"អាហារពេលព្រឹក"},{"hz":"包子","py":"bāozi","en":"Steamed bun","km":"នំប៉ាវ"},{"hz":"豆浆","py":"dòujiāng","en":"Soy milk","km":"ទឹកសណ្តែក"},{"hz":"来两个……","py":"lái liǎng ge…","en":"Give me two…","km":"យកពីរ…"},{"hz":"甜的还是咸的？","py":"tián de háishi xián de?","en":"Sweet or salty?","km":"ផ្អែម ឬប្រៃ?"},{"hz":"慢走","py":"màn zǒu","en":"Take care (when leaving)","km":"ដើរយឺតៗ / ធ្វើដំណើរប្រុងប្រយ័ត្ន"}],"tips":[{"label":"来 = give me","html":"In shops and stalls, <span class=\"zh\">来</span> + number means “give me”: <span class=\"zh\">来一碗面</span> — a bowl of noodles, please.","culture":false}]},
{"n":26,"ch":2,"title":"Invited for Dinner","titleZh":"请你来我家吃饭","titleKm":"អញ្ជើញមកញ៉ាំបាយនៅផ្ទះ","art":"home bowl shirt f","scene":"Your Chinese friend Lina has cooked dinner for you at her flat.","dialogue":[{"who":"Lina","hz":"菜做好了，快来吃吧！","py":"Cài zuò hǎo le, kuài lái chī ba!","en":"The food's ready, come and eat!","km":"ម្ហូបធ្វើរួចហើយ មកញ៉ាំលឿនៗ!"},{"who":"You","hz":"哇，这么多菜！你太厉害了。","py":"Wā, zhème duō cài! Nǐ tài lìhai le.","en":"Wow, so many dishes! You're amazing.","km":"វ៉ាវ ម្ហូបច្រើនម្ល៉េះ! អ្នកពូកែណាស់។"},{"who":"Lina","hz":"都是家常菜。别客气，多吃点儿！","py":"Dōu shì jiāchángcài. Bié kèqi, duō chī diǎnr!","en":"It's just home cooking. Don't be shy — eat more!","km":"សុទ្ធតែម្ហូបធម្មតាៗ។ កុំគួរសម ញ៉ាំច្រើនៗ!"},{"who":"You","hz":"这个鱼真好吃！怎么做的？","py":"Zhège yú zhēn hǎochī! Zěnme zuò de?","en":"This fish is really tasty! How did you make it?","km":"ត្រីនេះឆ្ងាញ់ណាស់! ធ្វើយ៉ាងម៉េច?"},{"who":"Lina","hz":"很简单，用姜、葱和酱油蒸的。","py":"Hěn jiǎndān, yòng jiāng, cōng hé jiàngyóu zhēng de.","en":"It's easy — steamed with ginger, spring onion and soy sauce.","km":"ងាយណាស់ ចំហុយជាមួយខ្ញី ស្លឹកខ្ទឹម និងទឹកស៊ីអ៊ីវ។"},{"who":"You","hz":"我吃饱了，谢谢你的招待！","py":"Wǒ chī bǎo le, xièxie nǐ de zhāodài!","en":"I'm full — thank you for having me!","km":"ខ្ញុំឆ្អែតហើយ អរគុណសម្រាប់ការទទួលស្វាគមន៍!"}],"phrases":[{"hz":"快来吃吧","py":"kuài lái chī ba","en":"Come and eat","km":"មកញ៉ាំលឿនៗ"},{"hz":"别客气","py":"bié kèqi","en":"Don't be polite / help yourself","km":"កុំគួរសម"},{"hz":"多吃点儿","py":"duō chī diǎnr","en":"Eat more","km":"ញ៉ាំច្រើនៗ"},{"hz":"怎么做的？","py":"zěnme zuò de?","en":"How did you make it?","km":"ធ្វើយ៉ាងម៉េច?"},{"hz":"我吃饱了","py":"wǒ chī bǎo le","en":"I'm full","km":"ខ្ញុំឆ្អែតហើយ"},{"hz":"谢谢你的招待","py":"xièxie nǐ de zhāodài","en":"Thank you for your hospitality","km":"អរគុណសម្រាប់ការទទួលស្វាគមន៍"}],"tips":[{"label":"Chopstick manners","html":"Never stand chopsticks upright in rice — it looks like incense at a funeral. Rest them across your bowl instead.","culture":true}]},
{"n":27,"ch":2,"title":"Ordering Food Delivery","titleZh":"叫外卖","titleKm":"កុម្ម៉ង់ម្ហូបតាមអនឡាញ","art":"home foodbag helmet m","scene":"The delivery rider calls you because he cannot find your building.","dialogue":[{"who":"Rider","hz":"喂，您好，您的外卖到了。","py":"Wéi, nín hǎo, nín de wàimài dào le.","en":"Hello, your food delivery is here.","km":"អាឡូ ជម្រាបសួរ ម្ហូបដែលអ្នកកុម្ម៉ង់មកដល់ហើយ។"},{"who":"You","hz":"好的，你在哪儿？","py":"Hǎo de, nǐ zài nǎr?","en":"OK, where are you?","km":"បាទ អ្នកនៅឯណា?"},{"who":"Rider","hz":"我在小区门口，找不到三号楼。","py":"Wǒ zài xiǎoqū ménkǒu, zhǎo bu dào sān hào lóu.","en":"I'm at the estate gate, I can't find Building 3.","km":"ខ្ញុំនៅមាត់ទ្វារបុរី រកអគារលេខបីមិនឃើញ។"},{"who":"You","hz":"进门以后往右走，第二个楼就是。","py":"Jìn mén yǐhòu wǎng yòu zǒu, dì-èr ge lóu jiù shì.","en":"After the gate turn right — it's the second building.","km":"ចូលទ្វារហើយ បត់ទៅស្តាំ អគារទីពីរគឺហ្នឹងហើយ។"},{"who":"Rider","hz":"好，几楼？","py":"Hǎo, jǐ lóu?","en":"OK, which floor?","km":"បាទ ជាន់ទីប៉ុន្មាន?"},{"who":"You","hz":"五楼，五零二。我下来拿吧。","py":"Wǔ lóu, wǔ líng èr. Wǒ xiàlái ná ba.","en":"Fifth floor, 502. I'll come down and get it.","km":"ជាន់ទីប្រាំ បន្ទប់ ៥០២។ ខ្ញុំចុះមកយកចុះ។"},{"who":"Rider","hz":"好的，我在楼下等您。","py":"Hǎo de, wǒ zài lóuxià děng nín.","en":"OK, I'll wait for you downstairs.","km":"បាទ ខ្ញុំរង់ចាំអ្នកនៅខាងក្រោម។"}],"phrases":[{"hz":"外卖","py":"wàimài","en":"Food delivery / takeaway","km":"ម្ហូបដឹកជញ្ជូន"},{"hz":"到了","py":"dào le","en":"It has arrived","km":"មកដល់ហើយ"},{"hz":"找不到","py":"zhǎo bu dào","en":"Can't find","km":"រកមិនឃើញ"},{"hz":"往右走","py":"wǎng yòu zǒu","en":"Go to the right","km":"បត់ទៅស្តាំ"},{"hz":"几楼？","py":"jǐ lóu?","en":"Which floor?","km":"ជាន់ទីប៉ុន្មាន?"},{"hz":"我下来拿","py":"wǒ xiàlái ná","en":"I'll come down for it","km":"ខ្ញុំចុះមកយក"}],"tips":[{"label":"Complements of result","html":"<span class=\"zh\">找到</span> = find (successfully); <span class=\"zh\">找不到</span> = can't find. The same pattern gives <span class=\"zh\">听不懂</span>, <span class=\"zh\">看不见</span>.","culture":false}]},
{"n":28,"ch":2,"title":"I Don't Eat Meat","titleZh":"我吃素","titleKm":"ខ្ញុំមិនញ៉ាំសាច់","art":"restaurant leaf apron f","scene":"You are vegetarian and need to check what is in each dish.","dialogue":[{"who":"You","hz":"不好意思，我吃素。哪些菜没有肉？","py":"Bù hǎoyìsi, wǒ chī sù. Nǎxiē cài méiyǒu ròu?","en":"Excuse me, I'm vegetarian. Which dishes have no meat?","km":"សុំទោស ខ្ញុំញ៉ាំបួស។ ម្ហូបណាខ្លះគ្មានសាច់?"},{"who":"Waitress","hz":"麻婆豆腐里有一点儿牛肉。","py":"Mápó dòufu li yǒu yìdiǎnr niúròu.","en":"Mapo tofu has a little beef in it.","km":"តៅហ៊ូម៉ាប៉ូមានសាច់គោបន្តិច។"},{"who":"You","hz":"能不放肉吗？","py":"Néng bú fàng ròu ma?","en":"Can you make it without meat?","km":"អាចមិនដាក់សាច់បានទេ?"},{"who":"Waitress","hz":"可以，做素的。炒青菜也没有肉。","py":"Kěyǐ, zuò sù de. Chǎo qīngcài yě méiyǒu ròu.","en":"Yes, we'll make it vegetarian. The stir-fried greens have no meat either.","km":"បាន ធ្វើបួស។ បន្លែឆាក៏គ្មានសាច់ដែរ។"},{"who":"You","hz":"太好了，这两个都要。","py":"Tài hǎo le, zhè liǎng ge dōu yào.","en":"Great, I'll take both of those.","km":"ល្អណាស់ យកទាំងពីរមុខនេះ។"},{"who":"Waitress","hz":"好，我告诉厨师。","py":"Hǎo, wǒ gàosu chúshī.","en":"OK, I'll tell the chef.","km":"បាទ ខ្ញុំប្រាប់ចុងភៅ។"}],"phrases":[{"hz":"我吃素","py":"wǒ chī sù","en":"I'm vegetarian","km":"ខ្ញុំញ៉ាំបួស"},{"hz":"没有肉","py":"méiyǒu ròu","en":"Without meat","km":"គ្មានសាច់"},{"hz":"不放……","py":"bú fàng…","en":"Don't put in…","km":"កុំដាក់…"},{"hz":"牛肉","py":"niúròu","en":"Beef","km":"សាច់គោ"},{"hz":"猪肉","py":"zhūròu","en":"Pork","km":"សាច់ជ្រូក"},{"hz":"鸡肉","py":"jīròu","en":"Chicken","km":"សាច់មាន់"}],"tips":[{"label":"Ask about the sauce","html":"Some vegetable dishes are cooked with meat stock or oyster sauce. Ask: <span class=\"zh\">有没有放肉汤？</span> — “is there meat stock in it?”","culture":false}]},
{"n":29,"ch":2,"title":"Cheers! A Dinner Toast","titleZh":"干杯","titleKm":"លើកកែវ!","art":"restaurant drinks suit m","scene":"At a company dinner, your manager stands up and raises a glass.","dialogue":[{"who":"Manager","hz":"来，大家一起干杯！","py":"Lái, dàjiā yìqǐ gānbēi!","en":"Come on, everyone — cheers!","km":"មក ទាំងអស់គ្នាលើកកែវ!"},{"who":"You","hz":"干杯！祝大家身体健康！","py":"Gānbēi! Zhù dàjiā shēntǐ jiànkāng!","en":"Cheers! To everyone's health!","km":"លើកកែវ! សូមឱ្យទាំងអស់គ្នាមានសុខភាពល្អ!"},{"who":"Manager","hz":"你今年工作很努力，谢谢你。","py":"Nǐ jīnnián gōngzuò hěn nǔlì, xièxie nǐ.","en":"You worked very hard this year — thank you.","km":"ឆ្នាំនេះអ្នកធ្វើការខិតខំណាស់ អរគុណអ្នក។"},{"who":"You","hz":"谢谢经理！我敬您一杯。","py":"Xièxie jīnglǐ! Wǒ jìng nín yì bēi.","en":"Thank you, sir! A toast to you.","km":"អរគុណលោកនាយក! ខ្ញុំសូមលើកកែវគោរពលោក។"},{"who":"Manager","hz":"好！你随意，我干了。","py":"Hǎo! Nǐ suíyì, wǒ gān le.","en":"Good! Drink as much as you like — I'll finish mine.","km":"ល្អ! អ្នកផឹកតាមចិត្ត ខ្ញុំផឹកអស់។"},{"who":"You","hz":"我不太会喝酒，我喝果汁吧。","py":"Wǒ bú tài huì hē jiǔ, wǒ hē guǒzhī ba.","en":"I don't really drink — I'll have juice.","km":"ខ្ញុំមិនសូវចេះផឹកស្រាទេ ខ្ញុំផឹកទឹកផ្លែឈើវិញ។"}],"phrases":[{"hz":"干杯！","py":"gānbēi!","en":"Cheers!","km":"លើកកែវ!"},{"hz":"祝你身体健康","py":"zhù nǐ shēntǐ jiànkāng","en":"Wishing you good health","km":"សូមឱ្យអ្នកមានសុខភាពល្អ"},{"hz":"我敬你一杯","py":"wǒ jìng nǐ yì bēi","en":"A toast to you","km":"ខ្ញុំសូមលើកកែវជូនអ្នក"},{"hz":"随意","py":"suíyì","en":"As you like (drink a little)","km":"តាមចិត្ត"},{"hz":"我不太会喝酒","py":"wǒ bú tài huì hē jiǔ","en":"I don't really drink alcohol","km":"ខ្ញុំមិនសូវចេះផឹកស្រា"},{"hz":"果汁","py":"guǒzhī","en":"Fruit juice","km":"ទឹកផ្លែឈើ"}],"tips":[{"label":"Glass a little lower","html":"When you clink glasses with someone senior, hold your glass a little lower than theirs to show respect.","culture":true}]},
{"n":30,"ch":2,"title":"My Favourite Food","titleZh":"我最喜欢的菜","titleKm":"ម្ហូបដែលខ្ញុំចូលចិត្តបំផុត","art":"cafe rice shirt m","scene":"Over lunch, a Chinese classmate asks what Cambodian food you like.","dialogue":[{"who":"Classmate","hz":"你最喜欢吃什么？","py":"Nǐ zuì xǐhuan chī shénme?","en":"What do you like to eat most?","km":"អ្នកចូលចិត្តញ៉ាំអ្វីជាងគេ?"},{"who":"You","hz":"我最喜欢吃阿莫克鱼。","py":"Wǒ zuì xǐhuan chī Āmòkè yú.","en":"My favourite is fish amok.","km":"ខ្ញុំចូលចិត្តញ៉ាំអាម៉ុកត្រីជាងគេ។"},{"who":"Classmate","hz":"阿莫克是什么？","py":"Āmòkè shì shénme?","en":"What's amok?","km":"អាម៉ុកជាអ្វី?"},{"who":"You","hz":"是柬埔寨菜，用椰奶和香料做的，有点儿像咖喱。","py":"Shì Jiǎnpǔzhài cài, yòng yēnǎi hé xiāngliào zuò de, yǒudiǎnr xiàng gālí.","en":"It's Cambodian — made with coconut milk and spices, a bit like curry.","km":"ជាម្ហូបខ្មែរ ធ្វើពីខ្ទិះដូង និងគ្រឿង ប្រហាក់ប្រហែលការី។"},{"who":"Classmate","hz":"听起来很好吃！我喜欢吃饺子。","py":"Tīng qǐlai hěn hǎochī! Wǒ xǐhuan chī jiǎozi.","en":"Sounds delicious! I like dumplings.","km":"ស្តាប់ទៅឆ្ងាញ់ណាស់! ខ្ញុំចូលចិត្តនំចំហុយ។"},{"who":"You","hz":"下次我们一起去吃柬埔寨菜吧！","py":"Xià cì wǒmen yìqǐ qù chī Jiǎnpǔzhài cài ba!","en":"Next time let's go and eat Cambodian food together!","km":"លើកក្រោយ យើងទៅញ៉ាំម្ហូបខ្មែរជាមួយគ្នាណា!"}],"phrases":[{"hz":"你最喜欢吃什么？","py":"nǐ zuì xǐhuan chī shénme?","en":"What's your favourite food?","km":"អ្នកចូលចិត្តញ៉ាំអ្វីជាងគេ?"},{"hz":"我最喜欢……","py":"wǒ zuì xǐhuan…","en":"I like … most","km":"ខ្ញុំចូលចិត្ត…ជាងគេ"},{"hz":"有点儿像……","py":"yǒudiǎnr xiàng…","en":"A bit like…","km":"ប្រហាក់ប្រហែល…"},{"hz":"听起来很好吃","py":"tīng qǐlai hěn hǎochī","en":"Sounds delicious","km":"ស្តាប់ទៅឆ្ងាញ់"},{"hz":"甜 / 酸 / 咸","py":"tián / suān / xián","en":"Sweet / sour / salty","km":"ផ្អែម / ជូរ / ប្រៃ"},{"hz":"柬埔寨菜","py":"Jiǎnpǔzhài cài","en":"Cambodian food","km":"ម្ហូបខ្មែរ"}],"tips":[{"label":"最 = most","html":"Put <span class=\"zh\">最</span> before an adjective or verb for “most”: <span class=\"zh\">最好</span> best, <span class=\"zh\">最喜欢</span> like most.","culture":false}]},
{"n":31,"ch":3,"title":"How Much Is It?","titleZh":"多少钱？","titleKm":"ថ្លៃប៉ុន្មាន?","art":"shop tag uniform f","scene":"You are looking at water bottles in a small shop.","dialogue":[{"who":"You","hz":"请问，这个多少钱？","py":"Qǐngwèn, zhège duōshao qián?","en":"Excuse me, how much is this?","km":"សុំសួរ មួយនេះថ្លៃប៉ុន្មាន?"},{"who":"Assistant","hz":"这个三十五块。","py":"Zhège sānshíwǔ kuài.","en":"This one is thirty-five yuan.","km":"មួយនេះសាមសិបប្រាំយ័ន។"},{"who":"You","hz":"那个蓝色的呢？","py":"Nàge lánsè de ne?","en":"What about that blue one?","km":"ចុះមួយពណ៌ខៀវនោះ?"},{"who":"Assistant","hz":"那个贵一点儿，四十八块。","py":"Nàge guì yìdiǎnr, sìshíbā kuài.","en":"That one is a bit more expensive — forty-eight.","km":"មួយនោះថ្លៃជាងបន្តិច សែសិបប្រាំបីយ័ន។"},{"who":"You","hz":"我要这个便宜的。","py":"Wǒ yào zhège piányi de.","en":"I'll take this cheaper one.","km":"ខ្ញុំយកមួយនេះដែលថោក។"},{"who":"Assistant","hz":"好的，还要别的吗？","py":"Hǎo de, hái yào bié de ma?","en":"OK, anything else?","km":"បាទ/ចាស យកអ្វីផ្សេងទៀតទេ?"},{"who":"You","hz":"不要了，谢谢。","py":"Bú yào le, xièxie.","en":"No, that's all, thanks.","km":"អត់ទេ អរគុណ។"}],"phrases":[{"hz":"多少钱？","py":"duōshao qián?","en":"How much?","km":"ថ្លៃប៉ុន្មាន?"},{"hz":"这个 / 那个","py":"zhège / nàge","en":"This one / that one","km":"មួយនេះ / មួយនោះ"},{"hz":"块","py":"kuài","en":"Yuan (spoken)","km":"យ័ន (ពាក្យនិយាយ)"},{"hz":"贵","py":"guì","en":"Expensive","km":"ថ្លៃ"},{"hz":"便宜","py":"piányi","en":"Cheap","km":"ថោក"},{"hz":"不要了","py":"bú yào le","en":"No more, thanks","km":"មិនយកទៀតទេ"}],"tips":[{"label":"Money words","html":"Written: <span class=\"zh\">元 / 角</span>. Spoken: <span class=\"zh\">块 / 毛</span>. ¥3.50 is <span class=\"zh\">三块五</span> <em>sān kuài wǔ</em>.","culture":false}]},
{"n":32,"ch":3,"title":"Bargaining at the Market","titleZh":"讲价","titleKm":"ការតថ្លៃ","art":"market money hat f e","scene":"At a tourist market you like a silk scarf, but the price seems high.","dialogue":[{"who":"You","hz":"这条围巾多少钱？","py":"Zhè tiáo wéijīn duōshao qián?","en":"How much is this scarf?","km":"កន្សែងបង់កមួយនេះថ្លៃប៉ុន្មាន?"},{"who":"Seller","hz":"一百二。真丝的！","py":"Yìbǎi èr. Zhēnsī de!","en":"A hundred and twenty. It's real silk!","km":"មួយរយម្ភៃ។ សូត្រសុទ្ធ!"},{"who":"You","hz":"太贵了！便宜一点儿吧。","py":"Tài guì le! Piányi yìdiǎnr ba.","en":"Too expensive! Make it a bit cheaper.","km":"ថ្លៃពេក! ចុះថោកបន្តិចមក។"},{"who":"Seller","hz":"你说多少？","py":"Nǐ shuō duōshao?","en":"How much do you say?","km":"អ្នកថាប៉ុន្មាន?"},{"who":"You","hz":"六十块，行吗？","py":"Liùshí kuài, xíng ma?","en":"Sixty yuan, OK?","km":"ហុកសិបយ័ន បានទេ?"},{"who":"Seller","hz":"六十太少了。八十吧，最低价。","py":"Liùshí tài shǎo le. Bāshí ba, zuì dī jià.","en":"Sixty is too little. Eighty — lowest price.","km":"ហុកសិបតិចពេក។ ប៉ែតសិបចុះ តម្លៃទាបបំផុត។"},{"who":"You","hz":"七十，我买两条。","py":"Qīshí, wǒ mǎi liǎng tiáo.","en":"Seventy each and I'll buy two.","km":"ចិតសិប ខ្ញុំទិញពីរ។"},{"who":"Seller","hz":"好吧，成交！","py":"Hǎo ba, chéngjiāo!","en":"All right — deal!","km":"ក៏បាន ព្រមលក់!"}],"phrases":[{"hz":"太贵了！","py":"tài guì le!","en":"Too expensive!","km":"ថ្លៃពេក!"},{"hz":"便宜一点儿吧","py":"piányi yìdiǎnr ba","en":"Make it cheaper","km":"ចុះថោកបន្តិចមក"},{"hz":"……行吗？","py":"… xíng ma?","en":"Is … OK?","km":"…បានទេ?"},{"hz":"最低价","py":"zuì dī jià","en":"Lowest price","km":"តម្លៃទាបបំផុត"},{"hz":"成交！","py":"chéngjiāo!","en":"Deal!","km":"ព្រមលក់!"},{"hz":"一条围巾","py":"yì tiáo wéijīn","en":"A scarf","km":"កន្សែងបង់កមួយ"}],"tips":[{"label":"Where to bargain","html":"Bargain at markets and small stalls, not in supermarkets or chain stores where prices are fixed.","culture":true},{"label":"Short prices","html":"<span class=\"zh\">一百二</span> means 120, not 102. For 102 say <span class=\"zh\">一百零二</span>.","culture":false}]},
{"n":33,"ch":3,"title":"Buying Clothes","titleZh":"买衣服","titleKm":"ទិញសម្លៀកបំពាក់","art":"shop shirt uniform f","scene":"You find a shirt you like in a clothes shop and want to try it on.","dialogue":[{"who":"You","hz":"这件衬衫有大号的吗？","py":"Zhè jiàn chènshān yǒu dà hào de ma?","en":"Do you have this shirt in a large?","km":"អាវនេះមានលេខធំទេ?"},{"who":"Assistant","hz":"有。您穿多大的？","py":"Yǒu. Nín chuān duō dà de?","en":"Yes. What size do you wear?","km":"មាន។ អ្នកពាក់លេខប៉ុន្មាន?"},{"who":"You","hz":"我穿L号。可以试试吗？","py":"Wǒ chuān L hào. Kěyǐ shìshi ma?","en":"I wear an L. Can I try it on?","km":"ខ្ញុំពាក់លេខ L។ អាចសាកបានទេ?"},{"who":"Assistant","hz":"可以，试衣间在那边。","py":"Kěyǐ, shìyījiān zài nàbiān.","en":"Sure, the fitting room is over there.","km":"បាន បន្ទប់សាកនៅខាងនោះ។"},{"who":"You","hz":"有点儿小。有没有再大一点儿的？","py":"Yǒudiǎnr xiǎo. Yǒu méiyǒu zài dà yìdiǎnr de?","en":"It's a bit small. Is there a bigger one?","km":"តូចបន្តិច។ មានធំជាងនេះបន្តិចទេ?"},{"who":"Assistant","hz":"这件XL的，您试试。","py":"Zhè jiàn XL de, nín shìshi.","en":"Try this XL.","km":"នេះលេខ XL សាកមើល។"},{"who":"You","hz":"正合适！就要这件。","py":"Zhèng héshì! Jiù yào zhè jiàn.","en":"It fits perfectly! I'll take it.","km":"ត្រូវល្មមតែម្តង! យកមួយនេះ។"}],"phrases":[{"hz":"可以试试吗？","py":"kěyǐ shìshi ma?","en":"Can I try it on?","km":"អាចសាកបានទេ?"},{"hz":"试衣间","py":"shìyījiān","en":"Fitting room","km":"បន្ទប់សាកសម្លៀកបំពាក់"},{"hz":"有点儿小 / 大","py":"yǒudiǎnr xiǎo / dà","en":"A bit small / big","km":"តូច / ធំបន្តិច"},{"hz":"正合适","py":"zhèng héshì","en":"It fits perfectly","km":"ត្រូវល្មម"},{"hz":"一件衬衫","py":"yí jiàn chènshān","en":"A shirt","km":"អាវមួយ"},{"hz":"大号 / 中号 / 小号","py":"dà hào / zhōng hào / xiǎo hào","en":"Large / medium / small","km":"លេខធំ / មធ្យម / តូច"}],"tips":[{"label":"Try it: verb + verb","html":"Doubling a verb softens it: <span class=\"zh\">试试</span> “have a try”, <span class=\"zh\">看看</span> “have a look”.","culture":false}]},
{"n":34,"ch":3,"title":"Shoes and Colours","titleZh":"买鞋","titleKm":"ទិញស្បែកជើង","art":"shop tag uniform m","scene":"You are buying running shoes and want a different colour.","dialogue":[{"who":"Assistant","hz":"您想买什么鞋？","py":"Nín xiǎng mǎi shénme xié?","en":"What kind of shoes are you looking for?","km":"តើអ្នកចង់ទិញស្បែកជើងប្រភេទអ្វី?"},{"who":"You","hz":"我想买一双跑步鞋。","py":"Wǒ xiǎng mǎi yì shuāng pǎobù xié.","en":"I'd like a pair of running shoes.","km":"ខ្ញុំចង់ទិញស្បែកជើងរត់មួយគូ។"},{"who":"Assistant","hz":"这双怎么样？现在打八折。","py":"Zhè shuāng zěnmeyàng? Xiànzài dǎ bā zhé.","en":"How about these? They're 20% off now.","km":"មួយគូនេះយ៉ាងម៉េចដែរ? ឥឡូវបញ្ចុះតម្លៃ ២០%។"},{"who":"You","hz":"样子不错，有没有白色的？","py":"Yàngzi búcuò, yǒu méiyǒu báisè de?","en":"Nice style. Do you have them in white?","km":"ម៉ូដល្អ។ មានពណ៌សទេ?"},{"who":"Assistant","hz":"白色的卖完了，有黑色和红色的。","py":"Báisè de mài wán le, yǒu hēisè hé hóngsè de.","en":"White is sold out; we have black and red.","km":"ពណ៌សលក់អស់ហើយ មានពណ៌ខ្មៅ និងក្រហម។"},{"who":"You","hz":"那我要黑色的，三十九码。","py":"Nà wǒ yào hēisè de, sānshíjiǔ mǎ.","en":"Then I'll take black, size 39.","km":"អញ្ចឹងខ្ញុំយកពណ៌ខ្មៅ លេខ ៣៩។"}],"phrases":[{"hz":"一双鞋","py":"yì shuāng xié","en":"A pair of shoes","km":"ស្បែកជើងមួយគូ"},{"hz":"打八折","py":"dǎ bā zhé","en":"20% off (pay 80%)","km":"បញ្ចុះតម្លៃ ២០%"},{"hz":"有没有……的？","py":"yǒu méiyǒu … de?","en":"Do you have a … one?","km":"មាន…ទេ?"},{"hz":"卖完了","py":"mài wán le","en":"Sold out","km":"លក់អស់ហើយ"},{"hz":"白色 / 黑色 / 红色","py":"báisè / hēisè / hóngsè","en":"White / black / red","km":"ពណ៌ស / ខ្មៅ / ក្រហម"},{"hz":"三十九码","py":"sānshíjiǔ mǎ","en":"Size 39","km":"លេខ ៣៩"}],"tips":[{"label":"Discounts backwards","html":"<span class=\"zh\">打八折</span> means you pay 80%, so it's 20% off. <span class=\"zh\">打五折</span> = half price.","culture":false}]},
{"n":35,"ch":3,"title":"At the Supermarket","titleZh":"在超市","titleKm":"នៅផ្សារទំនើប","art":"shop basket uniform m","scene":"You cannot find what you need in a big supermarket, so you ask a staff member.","dialogue":[{"who":"You","hz":"请问，牛奶在哪儿？","py":"Qǐngwèn, niúnǎi zài nǎr?","en":"Excuse me, where is the milk?","km":"សុំសួរ ទឹកដោះគោនៅឯណា?"},{"who":"Staff","hz":"在最后一排，冰柜里。","py":"Zài zuìhòu yì pái, bīngguì li.","en":"In the last aisle, in the fridge.","km":"នៅជួរចុងក្រោយ ក្នុងទូទឹកកក។"},{"who":"You","hz":"鸡蛋呢？","py":"Jīdàn ne?","en":"And eggs?","km":"ចុះពងមាន់?"},{"who":"Staff","hz":"鸡蛋在蔬菜旁边。","py":"Jīdàn zài shūcài pángbiān.","en":"Eggs are next to the vegetables.","km":"ពងមាន់នៅក្បែរបន្លែ។"},{"who":"You","hz":"你们这儿有购物袋吗？","py":"Nǐmen zhèr yǒu gòuwùdài ma?","en":"Do you have shopping bags here?","km":"នៅទីនេះមានថង់ដាក់ឥវ៉ាន់ទេ?"},{"who":"Staff","hz":"收银台有，一个三毛钱。","py":"Shōuyíntái yǒu, yí ge sān máo qián.","en":"At the checkout — thirty cents each.","km":"នៅកន្លែងគិតលុយមាន មួយសាមសិបសេន។"}],"phrases":[{"hz":"……在哪儿？","py":"… zài nǎr?","en":"Where is …?","km":"…នៅឯណា?"},{"hz":"旁边","py":"pángbiān","en":"Next to","km":"ក្បែរ"},{"hz":"牛奶","py":"niúnǎi","en":"Milk","km":"ទឹកដោះគោ"},{"hz":"鸡蛋","py":"jīdàn","en":"Eggs","km":"ពងមាន់"},{"hz":"购物袋","py":"gòuwùdài","en":"Shopping bag","km":"ថង់ដាក់ឥវ៉ាន់"},{"hz":"收银台","py":"shōuyíntái","en":"Checkout / cashier","km":"កន្លែងគិតលុយ"}],"tips":[{"label":"Place words","html":"Location goes <em>after</em> the noun: <span class=\"zh\">冰柜里</span> “fridge-inside”, <span class=\"zh\">桌子上</span> “table-on”.","culture":false}]},
{"n":36,"ch":3,"title":"How Will You Pay?","titleZh":"怎么付钱？","titleKm":"បង់ប្រាក់របៀបណា?","art":"shop card uniform f","scene":"You are at the till of a convenience store in China with a few snacks.","dialogue":[{"who":"Cashier","hz":"一共四十二块六。要袋子吗？","py":"Yígòng sìshí'èr kuài liù. Yào dàizi ma?","en":"42.60 altogether. Do you need a bag?","km":"សរុបសែសិបពីរយ័នប្រាំមួយកាក់។ ត្រូវការថង់ទេ?"},{"who":"You","hz":"不要，谢谢。可以刷卡吗？","py":"Bú yào, xièxie. Kěyǐ shuā kǎ ma?","en":"No, thanks. Can I pay by card?","km":"អត់ទេ អរគុណ។ អាចឆូតកាតបានទេ?"},{"who":"Cashier","hz":"可以，也可以用支付宝或者微信。","py":"Kěyǐ, yě kěyǐ yòng Zhīfùbǎo huòzhě Wēixìn.","en":"Yes — you can also use Alipay or WeChat.","km":"បាន ហើយក៏អាចប្រើ Alipay ឬ WeChat បានដែរ។"},{"who":"You","hz":"那我用微信。我扫你吗？","py":"Nà wǒ yòng Wēixìn. Wǒ sǎo nǐ ma?","en":"I'll use WeChat. Do I scan your code?","km":"អញ្ចឹងខ្ញុំប្រើ WeChat។ ខ្ញុំស្កេនរបស់អ្នកឬ?"},{"who":"Cashier","hz":"我扫你的付款码。好了，付款成功。","py":"Wǒ sǎo nǐ de fùkuǎnmǎ. Hǎo le, fùkuǎn chénggōng.","en":"I'll scan your payment code. Done — payment successful.","km":"ខ្ញុំស្កេនកូដបង់ប្រាក់របស់អ្នក។ រួចហើយ បង់ប្រាក់ជោគជ័យ។"},{"who":"You","hz":"可以给我小票吗？","py":"Kěyǐ gěi wǒ xiǎopiào ma?","en":"Could I have the receipt?","km":"អាចឱ្យវិក្កយបត្រខ្ញុំបានទេ?"}],"phrases":[{"hz":"刷卡","py":"shuā kǎ","en":"Pay by card","km":"ឆូតកាត"},{"hz":"现金","py":"xiànjīn","en":"Cash","km":"សាច់ប្រាក់"},{"hz":"付款码","py":"fùkuǎnmǎ","en":"Payment code","km":"កូដបង់ប្រាក់"},{"hz":"付款成功","py":"fùkuǎn chénggōng","en":"Payment successful","km":"បង់ប្រាក់ជោគជ័យ"},{"hz":"小票","py":"xiǎopiào","en":"Receipt","km":"វិក្កយបត្រ"},{"hz":"或者","py":"huòzhě","en":"Or (in statements)","km":"ឬ"}],"tips":[{"label":"Two kinds of “or”","html":"<span class=\"zh\">或者</span> is “or” in statements; <span class=\"zh\">还是</span> is “or” in questions.","culture":false}]},
{"n":37,"ch":3,"title":"Returning Something","titleZh":"退货","titleKm":"ការប្រគល់ទំនិញវិញ","art":"shop receipt uniform m","scene":"The headphones you bought yesterday don't work. You take them back to the shop.","dialogue":[{"who":"You","hz":"你好，这个耳机是昨天买的，坏了。","py":"Nǐ hǎo, zhège ěrjī shì zuótiān mǎi de, huài le.","en":"Hello, I bought these headphones yesterday — they're broken.","km":"សួស្តី កាសនេះទិញម្សិលមិញ ខូចហើយ។"},{"who":"Assistant","hz":"哪里有问题？","py":"Nǎli yǒu wèntí?","en":"What's the problem?","km":"មានបញ្ហាត្រង់ណា?"},{"who":"You","hz":"左边没有声音。","py":"Zuǒbian méiyǒu shēngyīn.","en":"There's no sound on the left.","km":"ខាងឆ្វេងគ្មានសំឡេង។"},{"who":"Assistant","hz":"您带小票了吗？","py":"Nín dài xiǎopiào le ma?","en":"Did you bring the receipt?","km":"អ្នកយកវិក្កយបត្រមកទេ?"},{"who":"You","hz":"带了，在这儿。可以退吗？","py":"Dài le, zài zhèr. Kěyǐ tuì ma?","en":"Yes, here it is. Can I return them?","km":"យកមក នៅទីនេះ។ អាចប្រគល់វិញបានទេ?"},{"who":"Assistant","hz":"可以退，也可以换一个新的。","py":"Kěyǐ tuì, yě kěyǐ huàn yí ge xīn de.","en":"You can return them, or exchange them for a new pair.","km":"អាចប្រគល់វិញ ឬក៏អាចប្តូរយកថ្មីបាន។"},{"who":"You","hz":"那换一个新的吧。","py":"Nà huàn yí ge xīn de ba.","en":"Then I'll exchange them for new ones.","km":"អញ្ចឹងប្តូរយកថ្មីចុះ។"}],"phrases":[{"hz":"坏了","py":"huài le","en":"It's broken","km":"ខូចហើយ"},{"hz":"有问题","py":"yǒu wèntí","en":"There's a problem","km":"មានបញ្ហា"},{"hz":"退货","py":"tuìhuò","en":"Return goods","km":"ប្រគល់ទំនិញវិញ"},{"hz":"换一个","py":"huàn yí ge","en":"Exchange for another","km":"ប្តូរមួយទៀត"},{"hz":"退钱","py":"tuì qián","en":"Refund","km":"សងប្រាក់វិញ"},{"hz":"是昨天买的","py":"shì zuótiān mǎi de","en":"(It) was bought yesterday","km":"ទិញកាលពីម្សិលមិញ"}],"tips":[{"label":"是……的 for details","html":"To stress when, where or how something happened in the past, wrap it in <span class=\"zh\">是……的</span>: <span class=\"zh\">我是坐飞机来的</span> — I came by plane.","culture":false}]},
{"n":38,"ch":3,"title":"Getting a SIM Card","titleZh":"办手机卡","titleKm":"ធ្វើស៊ីមកាត","art":"shop phone uniform f","scene":"You have just arrived in China and need a local SIM card.","dialogue":[{"who":"You","hz":"你好，我想办一张手机卡。","py":"Nǐ hǎo, wǒ xiǎng bàn yì zhāng shǒujī kǎ.","en":"Hello, I'd like to get a SIM card.","km":"សួស្តី ខ្ញុំចង់ធ្វើស៊ីមកាតមួយ។"},{"who":"Clerk","hz":"请给我看一下您的护照。","py":"Qǐng gěi wǒ kàn yíxià nín de hùzhào.","en":"Please show me your passport.","km":"សូមបង្ហាញលិខិតឆ្លងដែនរបស់អ្នក។"},{"who":"You","hz":"给你。有什么套餐？","py":"Gěi nǐ. Yǒu shénme tàocān?","en":"Here you are. What plans do you have?","km":"នេះ។ មានកញ្ចប់អ្វីខ្លះ?"},{"who":"Clerk","hz":"这个一个月五十九块，有三十G流量。","py":"Zhège yí ge yuè wǔshíjiǔ kuài, yǒu sānshí G liúliàng.","en":"This one is 59 a month with 30 GB of data.","km":"មួយនេះ ហាសិបប្រាំបួនយ័នមួយខែ មានទិន្នន័យ ៣០G។"},{"who":"You","hz":"可以打国际电话吗？","py":"Kěyǐ dǎ guójì diànhuà ma?","en":"Can I make international calls?","km":"អាចហៅទូរសព្ទអន្តរជាតិបានទេ?"},{"who":"Clerk","hz":"可以，但是要另外收费。","py":"Kěyǐ, dànshì yào lìngwài shōufèi.","en":"Yes, but there's an extra charge.","km":"បាន ប៉ុន្តែគិតថ្លៃបន្ថែម។"},{"who":"You","hz":"好，就办这个。","py":"Hǎo, jiù bàn zhège.","en":"OK, I'll get this one.","km":"ល្អ ធ្វើមួយនេះ។"}],"phrases":[{"hz":"手机卡","py":"shǒujī kǎ","en":"SIM card","km":"ស៊ីមកាត"},{"hz":"护照","py":"hùzhào","en":"Passport","km":"លិខិតឆ្លងដែន"},{"hz":"套餐","py":"tàocān","en":"Plan / package","km":"កញ្ចប់"},{"hz":"流量","py":"liúliàng","en":"Mobile data","km":"ទិន្នន័យអ៊ីនធឺណិត"},{"hz":"国际电话","py":"guójì diànhuà","en":"International call","km":"ការហៅអន្តរជាតិ"},{"hz":"充值","py":"chōngzhí","en":"Top up","km":"បញ្ចូលលុយ"}],"tips":[{"label":"办 for paperwork","html":"<span class=\"zh\">办</span> <em>bàn</em> means “to handle / get done” — used for cards, visas and accounts: <span class=\"zh\">办签证</span> get a visa.","culture":false}]},
{"n":39,"ch":3,"title":"Changing Money","titleZh":"换钱","titleKm":"ការប្តូរប្រាក់","art":"bank money suit f","scene":"You go to a bank counter to change US dollars into Chinese yuan.","dialogue":[{"who":"Clerk","hz":"您好，办什么业务？","py":"Nín hǎo, bàn shénme yèwù?","en":"Hello, how can I help you?","km":"ជម្រាបសួរ ចង់ធ្វើប្រតិបត្តិការអ្វី?"},{"who":"You","hz":"我想把美元换成人民币。","py":"Wǒ xiǎng bǎ měiyuán huàn chéng rénmínbì.","en":"I'd like to change US dollars into renminbi.","km":"ខ្ញុំចង់ប្តូរដុល្លារអាមេរិកជាប្រាក់យ័ន។"},{"who":"Clerk","hz":"换多少？","py":"Huàn duōshao?","en":"How much?","km":"ប្តូរប៉ុន្មាន?"},{"who":"You","hz":"五百美元。今天的汇率是多少？","py":"Wǔbǎi měiyuán. Jīntiān de huìlǜ shì duōshao?","en":"500 dollars. What's today's exchange rate?","km":"ប្រាំរយដុល្លារ។ អត្រាប្តូរប្រាក់ថ្ងៃនេះប៉ុន្មាន?"},{"who":"Clerk","hz":"一美元换七块一。请填一下这张表。","py":"Yì měiyuán huàn qī kuài yī. Qǐng tián yíxià zhè zhāng biǎo.","en":"One dollar is 7.10 yuan. Please fill in this form.","km":"មួយដុល្លារស្មើនឹងប្រាំពីរយ័នមួយកាក់។ សូមបំពេញទម្រង់នេះ។"},{"who":"You","hz":"填好了。","py":"Tián hǎo le.","en":"I've filled it in.","km":"បំពេញរួចហើយ។"},{"who":"Clerk","hz":"这是三千五百五十块，请点一下。","py":"Zhè shì sānqiān wǔbǎi wǔshí kuài, qǐng diǎn yíxià.","en":"Here's 3,550 yuan — please count it.","km":"នេះគឺបីពាន់ប្រាំរយហាសិបយ័ន សូមរាប់មើល។"}],"phrases":[{"hz":"换钱","py":"huàn qián","en":"Change money","km":"ប្តូរប្រាក់"},{"hz":"人民币","py":"rénmínbì","en":"Renminbi (Chinese money)","km":"ប្រាក់យ័នចិន"},{"hz":"美元","py":"měiyuán","en":"US dollar","km":"ដុល្លារអាមេរិក"},{"hz":"汇率","py":"huìlǜ","en":"Exchange rate","km":"អត្រាប្តូរប្រាក់"},{"hz":"填表","py":"tián biǎo","en":"Fill in a form","km":"បំពេញទម្រង់"},{"hz":"请点一下","py":"qǐng diǎn yíxià","en":"Please count it","km":"សូមរាប់មើល"}],"tips":[{"label":"把 sentences","html":"<span class=\"zh\">把</span> moves the object before the verb when you do something to it: <span class=\"zh\">把美元换成人民币</span> — “take the dollars and change them into RMB”.","culture":false}]},
{"n":40,"ch":3,"title":"Buying Fruit","titleZh":"买水果","titleKm":"ទិញផ្លែឈើ","art":"market fruit apron f","scene":"At the fruit stall the mangoes look perfect.","dialogue":[{"who":"Seller","hz":"来看看，芒果很甜！","py":"Lái kànkan, mángguǒ hěn tián!","en":"Come and have a look — the mangoes are sweet!","km":"មកមើលសិន ស្វាយផ្អែមណាស់!"},{"who":"You","hz":"芒果怎么卖？","py":"Mángguǒ zěnme mài?","en":"How much are the mangoes?","km":"ស្វាយលក់យ៉ាងម៉េច?"},{"who":"Seller","hz":"十块钱一斤。","py":"Shí kuài qián yì jīn.","en":"Ten yuan a jin (half a kilo).","km":"ដប់យ័នមួយជីន។"},{"who":"You","hz":"可以尝一下吗？","py":"Kěyǐ cháng yíxià ma?","en":"Can I have a taste?","km":"អាចភ្លក់បានទេ?"},{"who":"Seller","hz":"可以，你尝尝。","py":"Kěyǐ, nǐ chángchang.","en":"Sure, try some.","km":"បាន ភ្លក់មើល។"},{"who":"You","hz":"真甜！给我来两斤。","py":"Zhēn tián! Gěi wǒ lái liǎng jīn.","en":"Really sweet! Give me two jin.","km":"ផ្អែមមែន! យកឱ្យខ្ញុំពីរជីន។"},{"who":"Seller","hz":"好嘞！二十块。","py":"Hǎo lei! Èrshí kuài.","en":"Coming up! Twenty yuan.","km":"បាទ! ម្ភៃយ័ន។"}],"phrases":[{"hz":"怎么卖？","py":"zěnme mài?","en":"How is it sold? (price)","km":"លក់យ៉ាងម៉េច?"},{"hz":"一斤","py":"yì jīn","en":"One jin (500 g)","km":"មួយជីន (៥០០ក្រាម)"},{"hz":"尝一下","py":"cháng yíxià","en":"Have a taste","km":"ភ្លក់បន្តិច"},{"hz":"真甜！","py":"zhēn tián!","en":"Really sweet!","km":"ផ្អែមមែន!"},{"hz":"芒果","py":"mángguǒ","en":"Mango","km":"ស្វាយ"},{"hz":"香蕉 / 苹果","py":"xiāngjiāo / píngguǒ","en":"Banana / apple","km":"ចេក / ប៉ោម"}],"tips":[{"label":"Jin, not kilo","html":"Markets in China weigh in <span class=\"zh\">斤</span> <em>jīn</em> = 500 g. One kilo is <span class=\"zh\">两斤</span> or <span class=\"zh\">一公斤</span>.","culture":true}]},
{"n":41,"ch":4,"title":"Taking a Taxi","titleZh":"坐出租车","titleKm":"ជិះតាក់ស៊ី","art":"street map cap m","scene":"You get into a taxi outside the train station.","dialogue":[{"who":"Driver","hz":"您好，去哪儿？","py":"Nín hǎo, qù nǎr?","en":"Hello, where to?","km":"ជម្រាបសួរ ទៅណា?"},{"who":"You","hz":"师傅，去人民广场。","py":"Shīfu, qù Rénmín Guǎngchǎng.","en":"To People's Square, please.","km":"លោកពូ ទៅទីលានប្រជាជន។"},{"who":"Driver","hz":"好的。系好安全带。","py":"Hǎo de. Jì hǎo ānquándài.","en":"OK. Please fasten your seat belt.","km":"បាទ។ សូមពាក់ខ្សែក្រវាត់សុវត្ថិភាព។"},{"who":"You","hz":"大概要多长时间？","py":"Dàgài yào duō cháng shíjiān?","en":"About how long will it take?","km":"ប្រហែលចំណាយពេលប៉ុន្មាន?"},{"who":"Driver","hz":"不堵车的话，二十分钟。","py":"Bù dǔchē de huà, èrshí fēnzhōng.","en":"If there's no traffic, twenty minutes.","km":"បើមិនស្ទះចរាចរណ៍ ម្ភៃនាទី។"},{"who":"You","hz":"就在前面停吧。多少钱？","py":"Jiù zài qiánmiàn tíng ba. Duōshao qián?","en":"Stop just up ahead, please. How much?","km":"ឈប់នៅខាងមុខនេះចុះ។ ថ្លៃប៉ុន្មាន?"},{"who":"Driver","hz":"三十二块。","py":"Sānshí'èr kuài.","en":"Thirty-two yuan.","km":"សាមសិបពីរយ័ន។"}],"phrases":[{"hz":"去哪儿？","py":"qù nǎr?","en":"Where to?","km":"ទៅណា?"},{"hz":"师傅","py":"shīfu","en":"Driver / master (polite address)","km":"លោកពូ (ហៅអ្នកបើកបរ)"},{"hz":"去……","py":"qù…","en":"To … (please)","km":"ទៅ…"},{"hz":"要多长时间？","py":"yào duō cháng shíjiān?","en":"How long does it take?","km":"ចំណាយពេលប៉ុន្មាន?"},{"hz":"在前面停","py":"zài qiánmiàn tíng","en":"Stop up ahead","km":"ឈប់នៅខាងមុខ"},{"hz":"系好安全带","py":"jì hǎo ānquándài","en":"Fasten your seat belt","km":"ពាក់ខ្សែក្រវាត់សុវត្ថិភាព"}],"tips":[{"label":"Calling a driver","html":"Address taxi drivers, mechanics and cooks as <span class=\"zh\">师傅</span> <em>shīfu</em> — it is polite and friendly.","culture":true}]},
{"n":42,"ch":4,"title":"Asking for Directions","titleZh":"问路","titleKm":"ការសួរផ្លូវ","art":"street signpost shirt f","scene":"You are looking for a museum and stop a young woman on the street.","dialogue":[{"who":"You","hz":"打扰一下，博物馆怎么走？","py":"Dǎrǎo yíxià, bówùguǎn zěnme zǒu?","en":"Excuse me, how do I get to the museum?","km":"សុំទោសរំខាន តើទៅសារមន្ទីរតាមផ្លូវណា?"},{"who":"Woman","hz":"一直往前走，到红绿灯往左拐。","py":"Yìzhí wǎng qián zǒu, dào hónglǜdēng wǎng zuǒ guǎi.","en":"Go straight ahead, and turn left at the traffic lights.","km":"ដើរត្រង់ទៅមុខ ដល់ភ្លើងស្តុបបត់ឆ្វេង។"},{"who":"You","hz":"远不远？","py":"Yuǎn bu yuǎn?","en":"Is it far?","km":"ឆ្ងាយទេ?"},{"who":"Woman","hz":"不远，走路大概十分钟。","py":"Bù yuǎn, zǒulù dàgài shí fēnzhōng.","en":"Not far, about ten minutes on foot.","km":"មិនឆ្ងាយទេ ដើរប្រហែលដប់នាទី។"},{"who":"You","hz":"博物馆在路的哪边？","py":"Bówùguǎn zài lù de nǎ biān?","en":"Which side of the road is the museum on?","km":"សារមន្ទីរនៅខាងណានៃផ្លូវ?"},{"who":"Woman","hz":"在右边，银行对面。","py":"Zài yòubian, yínháng duìmiàn.","en":"On the right, opposite the bank.","km":"នៅខាងស្តាំ ទល់មុខធនាគារ។"},{"who":"You","hz":"明白了，非常感谢！","py":"Míngbai le, fēicháng gǎnxiè!","en":"Got it — thank you very much!","km":"យល់ហើយ អរគុណច្រើន!"}],"phrases":[{"hz":"……怎么走？","py":"… zěnme zǒu?","en":"How do I get to …?","km":"ទៅ…តាមផ្លូវណា?"},{"hz":"一直往前走","py":"yìzhí wǎng qián zǒu","en":"Go straight ahead","km":"ដើរត្រង់ទៅមុខ"},{"hz":"往左拐 / 往右拐","py":"wǎng zuǒ guǎi / wǎng yòu guǎi","en":"Turn left / turn right","km":"បត់ឆ្វេង / បត់ស្តាំ"},{"hz":"红绿灯","py":"hónglǜdēng","en":"Traffic lights","km":"ភ្លើងស្តុប"},{"hz":"对面","py":"duìmiàn","en":"Opposite","km":"ទល់មុខ"},{"hz":"远不远？","py":"yuǎn bu yuǎn?","en":"Is it far?","km":"ឆ្ងាយទេ?"}],"tips":[{"label":"Polite openers","html":"<span class=\"zh\">打扰一下</span> (sorry to bother you) and <span class=\"zh\">请问</span> (may I ask) are the best ways to stop a stranger.","culture":false}]},
{"n":43,"ch":4,"title":"Taking the Subway","titleZh":"坐地铁","titleKm":"ជិះរថភ្លើងក្រោមដី","art":"station ticket uniform f","scene":"You are at a subway station and not sure which line to take.","dialogue":[{"who":"You","hz":"请问，去天安门坐几号线？","py":"Qǐngwèn, qù Tiān'ānmén zuò jǐ hào xiàn?","en":"Excuse me, which line goes to Tiananmen?","km":"សុំសួរ ទៅទៀនអានមិនជិះខ្សែលេខប៉ុន្មាន?"},{"who":"Staff","hz":"坐一号线，往西的方向。","py":"Zuò yī hào xiàn, wǎng xī de fāngxiàng.","en":"Take Line 1, westbound.","km":"ជិះខ្សែលេខមួយ ទិសខាងលិច។"},{"who":"You","hz":"要换车吗？","py":"Yào huàn chē ma?","en":"Do I need to change trains?","km":"ត្រូវប្តូររថភ្លើងទេ?"},{"who":"Staff","hz":"不用换，坐五站就到。","py":"Búyòng huàn, zuò wǔ zhàn jiù dào.","en":"No change — it's five stops.","km":"មិនបាច់ប្តូរទេ ជិះប្រាំស្ថានីយ៍ក៏ដល់។"},{"who":"You","hz":"在哪儿买票？","py":"Zài nǎr mǎi piào?","en":"Where do I buy a ticket?","km":"ទិញសំបុត្រនៅឯណា?"},{"who":"Staff","hz":"用那边的自动售票机，或者用手机扫码进站。","py":"Yòng nàbiān de zìdòng shòupiàojī, huòzhě yòng shǒujī sǎo mǎ jìn zhàn.","en":"Use the ticket machine over there, or scan in with your phone.","km":"ប្រើម៉ាស៊ីនលក់សំបុត្រនៅខាងនោះ ឬស្កេនទូរសព្ទចូលស្ថានីយ៍។"}],"phrases":[{"hz":"地铁","py":"dìtiě","en":"Subway / metro","km":"រថភ្លើងក្រោមដី"},{"hz":"几号线？","py":"jǐ hào xiàn?","en":"Which line?","km":"ខ្សែលេខប៉ុន្មាន?"},{"hz":"换车","py":"huàn chē","en":"Change trains","km":"ប្តូររថភ្លើង"},{"hz":"坐五站","py":"zuò wǔ zhàn","en":"Ride five stops","km":"ជិះប្រាំស្ថានីយ៍"},{"hz":"买票","py":"mǎi piào","en":"Buy a ticket","km":"ទិញសំបុត្រ"},{"hz":"出口","py":"chūkǒu","en":"Exit","km":"ច្រកចេញ"}],"tips":[{"label":"坐 for transport","html":"You “sit” on transport: <span class=\"zh\">坐地铁</span>, <span class=\"zh\">坐公交车</span>, <span class=\"zh\">坐飞机</span>. For bikes and motorbikes, you “ride”: <span class=\"zh\">骑</span> <em>qí</em>.","culture":false}]},
{"n":44,"ch":4,"title":"Buying a Train Ticket","titleZh":"买火车票","titleKm":"ទិញសំបុត្ររថភ្លើង","art":"station ticket uniform m","scene":"You want a high-speed train ticket from Beijing to Shanghai.","dialogue":[{"who":"You","hz":"我要一张去上海的高铁票。","py":"Wǒ yào yì zhāng qù Shànghǎi de gāotiě piào.","en":"I'd like a high-speed train ticket to Shanghai.","km":"ខ្ញុំចង់បានសំបុត្ររថភ្លើងល្បឿនលឿនមួយទៅសៀងហៃ។"},{"who":"Clerk","hz":"哪天的？","py":"Nǎ tiān de?","en":"For which day?","km":"ថ្ងៃណា?"},{"who":"You","hz":"明天上午的。","py":"Míngtiān shàngwǔ de.","en":"Tomorrow morning.","km":"ថ្ងៃស្អែកពេលព្រឹក។"},{"who":"Clerk","hz":"九点有一趟，二等座五百五十三块。","py":"Jiǔ diǎn yǒu yí tàng, èr děng zuò wǔbǎi wǔshísān kuài.","en":"There's one at nine — second class is 553 yuan.","km":"ម៉ោងប្រាំបួនមានមួយជើង កៅអីថ្នាក់ទីពីរ ៥៥៣យ័ន។"},{"who":"You","hz":"好。可以要靠窗的座位吗？","py":"Hǎo. Kěyǐ yào kào chuāng de zuòwèi ma?","en":"OK. Could I have a window seat?","km":"បាន។ អាចយកកៅអីជាប់បង្អួចបានទេ?"},{"who":"Clerk","hz":"可以。请出示护照。","py":"Kěyǐ. Qǐng chūshì hùzhào.","en":"Yes. Please show your passport.","km":"បាន។ សូមបង្ហាញលិខិតឆ្លងដែន។"},{"who":"You","hz":"几点开始检票？","py":"Jǐ diǎn kāishǐ jiǎnpiào?","en":"What time does boarding start?","km":"ចាប់ផ្តើមពិនិត្យសំបុត្រម៉ោងប៉ុន្មាន?"},{"who":"Clerk","hz":"开车前十五分钟。","py":"Kāichē qián shíwǔ fēnzhōng.","en":"Fifteen minutes before departure.","km":"ដប់ប្រាំនាទីមុនរថភ្លើងចេញ។"}],"phrases":[{"hz":"一张票","py":"yì zhāng piào","en":"A ticket","km":"សំបុត្រមួយ"},{"hz":"高铁","py":"gāotiě","en":"High-speed train","km":"រថភ្លើងល្បឿនលឿន"},{"hz":"二等座","py":"èr děng zuò","en":"Second-class seat","km":"កៅអីថ្នាក់ទីពីរ"},{"hz":"靠窗的座位","py":"kào chuāng de zuòwèi","en":"Window seat","km":"កៅអីជាប់បង្អួច"},{"hz":"检票","py":"jiǎnpiào","en":"Check tickets / board","km":"ពិនិត្យសំបុត្រ"},{"hz":"单程 / 往返","py":"dānchéng / wǎngfǎn","en":"One-way / return","km":"ទៅតែម្តង / ទៅមក"}],"tips":[{"label":"Bring your passport","html":"In China, train tickets are tied to your ID. Foreigners need their passport to buy the ticket and to get through the gates.","culture":true}]},
{"n":45,"ch":4,"title":"Checking In at the Airport","titleZh":"机场值机","titleKm":"ចុះឈ្មោះនៅព្រលានយន្តហោះ","art":"airport passport uniform f","scene":"You are flying home to Phnom Penh and go to the check-in counter.","dialogue":[{"who":"Agent","hz":"您好，请出示护照和机票。","py":"Nín hǎo, qǐng chūshì hùzhào hé jīpiào.","en":"Hello, your passport and ticket, please.","km":"ជម្រាបសួរ សូមបង្ហាញលិខិតឆ្លងដែន និងសំបុត្រយន្តហោះ។"},{"who":"You","hz":"给您。我飞金边。","py":"Gěi nín. Wǒ fēi Jīnbiān.","en":"Here you are. I'm flying to Phnom Penh.","km":"នេះ។ ខ្ញុំហោះទៅភ្នំពេញ។"},{"who":"Agent","hz":"有行李要托运吗？","py":"Yǒu xíngli yào tuōyùn ma?","en":"Any luggage to check in?","km":"មានវ៉ាលីដាក់ក្នុងឃ្លាំងទេ?"},{"who":"You","hz":"有一个箱子。","py":"Yǒu yí ge xiāngzi.","en":"One suitcase.","km":"មានវ៉ាលីមួយ។"},{"who":"Agent","hz":"请放在这儿。您要靠窗还是靠过道？","py":"Qǐng fàng zài zhèr. Nín yào kào chuāng háishi kào guòdào?","en":"Please put it here. Window or aisle?","km":"សូមដាក់នៅទីនេះ។ អ្នកចង់បានកៅអីជាប់បង្អួច ឬជាប់ផ្លូវដើរ?"},{"who":"You","hz":"靠过道。几点登机？","py":"Kào guòdào. Jǐ diǎn dēngjī?","en":"Aisle. What time is boarding?","km":"ជាប់ផ្លូវដើរ។ ឡើងយន្តហោះម៉ោងប៉ុន្មាន?"},{"who":"Agent","hz":"十二点二十，在十八号登机口。","py":"Shí'èr diǎn èrshí, zài shíbā hào dēngjīkǒu.","en":"At 12:20, from gate 18.","km":"ម៉ោងដប់ពីរម្ភៃ នៅច្រកលេខដប់ប្រាំបី។"}],"phrases":[{"hz":"机票","py":"jīpiào","en":"Plane ticket","km":"សំបុត្រយន្តហោះ"},{"hz":"托运行李","py":"tuōyùn xíngli","en":"Check in luggage","km":"ដាក់វ៉ាលីក្នុងឃ្លាំង"},{"hz":"靠过道","py":"kào guòdào","en":"Aisle seat","km":"កៅអីជាប់ផ្លូវដើរ"},{"hz":"登机","py":"dēngjī","en":"Board the plane","km":"ឡើងយន្តហោះ"},{"hz":"登机口","py":"dēngjīkǒu","en":"Boarding gate","km":"ច្រកឡើងយន្តហោះ"},{"hz":"航班","py":"hángbān","en":"Flight","km":"ជើងហោះហើរ"}],"tips":[{"label":"Power banks","html":"Chinese airports are strict: power banks must go in your hand luggage, never in a checked suitcase.","culture":true}]},
{"n":46,"ch":4,"title":"Calling Your Ride","titleZh":"打车软件","titleKm":"ហៅឡានតាមកម្មវិធី","art":"street phone cap m","scene":"You booked a car with an app. The driver calls you to find where you are.","dialogue":[{"who":"Driver","hz":"喂，我是滴滴司机，您在哪儿？","py":"Wéi, wǒ shì Dīdī sījī, nín zài nǎr?","en":"Hello, I'm your Didi driver — where are you?","km":"អាឡូ ខ្ញុំជាអ្នកបើកឡាន Didi អ្នកនៅឯណា?"},{"who":"You","hz":"我在商场正门口，穿红衣服。","py":"Wǒ zài shāngchǎng zhèng ménkǒu, chuān hóng yīfu.","en":"I'm at the main entrance of the mall, wearing red.","km":"ខ្ញុំនៅមុខទ្វារធំផ្សារទំនើប ពាក់អាវក្រហម។"},{"who":"Driver","hz":"这里不能停车，您能走到路口吗？","py":"Zhèli bù néng tíngchē, nín néng zǒu dào lùkǒu ma?","en":"I can't stop here — can you walk to the corner?","km":"ទីនេះមិនអាចចតឡានបានទេ អ្នកអាចដើរមកផ្លូវបំបែកបានទេ?"},{"who":"You","hz":"可以。你的车是什么颜色的？","py":"Kěyǐ. Nǐ de chē shì shénme yánsè de?","en":"Sure. What colour is your car?","km":"បាន។ ឡានរបស់អ្នកពណ៌អ្វី?"},{"who":"Driver","hz":"白色的，车牌尾号是八六。","py":"Báisè de, chēpái wěihào shì bā liù.","en":"White — the plate ends in 86.","km":"ពណ៌ស ស្លាកលេខចុងក្រោយ ៨៦។"},{"who":"You","hz":"看到了，我马上过来！","py":"Kàndào le, wǒ mǎshàng guòlái!","en":"I see you — coming right now!","km":"ឃើញហើយ ខ្ញុំមកឥឡូវនេះ!"}],"phrases":[{"hz":"打车","py":"dǎchē","en":"Get a taxi / ride","km":"ហៅឡាន"},{"hz":"司机","py":"sījī","en":"Driver","km":"អ្នកបើកបរ"},{"hz":"门口","py":"ménkǒu","en":"Entrance / doorway","km":"មាត់ទ្វារ"},{"hz":"路口","py":"lùkǒu","en":"Intersection / corner","km":"ផ្លូវបំបែក"},{"hz":"车牌","py":"chēpái","en":"Number plate","km":"ស្លាកលេខឡាន"},{"hz":"我马上过来","py":"wǒ mǎshàng guòlái","en":"I'm coming right away","km":"ខ្ញុំមកឥឡូវនេះ"}],"tips":[{"label":"马上 = right now","html":"<span class=\"zh\">马上</span> literally “on horseback” — it means immediately. You'll hear it a lot from waiters and drivers.","culture":false}]},
{"n":47,"ch":4,"title":"Renting a Bike","titleZh":"骑共享单车","titleKm":"ជួលកង់","art":"park map shirt m","scene":"You want to try a shared bike and ask a student for help.","dialogue":[{"who":"You","hz":"同学，这个共享单车怎么用？","py":"Tóngxué, zhège gòngxiǎng dānchē zěnme yòng?","en":"Hi, how do you use these shared bikes?","km":"ប្អូន កង់ជួលនេះប្រើយ៉ាងម៉េច?"},{"who":"Student","hz":"先下载这个应用，然后扫车上的二维码。","py":"Xiān xiàzài zhège yìngyòng, ránhòu sǎo chē shang de èrwéimǎ.","en":"First download this app, then scan the QR code on the bike.","km":"ទាញយកកម្មវិធីនេះសិន រួចស្កេន QR code នៅលើកង់។"},{"who":"You","hz":"锁会自己打开吗？","py":"Suǒ huì zìjǐ dǎkāi ma?","en":"Will the lock open by itself?","km":"សោនឹងបើកដោយខ្លួនឯងទេ?"},{"who":"Student","hz":"对，扫完锁就开了。","py":"Duì, sǎo wán suǒ jiù kāi le.","en":"Yes, once you scan it the lock opens.","km":"ត្រូវ ស្កេនរួចសោក៏បើក។"},{"who":"You","hz":"多少钱？","py":"Duōshao qián?","en":"How much is it?","km":"ថ្លៃប៉ុន្មាន?"},{"who":"Student","hz":"一块五半小时。骑完了把锁关上就行。","py":"Yí kuài wǔ bàn xiǎoshí. Qí wán le bǎ suǒ guān shang jiù xíng.","en":"1.50 for half an hour. When you finish, just close the lock.","km":"មួយយ័នកន្លះ សម្រាប់កន្លះម៉ោង។ ជិះរួច គ្រាន់តែចាក់សោវិញបានហើយ។"},{"who":"You","hz":"明白了，谢谢你！","py":"Míngbai le, xièxie nǐ!","en":"Got it, thank you!","km":"យល់ហើយ អរគុណប្អូន!"}],"phrases":[{"hz":"共享单车","py":"gòngxiǎng dānchē","en":"Shared bike","km":"កង់ជួលរួម"},{"hz":"怎么用？","py":"zěnme yòng?","en":"How do you use it?","km":"ប្រើយ៉ាងម៉េច?"},{"hz":"下载","py":"xiàzài","en":"Download","km":"ទាញយក"},{"hz":"骑车","py":"qí chē","en":"Ride a bike","km":"ជិះកង់"},{"hz":"半小时","py":"bàn xiǎoshí","en":"Half an hour","km":"កន្លះម៉ោង"},{"hz":"就行","py":"jiù xíng","en":"That's all you need to do","km":"គ្រាន់តែ…បានហើយ"}],"tips":[{"label":"同学 for students","html":"<span class=\"zh\">同学</span> (classmate) is a friendly way to call any student you don't know.","culture":true}]},
{"n":48,"ch":4,"title":"I'm Lost","titleZh":"我迷路了","titleKm":"ខ្ញុំវង្វេងផ្លូវ","art":"street question uniform m","scene":"Your phone has no signal and you can't find your hotel. You ask a police officer.","dialogue":[{"who":"You","hz":"警察先生，我迷路了。","py":"Jǐngchá xiānsheng, wǒ mílù le.","en":"Officer, I'm lost.","km":"លោកប៉ូលិស ខ្ញុំវង្វេងផ្លូវហើយ។"},{"who":"Officer","hz":"别着急。您要去哪儿？","py":"Bié zháojí. Nín yào qù nǎr?","en":"Don't worry. Where do you want to go?","km":"កុំបារម្ភ។ អ្នកចង់ទៅណា?"},{"who":"You","hz":"我要回如家酒店。这是地址。","py":"Wǒ yào huí Rújiā Jiǔdiàn. Zhè shì dìzhǐ.","en":"I need to get back to the Home Inn hotel. Here's the address.","km":"ខ្ញុំត្រូវត្រឡប់ទៅសណ្ឋាគាររូជា។ នេះជាអាសយដ្ឋាន។"},{"who":"Officer","hz":"离这儿不远。过了这座桥，第一个路口右拐。","py":"Lí zhèr bù yuǎn. Guò le zhè zuò qiáo, dì-yī ge lùkǒu yòu guǎi.","en":"It's not far from here. Cross this bridge and turn right at the first junction.","km":"មិនឆ្ងាយពីទីនេះទេ។ ឆ្លងស្ពាននេះ ហើយបត់ស្តាំនៅផ្លូវបំបែកទីមួយ។"},{"who":"You","hz":"过桥，右拐。然后呢？","py":"Guò qiáo, yòu guǎi. Ránhòu ne?","en":"Cross the bridge, turn right. And then?","km":"ឆ្លងស្ពាន បត់ស្តាំ។ បន្ទាប់មក?"},{"who":"Officer","hz":"再走两百米就到了。","py":"Zài zǒu liǎngbǎi mǐ jiù dào le.","en":"Walk another 200 metres and you're there.","km":"ដើរពីររយម៉ែត្រទៀតក៏ដល់។"},{"who":"You","hz":"太感谢您了！","py":"Tài gǎnxiè nín le!","en":"Thank you so much!","km":"អរគុណលោកច្រើនណាស់!"}],"phrases":[{"hz":"我迷路了","py":"wǒ mílù le","en":"I'm lost","km":"ខ្ញុំវង្វេងផ្លូវ"},{"hz":"地址","py":"dìzhǐ","en":"Address","km":"អាសយដ្ឋាន"},{"hz":"离这儿远吗？","py":"lí zhèr yuǎn ma?","en":"Is it far from here?","km":"ឆ្ងាយពីទីនេះទេ?"},{"hz":"过桥","py":"guò qiáo","en":"Cross the bridge","km":"ឆ្លងស្ពាន"},{"hz":"第一个路口","py":"dì-yī ge lùkǒu","en":"The first junction","km":"ផ្លូវបំបែកទីមួយ"},{"hz":"警察","py":"jǐngchá","en":"Police officer","km":"ប៉ូលិស"}],"tips":[{"label":"Keep a hotel card","html":"Carry your hotel's business card or address in Chinese. Any driver or passer-by can then help you back.","culture":true}]},
{"n":49,"ch":4,"title":"Checking Into a Hotel","titleZh":"入住酒店","titleKm":"ចុះឈ្មោះស្នាក់នៅសណ្ឋាគារ","art":"hotel key suit f","scene":"You arrive at your hotel after a long trip.","dialogue":[{"who":"Receptionist","hz":"您好，欢迎光临。请问有预订吗？","py":"Nín hǎo, huānyíng guānglín. Qǐngwèn yǒu yùdìng ma?","en":"Hello and welcome. Do you have a reservation?","km":"ជម្រាបសួរ សូមស្វាគមន៍។ សុំសួរ មានកក់ទុកទេ?"},{"who":"You","hz":"有，我在网上订了一个大床房。","py":"Yǒu, wǒ zài wǎngshang dìng le yí ge dàchuángfáng.","en":"Yes, I booked a double room online.","km":"មាន ខ្ញុំបានកក់បន្ទប់គ្រែធំមួយតាមអនឡាញ។"},{"who":"Receptionist","hz":"请出示护照。您住几个晚上？","py":"Qǐng chūshì hùzhào. Nín zhù jǐ ge wǎnshang?","en":"Your passport, please. How many nights are you staying?","km":"សូមបង្ហាញលិខិតឆ្លងដែន។ អ្នកស្នាក់ប៉ុន្មានយប់?"},{"who":"You","hz":"三个晚上。含早餐吗？","py":"Sān ge wǎnshang. Hán zǎocān ma?","en":"Three nights. Is breakfast included?","km":"បីយប់។ រួមទាំងអាហារពេលព្រឹកទេ?"},{"who":"Receptionist","hz":"含早餐，在二楼，六点半到十点。","py":"Hán zǎocān, zài èr lóu, liù diǎn bàn dào shí diǎn.","en":"Yes — on the second floor, 6:30 to 10.","km":"រួម នៅជាន់ទីពីរ ពីម៉ោងប្រាំមួយកន្លះដល់ម៉ោងដប់។"},{"who":"You","hz":"Wi-Fi密码是多少？","py":"Wi-Fi mìmǎ shì duōshao?","en":"What's the Wi-Fi password?","km":"លេខសម្ងាត់ Wi-Fi ជាអ្វី?"},{"who":"Receptionist","hz":"在房卡上。您的房间是八零六。","py":"Zài fángkǎ shang. Nín de fángjiān shì bā líng liù.","en":"It's on your key card. Your room is 806.","km":"នៅលើកាតបន្ទប់។ បន្ទប់របស់អ្នកលេខ ៨០៦។"}],"phrases":[{"hz":"预订","py":"yùdìng","en":"Reservation / to book","km":"ការកក់"},{"hz":"大床房","py":"dàchuángfáng","en":"Room with a double bed","km":"បន្ទប់គ្រែធំ"},{"hz":"住三个晚上","py":"zhù sān ge wǎnshang","en":"Stay three nights","km":"ស្នាក់បីយប់"},{"hz":"含早餐吗？","py":"hán zǎocān ma?","en":"Is breakfast included?","km":"រួមអាហារពេលព្រឹកទេ?"},{"hz":"密码","py":"mìmǎ","en":"Password","km":"លេខសម្ងាត់"},{"hz":"房卡","py":"fángkǎ","en":"Room key card","km":"កាតបន្ទប់"}],"tips":[{"label":"Twin or double","html":"<span class=\"zh\">大床房</span> = one big bed; <span class=\"zh\">双床房</span> or <span class=\"zh\">标准间</span> = two single beds.","culture":false}]},
{"n":50,"ch":4,"title":"A Problem in Your Room","titleZh":"房间有问题","titleKm":"បន្ទប់មានបញ្ហា","art":"hotel bulb suit m","scene":"The air conditioner in your hotel room isn't working. You call the front desk.","dialogue":[{"who":"Receptionist","hz":"您好，前台。","py":"Nín hǎo, qiántái.","en":"Hello, front desk.","km":"ជម្រាបសួរ កន្លែងទទួលភ្ញៀវ។"},{"who":"You","hz":"你好，我是八零六房间。空调坏了。","py":"Nǐ hǎo, wǒ shì bā líng liù fángjiān. Kōngtiáo huài le.","en":"Hello, this is room 806. The air conditioner is broken.","km":"សួស្តី ខ្ញុំនៅបន្ទប់ ៨០៦។ ម៉ាស៊ីនត្រជាក់ខូច។"},{"who":"Receptionist","hz":"不好意思，什么问题？","py":"Bù hǎoyìsi, shénme wèntí?","en":"Sorry about that — what's the problem?","km":"សុំទោស មានបញ្ហាអ្វី?"},{"who":"You","hz":"打开以后一直吹热风。","py":"Dǎkāi yǐhòu yìzhí chuī rè fēng.","en":"When I turn it on it only blows hot air.","km":"បើកហើយ វាផ្លុំតែខ្យល់ក្តៅ។"},{"who":"Receptionist","hz":"我马上叫人去修。","py":"Wǒ mǎshàng jiào rén qù xiū.","en":"I'll send someone to fix it right away.","km":"ខ្ញុំនឹងហៅមនុស្សទៅជួសជុលភ្លាម។"},{"who":"You","hz":"如果修不好，可以换房间吗？","py":"Rúguǒ xiū bu hǎo, kěyǐ huàn fángjiān ma?","en":"If it can't be fixed, can I change rooms?","km":"បើជួសជុលមិនបាន អាចប្តូរបន្ទប់បានទេ?"},{"who":"Receptionist","hz":"当然可以。","py":"Dāngrán kěyǐ.","en":"Of course.","km":"ពិតជាបាន។"}],"phrases":[{"hz":"前台","py":"qiántái","en":"Front desk","km":"កន្លែងទទួលភ្ញៀវ"},{"hz":"空调","py":"kōngtiáo","en":"Air conditioner","km":"ម៉ាស៊ីនត្រជាក់"},{"hz":"修","py":"xiū","en":"To repair","km":"ជួសជុល"},{"hz":"换房间","py":"huàn fángjiān","en":"Change rooms","km":"ប្តូរបន្ទប់"},{"hz":"没有热水","py":"méiyǒu rè shuǐ","en":"There's no hot water","km":"គ្មានទឹកក្តៅ"},{"hz":"当然可以","py":"dāngrán kěyǐ","en":"Of course","km":"ពិតជាបាន"}],"tips":[{"label":"如果……就……","html":"“If … then …”: <span class=\"zh\">如果下雨，我们就不去</span> — if it rains, we won't go.","culture":false}]},
{"n":51,"ch":5,"title":"Renting a Flat","titleZh":"租房子","titleKm":"ជួលផ្ទះ","art":"home house suit m","scene":"An agent is showing you a small flat near your office.","dialogue":[{"who":"Agent","hz":"这套房子一室一厅，有厨房和卫生间。","py":"Zhè tào fángzi yí shì yì tīng, yǒu chúfáng hé wèishēngjiān.","en":"This flat has a bedroom and a living room, plus a kitchen and bathroom.","km":"ផ្ទះនេះមានបន្ទប់គេងមួយ បន្ទប់ទទួលភ្ញៀវមួយ មានផ្ទះបាយ និងបន្ទប់ទឹក។"},{"who":"You","hz":"房租一个月多少钱？","py":"Fángzū yí ge yuè duōshao qián?","en":"How much is the rent per month?","km":"ថ្លៃជួលមួយខែប៉ុន្មាន?"},{"who":"Agent","hz":"三千五，押一付三。","py":"Sānqiān wǔ, yā yī fù sān.","en":"3,500 — one month's deposit plus three months up front.","km":"បីពាន់ប្រាំរយ កក់មួយខែ បង់មុនបីខែ។"},{"who":"You","hz":"水电费包括在里面吗？","py":"Shuǐdiànfèi bāokuò zài lǐmiàn ma?","en":"Are water and electricity included?","km":"រួមទាំងថ្លៃទឹកភ្លើងទេ?"},{"who":"Agent","hz":"不包括，水电费自己付。","py":"Bù bāokuò, shuǐdiànfèi zìjǐ fù.","en":"No, you pay water and electricity yourself.","km":"មិនរួមទេ ថ្លៃទឹកភ្លើងបង់ខ្លួនឯង។"},{"who":"You","hz":"离地铁站远吗？","py":"Lí dìtiězhàn yuǎn ma?","en":"Is it far from the subway station?","km":"ឆ្ងាយពីស្ថានីយ៍រថភ្លើងក្រោមដីទេ?"},{"who":"Agent","hz":"很近，走路五分钟。","py":"Hěn jìn, zǒulù wǔ fēnzhōng.","en":"Very close — five minutes' walk.","km":"ជិតណាស់ ដើរប្រាំនាទី។"},{"who":"You","hz":"我考虑一下，明天给你回复。","py":"Wǒ kǎolǜ yíxià, míngtiān gěi nǐ huífù.","en":"I'll think about it and get back to you tomorrow.","km":"ខ្ញុំគិតសិន ថ្ងៃស្អែកឆ្លើយតបទៅអ្នក។"}],"phrases":[{"hz":"租房子","py":"zū fángzi","en":"Rent a flat","km":"ជួលផ្ទះ"},{"hz":"房租","py":"fángzū","en":"Rent","km":"ថ្លៃជួលផ្ទះ"},{"hz":"押金","py":"yājīn","en":"Deposit","km":"ប្រាក់កក់"},{"hz":"水电费","py":"shuǐdiànfèi","en":"Water and electricity bills","km":"ថ្លៃទឹកភ្លើង"},{"hz":"离……远吗？","py":"lí … yuǎn ma?","en":"Is it far from …?","km":"ឆ្ងាយពី…ទេ?"},{"hz":"我考虑一下","py":"wǒ kǎolǜ yíxià","en":"Let me think about it","km":"ខ្ញុំគិតសិន"}],"tips":[{"label":"Room counts","html":"Flats are described as rooms + living rooms: <span class=\"zh\">两室一厅</span> = two bedrooms, one living room.","culture":false}]},
{"n":52,"ch":5,"title":"Meeting a Neighbour","titleZh":"认识邻居","titleKm":"ស្គាល់អ្នកជិតខាង","art":"lane flowers shirt f e","scene":"You have just moved in. An elderly woman next door is watering her plants.","dialogue":[{"who":"Neighbour","hz":"你是新搬来的吧？","py":"Nǐ shì xīn bān lái de ba?","en":"You've just moved in, haven't you?","km":"អ្នកទើបតែរើមកនៅថ្មីមែនទេ?"},{"who":"You","hz":"是的，我住在三零二。阿姨好！","py":"Shì de, wǒ zhù zài sān líng èr. Āyí hǎo!","en":"Yes, I live in 302. Hello, auntie!","km":"បាទ/ចាស ខ្ញុំនៅបន្ទប់ ៣០២។ ជម្រាបសួរអ៊ីង!"},{"who":"Neighbour","hz":"你好！以后我们就是邻居了。","py":"Nǐ hǎo! Yǐhòu wǒmen jiù shì línjū le.","en":"Hello! So from now on we're neighbours.","km":"សួស្តី! ពីនេះទៅយើងជាអ្នកជិតខាងហើយ។"},{"who":"You","hz":"请多关照！附近有菜市场吗？","py":"Qǐng duō guānzhào! Fùjìn yǒu càishìchǎng ma?","en":"I hope you'll look out for me! Is there a market nearby?","km":"សូមជួយមើលថែផង! នៅជិតនេះមានផ្សារលក់បន្លែទេ?"},{"who":"Neighbour","hz":"有，出了小区往左走，很近。","py":"Yǒu, chū le xiǎoqū wǎng zuǒ zǒu, hěn jìn.","en":"Yes — leave the estate and go left. It's very close.","km":"មាន ចេញពីបុរីបត់ឆ្វេង ជិតណាស់។"},{"who":"You","hz":"谢谢阿姨。有什么事可以找我。","py":"Xièxie āyí. Yǒu shénme shì kěyǐ zhǎo wǒ.","en":"Thanks, auntie. If you ever need anything, just ask me.","km":"អរគុណអ៊ីង។ មានរឿងអ្វីអាចរកខ្ញុំបាន។"}],"phrases":[{"hz":"邻居","py":"línjū","en":"Neighbour","km":"អ្នកជិតខាង"},{"hz":"新搬来的","py":"xīn bān lái de","en":"Newly moved in","km":"ទើបរើមកថ្មី"},{"hz":"阿姨","py":"āyí","en":"Auntie (polite address)","km":"អ៊ីង / មីង"},{"hz":"请多关照","py":"qǐng duō guānzhào","en":"Please look after me (when new)","km":"សូមជួយមើលថែផង"},{"hz":"附近有……吗？","py":"fùjìn yǒu … ma?","en":"Is there a … nearby?","km":"នៅជិតនេះមាន…ទេ?"},{"hz":"菜市场","py":"càishìchǎng","en":"Food market","km":"ផ្សារលក់បន្លែ"}],"tips":[{"label":"Family words for strangers","html":"Chinese people call friendly strangers by family words: <span class=\"zh\">阿姨</span> auntie, <span class=\"zh\">叔叔</span> uncle, <span class=\"zh\">大哥</span> big brother.","culture":true}]},
{"n":53,"ch":5,"title":"Sharing the Housework","titleZh":"做家务","titleKm":"ធ្វើការងារផ្ទះ","art":"home broom shirt f","scene":"Your flatmate wants to sort out who does which jobs at home.","dialogue":[{"who":"Flatmate","hz":"我们分一下家务吧。","py":"Wǒmen fēn yíxià jiāwù ba.","en":"Let's divide up the housework.","km":"យើងបែងចែកការងារផ្ទះបន្តិចណា។"},{"who":"You","hz":"好啊。我可以做饭，你洗碗，怎么样？","py":"Hǎo a. Wǒ kěyǐ zuò fàn, nǐ xǐ wǎn, zěnmeyàng?","en":"Sure. I can cook and you wash up — how's that?","km":"បាន។ ខ្ញុំធ្វើម្ហូប អ្នកលាងចាន យ៉ាងម៉េចដែរ?"},{"who":"Flatmate","hz":"没问题。扫地和拖地呢？","py":"Méi wèntí. Sǎodì hé tuōdì ne?","en":"No problem. What about sweeping and mopping?","km":"គ្មានបញ្ហា។ ចុះបោសផ្ទះ និងជូតផ្ទះ?"},{"who":"You","hz":"我们轮流吧，一人一个星期。","py":"Wǒmen lúnliú ba, yì rén yí ge xīngqī.","en":"Let's take turns — one week each.","km":"យើងប្តូរវេនគ្នា ម្នាក់មួយសប្តាហ៍។"},{"who":"Flatmate","hz":"好。还有倒垃圾，每天晚上倒。","py":"Hǎo. Hái yǒu dào lājī, měi tiān wǎnshang dào.","en":"OK. And the rubbish needs taking out every evening.","km":"បាន។ ហើយមានចាក់សំរាមទៀត ចាក់រៀងរាល់ល្ងាច។"},{"who":"You","hz":"那倒垃圾也轮流。","py":"Nà dào lājī yě lúnliú.","en":"Then we'll take turns with the rubbish too.","km":"អញ្ចឹងចាក់សំរាមក៏ប្តូរវេនគ្នាដែរ។"}],"phrases":[{"hz":"家务","py":"jiāwù","en":"Housework","km":"ការងារផ្ទះ"},{"hz":"做饭","py":"zuò fàn","en":"Cook","km":"ធ្វើម្ហូប"},{"hz":"洗碗","py":"xǐ wǎn","en":"Wash the dishes","km":"លាងចាន"},{"hz":"扫地","py":"sǎodì","en":"Sweep the floor","km":"បោសផ្ទះ"},{"hz":"倒垃圾","py":"dào lājī","en":"Take out the rubbish","km":"ចាក់សំរាម"},{"hz":"轮流","py":"lúnliú","en":"Take turns","km":"ប្តូរវេនគ្នា"}],"tips":[{"label":"Sorting rubbish","html":"Many Chinese cities sort rubbish into four bins: recyclable, kitchen waste, hazardous and other. Check the signs!","culture":true}]},
{"n":54,"ch":5,"title":"At the Laundry","titleZh":"洗衣店","titleKm":"នៅហាងបោកអ៊ុត","art":"shop laundry apron f","scene":"You take a suit and some shirts to a laundry near your home.","dialogue":[{"who":"Owner","hz":"您好，要洗什么？","py":"Nín hǎo, yào xǐ shénme?","en":"Hello, what do you need washed?","km":"ជម្រាបសួរ ចង់បោកអ្វី?"},{"who":"You","hz":"这套西装要干洗，这些衬衫要熨。","py":"Zhè tào xīzhuāng yào gānxǐ, zhèxiē chènshān yào yùn.","en":"This suit needs dry-cleaning and these shirts need ironing.","km":"ឈុតអាវធំនេះបោកស្ងួត ហើយអាវទាំងនេះអ៊ុត។"},{"who":"Owner","hz":"好的。西装上这儿有个油点。","py":"Hǎo de. Xīzhuāng shang zhèr yǒu ge yóudiǎn.","en":"OK. There's a grease mark on the suit here.","km":"បាទ។ អាវធំត្រង់នេះមានស្នាមប្រេង។"},{"who":"You","hz":"能洗掉吗？","py":"Néng xǐ diào ma?","en":"Can you get it out?","km":"អាចបោកជម្រះចេញបានទេ?"},{"who":"Owner","hz":"应该可以。后天下午来拿。","py":"Yīnggāi kěyǐ. Hòutiān xiàwǔ lái ná.","en":"It should be fine. Come and collect it the day after tomorrow, in the afternoon.","km":"គួរតែបាន។ ខានស្អែករសៀលមកយក។"},{"who":"You","hz":"一共多少钱？","py":"Yígòng duōshao qián?","en":"How much is it altogether?","km":"សរុបប៉ុន្មាន?"},{"who":"Owner","hz":"八十块。这是您的取衣单。","py":"Bāshí kuài. Zhè shì nín de qǔyīdān.","en":"Eighty yuan. Here's your collection slip.","km":"ប៉ែតសិបយ័ន។ នេះជាបណ្ណមកយកសម្លៀកបំពាក់។"}],"phrases":[{"hz":"干洗","py":"gānxǐ","en":"Dry-clean","km":"បោកស្ងួត"},{"hz":"熨衣服","py":"yùn yīfu","en":"Iron clothes","km":"អ៊ុតខោអាវ"},{"hz":"洗掉","py":"xǐ diào","en":"Wash out (a stain)","km":"បោកជម្រះចេញ"},{"hz":"后天","py":"hòutiān","en":"The day after tomorrow","km":"ខានស្អែក"},{"hz":"来拿","py":"lái ná","en":"Come and collect","km":"មកយក"},{"hz":"应该可以","py":"yīnggāi kěyǐ","en":"It should be OK","km":"គួរតែបាន"}],"tips":[{"label":"掉 = off, away","html":"<span class=\"zh\">掉</span> after a verb means “off / away”: <span class=\"zh\">洗掉</span> wash off, <span class=\"zh\">扔掉</span> throw away, <span class=\"zh\">关掉</span> switch off.","culture":false}]},
{"n":55,"ch":5,"title":"A Leaking Pipe","titleZh":"水管漏水","titleKm":"បំពង់ទឹកលេច","art":"home wrench cap m","scene":"Water is dripping under your kitchen sink. You call the building's repair man.","dialogue":[{"who":"You","hz":"师傅，我家厨房漏水了。","py":"Shīfu, wǒ jiā chúfáng lòu shuǐ le.","en":"Hello, my kitchen is leaking.","km":"លោកពូ ផ្ទះបាយផ្ទះខ្ញុំលេចទឹក។"},{"who":"Repairman","hz":"哪儿漏？漏得厉害吗？","py":"Nǎr lòu? Lòu de lìhai ma?","en":"Where's the leak? Is it bad?","km":"លេចត្រង់ណា? លេចខ្លាំងទេ?"},{"who":"You","hz":"水池下面，地上都是水。","py":"Shuǐchí xiàmiàn, dì shang dōu shì shuǐ.","en":"Under the sink — there's water all over the floor.","km":"នៅក្រោមអាងលាងចាន ពេញឥដ្ឋសុទ្ធតែទឹក។"},{"who":"Repairman","hz":"先把水阀关上。我半小时以后到。","py":"Xiān bǎ shuǐfá guān shang. Wǒ bàn xiǎoshí yǐhòu dào.","en":"Turn off the water valve first. I'll be there in half an hour.","km":"បិទរ៉ូប៊ីណេទឹកសិន។ កន្លះម៉ោងទៀតខ្ញុំមកដល់។"},{"who":"You","hz":"水阀在哪儿？","py":"Shuǐfá zài nǎr?","en":"Where's the valve?","km":"រ៉ូប៊ីណេទឹកនៅឯណា?"},{"who":"Repairman","hz":"一般在水池下面，是个红色的开关。","py":"Yìbān zài shuǐchí xiàmiàn, shì ge hóngsè de kāiguān.","en":"Usually under the sink — a red handle.","km":"ជាធម្មតានៅក្រោមអាង ជាគន្លឹះពណ៌ក្រហម។"},{"who":"You","hz":"找到了，关好了。等你来！","py":"Zhǎodào le, guān hǎo le. Děng nǐ lái!","en":"Found it, it's off. See you soon!","km":"រកឃើញហើយ បិទរួចហើយ។ ចាំអ្នកមក!"}],"phrases":[{"hz":"漏水","py":"lòu shuǐ","en":"Leak water","km":"លេចទឹក"},{"hz":"厨房","py":"chúfáng","en":"Kitchen","km":"ផ្ទះបាយ"},{"hz":"卫生间","py":"wèishēngjiān","en":"Bathroom / toilet","km":"បន្ទប់ទឹក"},{"hz":"关上","py":"guān shang","en":"Turn off / close","km":"បិទ"},{"hz":"……以后到","py":"… yǐhòu dào","en":"Arrive in … (time)","km":"…ទៀតមកដល់"},{"hz":"坏了，能修吗？","py":"huài le, néng xiū ma?","en":"It's broken — can you fix it?","km":"ខូចហើយ អាចជួសជុលបានទេ?"}],"tips":[{"label":"Time + 以后","html":"<span class=\"zh\">半小时以后</span> = in half an hour; <span class=\"zh\">三天以后</span> = in three days. The time comes before <span class=\"zh\">以后</span>.","culture":false}]},
{"n":56,"ch":5,"title":"Getting a Haircut","titleZh":"理发","titleKm":"កាត់សក់","art":"salon scissors apron m","scene":"You sit down in the barber's chair.","dialogue":[{"who":"Barber","hz":"您想怎么剪？","py":"Nín xiǎng zěnme jiǎn?","en":"How would you like it cut?","km":"តើអ្នកចង់កាត់បែបណា?"},{"who":"You","hz":"剪短一点儿，但是不要太短。","py":"Jiǎn duǎn yìdiǎnr, dànshì bú yào tài duǎn.","en":"A bit shorter, but not too short.","km":"កាត់ឱ្យខ្លីបន្តិច ប៉ុន្តែកុំខ្លីពេក។"},{"who":"Barber","hz":"两边呢？","py":"Liǎngbiān ne?","en":"And the sides?","km":"ចុះសងខាង?"},{"who":"You","hz":"两边剪短，上面留长一点儿。","py":"Liǎngbiān jiǎn duǎn, shàngmiàn liú cháng yìdiǎnr.","en":"Short on the sides, a bit longer on top.","km":"សងខាងកាត់ខ្លី ខាងលើទុកវែងបន្តិច។"},{"who":"Barber","hz":"要洗头吗？","py":"Yào xǐ tóu ma?","en":"Would you like a hair wash?","km":"កក់សក់ទេ?"},{"who":"You","hz":"要。剪完了吹一下。","py":"Yào. Jiǎn wán le chuī yíxià.","en":"Yes. And blow-dry it after the cut.","km":"កក់។ កាត់រួចផ្លុំសក់បន្តិច។"},{"who":"Barber","hz":"好了，您看看怎么样？","py":"Hǎo le, nín kànkan zěnmeyàng?","en":"Done — have a look, how is it?","km":"រួចហើយ មើលមើលយ៉ាងម៉េចដែរ?"},{"who":"You","hz":"很好，我很满意！","py":"Hěn hǎo, wǒ hěn mǎnyì!","en":"Great, I'm very happy with it!","km":"ល្អណាស់ ខ្ញុំពេញចិត្តណាស់!"}],"phrases":[{"hz":"理发 / 剪头发","py":"lǐfà / jiǎn tóufa","en":"Haircut / cut hair","km":"កាត់សក់"},{"hz":"剪短一点儿","py":"jiǎn duǎn yìdiǎnr","en":"Cut it a bit shorter","km":"កាត់ខ្លីបន្តិច"},{"hz":"不要太短","py":"bú yào tài duǎn","en":"Not too short","km":"កុំខ្លីពេក"},{"hz":"洗头","py":"xǐ tóu","en":"Wash hair","km":"កក់សក់"},{"hz":"吹干","py":"chuī gān","en":"Blow-dry","km":"ផ្លុំសក់ឱ្យស្ងួត"},{"hz":"我很满意","py":"wǒ hěn mǎnyì","en":"I'm very satisfied","km":"ខ្ញុំពេញចិត្តណាស់"}],"tips":[{"label":"Show a photo","html":"Hairstyle words are hard. Show a photo and say <span class=\"zh\">我想剪这样的</span> — I want it like this.","culture":false}]},
{"n":57,"ch":5,"title":"Sending a Parcel","titleZh":"寄快递","titleKm":"ផ្ញើកញ្ចប់","art":"post parcel uniform f","scene":"You want to send a birthday present to a friend in another city.","dialogue":[{"who":"You","hz":"你好，我想寄一个包裹到广州。","py":"Nǐ hǎo, wǒ xiǎng jì yí ge bāoguǒ dào Guǎngzhōu.","en":"Hello, I'd like to send a parcel to Guangzhou.","km":"សួស្តី ខ្ញុំចង់ផ្ញើកញ្ចប់មួយទៅក្វាងចូវ។"},{"who":"Clerk","hz":"里面是什么东西？","py":"Lǐmiàn shì shénme dōngxi?","en":"What's inside?","km":"ខាងក្នុងមានអ្វី?"},{"who":"You","hz":"是一本书和一些茶叶。","py":"Shì yì běn shū hé yìxiē cháyè.","en":"A book and some tea.","km":"សៀវភៅមួយ និងតែខ្លះ។"},{"who":"Clerk","hz":"请把地址和电话写在这儿。","py":"Qǐng bǎ dìzhǐ hé diànhuà xiě zài zhèr.","en":"Please write the address and phone number here.","km":"សូមសរសេរអាសយដ្ឋាន និងលេខទូរសព្ទនៅទីនេះ។"},{"who":"You","hz":"几天能到？","py":"Jǐ tiān néng dào?","en":"How many days will it take?","km":"ប៉ុន្មានថ្ងៃទើបដល់?"},{"who":"Clerk","hz":"普通的三天，加急的明天就到。","py":"Pǔtōng de sān tiān, jiājí de míngtiān jiù dào.","en":"Standard takes three days; express arrives tomorrow.","km":"ធម្មតាបីថ្ងៃ បន្ទាន់ថ្ងៃស្អែកដល់។"},{"who":"You","hz":"普通的就行。","py":"Pǔtōng de jiù xíng.","en":"Standard is fine.","km":"ធម្មតាក៏បាន។"}],"phrases":[{"hz":"寄快递","py":"jì kuàidì","en":"Send by courier","km":"ផ្ញើតាមក្រុមហ៊ុនដឹកជញ្ជូន"},{"hz":"包裹","py":"bāoguǒ","en":"Parcel","km":"កញ្ចប់"},{"hz":"里面是什么？","py":"lǐmiàn shì shénme?","en":"What's inside?","km":"ខាងក្នុងមានអ្វី?"},{"hz":"几天能到？","py":"jǐ tiān néng dào?","en":"How many days to arrive?","km":"ប៉ុន្មានថ្ងៃទើបដល់?"},{"hz":"加急","py":"jiājí","en":"Express / urgent","km":"បន្ទាន់"},{"hz":"……就行","py":"… jiù xíng","en":"… is fine","km":"…ក៏បាន"}],"tips":[{"label":"Measure words","html":"Each noun has its counting word: <span class=\"zh\">一本书</span> a book, <span class=\"zh\">一张票</span> a ticket, <span class=\"zh\">一件衣服</span> a piece of clothing. When unsure, <span class=\"zh\">个</span> often works.","culture":false}]},
{"n":58,"ch":5,"title":"What's the Wi-Fi Password?","titleZh":"Wi-Fi密码是多少？","titleKm":"លេខសម្ងាត់ Wi-Fi ជាអ្វី?","art":"cafe wifi apron m","scene":"You want to work on your laptop in a café.","dialogue":[{"who":"You","hz":"你好，这儿有Wi-Fi吗？","py":"Nǐ hǎo, zhèr yǒu Wi-Fi ma?","en":"Hi, is there Wi-Fi here?","km":"សួស្តី នៅទីនេះមាន Wi-Fi ទេ?"},{"who":"Barista","hz":"有，免费的。","py":"Yǒu, miǎnfèi de.","en":"Yes, it's free.","km":"មាន ឥតគិតថ្លៃ។"},{"who":"You","hz":"密码是多少？","py":"Mìmǎ shì duōshao?","en":"What's the password?","km":"លេខសម្ងាត់ជាអ្វី?"},{"who":"Barista","hz":"在小票下面，八个八。","py":"Zài xiǎopiào xiàmiàn, bā ge bā.","en":"It's at the bottom of your receipt — eight eights.","km":"នៅខាងក្រោមវិក្កយបត្រ ប្រាំបីប្រាំបីដង។"},{"who":"You","hz":"连不上，信号不太好。","py":"Lián bu shàng, xìnhào bú tài hǎo.","en":"It won't connect — the signal isn't very good.","km":"ភ្ជាប់មិនបាន សេវាខ្សោយ។"},{"who":"Barista","hz":"您坐到里面去试试，那边信号好。","py":"Nín zuò dào lǐmiàn qù shìshi, nàbiān xìnhào hǎo.","en":"Try sitting further inside — the signal is better there.","km":"អ្នកអង្គុយនៅខាងក្នុងសាកមើល ខាងនោះសេវាល្អ។"},{"who":"You","hz":"好，连上了！谢谢。","py":"Hǎo, lián shàng le! Xièxie.","en":"Great, I'm connected! Thanks.","km":"ល្អ ភ្ជាប់បានហើយ! អរគុណ។"}],"phrases":[{"hz":"有Wi-Fi吗？","py":"yǒu Wi-Fi ma?","en":"Is there Wi-Fi?","km":"មាន Wi-Fi ទេ?"},{"hz":"免费","py":"miǎnfèi","en":"Free of charge","km":"ឥតគិតថ្លៃ"},{"hz":"密码是多少？","py":"mìmǎ shì duōshao?","en":"What's the password?","km":"លេខសម្ងាត់ជាអ្វី?"},{"hz":"连不上","py":"lián bu shàng","en":"Can't connect","km":"ភ្ជាប់មិនបាន"},{"hz":"信号","py":"xìnhào","en":"Signal","km":"សេវា / សញ្ញា"},{"hz":"手机没电了","py":"shǒujī méi diàn le","en":"My phone's battery is dead","km":"ទូរសព្ទអស់ថ្មហើយ"}],"tips":[{"label":"Charging","html":"Need a charger? Ask <span class=\"zh\">这儿可以充电吗？</span> — can I charge my phone here?","culture":false}]},
{"n":59,"ch":5,"title":"Taking Care of a Pet","titleZh":"养宠物","titleKm":"ចិញ្ចឹមសត្វ","art":"park paw shirt f c","scene":"In the park a little girl is walking a puppy. You stop to say hello.","dialogue":[{"who":"You","hz":"好可爱的小狗！它叫什么名字？","py":"Hǎo kě'ài de xiǎo gǒu! Tā jiào shénme míngzi?","en":"What a cute puppy! What's its name?","km":"កូនឆ្កែគួរឱ្យស្រឡាញ់ណាស់! វាឈ្មោះអ្វី?"},{"who":"Girl","hz":"它叫豆豆，三个月大。","py":"Tā jiào Dòudou, sān ge yuè dà.","en":"It's called Doudou — three months old.","km":"វាឈ្មោះតូវតូវ អាយុបីខែ។"},{"who":"You","hz":"我可以摸摸它吗？","py":"Wǒ kěyǐ mōmo tā ma?","en":"Can I stroke it?","km":"ខ្ញុំអាចស្ទាបវាបានទេ?"},{"who":"Girl","hz":"可以，它不咬人。","py":"Kěyǐ, tā bù yǎo rén.","en":"Yes, it doesn't bite.","km":"បាន វាមិនខាំមនុស្សទេ។"},{"who":"You","hz":"你每天带它出来散步吗？","py":"Nǐ měi tiān dài tā chūlái sànbù ma?","en":"Do you take it out for a walk every day?","km":"ប្អូននាំវាមកដើរលេងរៀងរាល់ថ្ងៃទេ?"},{"who":"Girl","hz":"对，早上和晚上各一次。你喜欢狗还是猫？","py":"Duì, zǎoshang hé wǎnshang gè yí cì. Nǐ xǐhuan gǒu háishi māo?","en":"Yes, once in the morning and once in the evening. Do you like dogs or cats?","km":"ត្រូវ ពេលព្រឹកម្តង ពេលល្ងាចម្តង។ បងចូលចិត្តឆ្កែ ឬឆ្មា?"},{"who":"You","hz":"我都喜欢！我家有一只猫。","py":"Wǒ dōu xǐhuan! Wǒ jiā yǒu yì zhī māo.","en":"I like both! I have a cat at home.","km":"ខ្ញុំចូលចិត្តទាំងពីរ! ផ្ទះខ្ញុំមានឆ្មាមួយ។"}],"phrases":[{"hz":"宠物","py":"chǒngwù","en":"Pet","km":"សត្វចិញ្ចឹម"},{"hz":"小狗 / 小猫","py":"xiǎo gǒu / xiǎo māo","en":"Puppy / kitten","km":"កូនឆ្កែ / កូនឆ្មា"},{"hz":"好可爱！","py":"hǎo kě'ài!","en":"So cute!","km":"គួរឱ្យស្រឡាញ់ណាស់!"},{"hz":"它不咬人","py":"tā bù yǎo rén","en":"It doesn't bite","km":"វាមិនខាំមនុស្សទេ"},{"hz":"散步","py":"sànbù","en":"Go for a walk","km":"ដើរលេង"},{"hz":"一只猫","py":"yì zhī māo","en":"A cat","km":"ឆ្មាមួយ"}],"tips":[{"label":"它 for animals","html":"<span class=\"zh\">他</span> he, <span class=\"zh\">她</span> she, <span class=\"zh\">它</span> it — all pronounced <em>tā</em>. Animals and things use <span class=\"zh\">它</span>.","culture":false}]},
{"n":60,"ch":5,"title":"Breakfast with the Family","titleZh":"一家人吃早饭","titleKm":"ញ៉ាំអាហារពេលព្រឹកជាមួយគ្រួសារ","art":"home bowl shirt f","scene":"You are staying with a Chinese host family. Mum is making breakfast.","dialogue":[{"who":"Mum","hz":"起来了？睡得好吗？","py":"Qǐlái le? Shuì de hǎo ma?","en":"You're up? Did you sleep well?","km":"ក្រោកហើយ? គេងលក់ស្រួលទេ?"},{"who":"You","hz":"睡得很好，谢谢阿姨。","py":"Shuì de hěn hǎo, xièxie āyí.","en":"I slept very well, thank you, auntie.","km":"គេងលក់ស្រួលណាស់ អរគុណអ៊ីង។"},{"who":"Mum","hz":"早饭有粥、鸡蛋和面包，你想吃什么？","py":"Zǎofàn yǒu zhōu, jīdàn hé miànbāo, nǐ xiǎng chī shénme?","en":"There's rice porridge, eggs and bread — what would you like?","km":"អាហារពេលព្រឹកមានបបរ ពងមាន់ និងនំប៉័ង ចង់ញ៉ាំអ្វី?"},{"who":"You","hz":"我想喝粥。有什么我可以帮忙的吗？","py":"Wǒ xiǎng hē zhōu. Yǒu shénme wǒ kěyǐ bāngmáng de ma?","en":"I'd like porridge. Is there anything I can help with?","km":"ខ្ញុំចង់ញ៉ាំបបរ។ មានអ្វីដែលខ្ញុំអាចជួយបានទេ?"},{"who":"Mum","hz":"你帮我拿一下碗和筷子吧。","py":"Nǐ bāng wǒ ná yíxià wǎn hé kuàizi ba.","en":"Could you get the bowls and chopsticks for me?","km":"ជួយយកចាន និងចង្កឹះឱ្យខ្ញុំបន្តិចមក។"},{"who":"You","hz":"好的。今天您要去上班吗？","py":"Hǎo de. Jīntiān nín yào qù shàngbān ma?","en":"Sure. Are you going to work today?","km":"បាទ/ចាស។ ថ្ងៃនេះអ៊ីងទៅធ្វើការទេ?"},{"who":"Mum","hz":"要去。晚上我们一起包饺子！","py":"Yào qù. Wǎnshang wǒmen yìqǐ bāo jiǎozi!","en":"Yes. This evening we'll make dumplings together!","km":"ទៅ។ ល្ងាចនេះយើងខ្ចប់នំចំហុយជាមួយគ្នា!"}],"phrases":[{"hz":"睡得好吗？","py":"shuì de hǎo ma?","en":"Did you sleep well?","km":"គេងលក់ស្រួលទេ?"},{"hz":"粥","py":"zhōu","en":"Rice porridge","km":"បបរ"},{"hz":"面包","py":"miànbāo","en":"Bread","km":"នំប៉័ង"},{"hz":"我可以帮忙吗？","py":"wǒ kěyǐ bāngmáng ma?","en":"Can I help?","km":"ខ្ញុំអាចជួយបានទេ?"},{"hz":"碗和筷子","py":"wǎn hé kuàizi","en":"Bowls and chopsticks","km":"ចាន និងចង្កឹះ"},{"hz":"包饺子","py":"bāo jiǎozi","en":"Make (wrap) dumplings","km":"ខ្ចប់នំចំហុយ"}],"tips":[{"label":"Verb + 得 + how","html":"To say how well something is done, use <span class=\"zh\">得</span>: <span class=\"zh\">睡得很好</span> slept well, <span class=\"zh\">说得很快</span> speaks fast.","culture":false}]},
{"n":61,"ch":6,"title":"First Day at Work","titleZh":"第一天上班","titleKm":"ថ្ងៃដំបូងចូលធ្វើការ","art":"office briefcase suit f","scene":"Your manager shows you around the office on your first day.","dialogue":[{"who":"Manager","hz":"欢迎加入我们公司！","py":"Huānyíng jiārù wǒmen gōngsī!","en":"Welcome to our company!","km":"សូមស្វាគមន៍ចូលរួមក្រុមហ៊ុនយើង!"},{"who":"You","hz":"谢谢！我很高兴能在这儿工作。","py":"Xièxie! Wǒ hěn gāoxìng néng zài zhèr gōngzuò.","en":"Thank you! I'm very happy to work here.","km":"អរគុណ! ខ្ញុំរីករាយណាស់ដែលបានធ្វើការនៅទីនេះ។"},{"who":"Manager","hz":"这是你的办公桌。电脑已经准备好了。","py":"Zhè shì nǐ de bàngōngzhuō. Diànnǎo yǐjīng zhǔnbèi hǎo le.","en":"This is your desk. The computer is already set up.","km":"នេះជាតុការិយាល័យរបស់អ្នក។ កុំព្យូទ័ររៀបចំរួចហើយ។"},{"who":"You","hz":"请问，会议室在哪儿？","py":"Qǐngwèn, huìyìshì zài nǎr?","en":"May I ask, where is the meeting room?","km":"សុំសួរ បន្ទប់ប្រជុំនៅឯណា?"},{"who":"Manager","hz":"在走廊尽头。有问题可以问小王。","py":"Zài zǒuláng jìntóu. Yǒu wèntí kěyǐ wèn Xiǎo Wáng.","en":"At the end of the corridor. If you have questions, ask Xiao Wang.","km":"នៅចុងច្រករបៀង។ មានសំណួរអាចសួរសៅវ៉ាងបាន។"},{"who":"You","hz":"好的。我们几点吃午饭？","py":"Hǎo de. Wǒmen jǐ diǎn chī wǔfàn?","en":"OK. What time do we have lunch?","km":"បាទ/ចាស។ យើងញ៉ាំអាហារថ្ងៃត្រង់ម៉ោងប៉ុន្មាន?"},{"who":"Manager","hz":"十二点到一点半。加油！","py":"Shí'èr diǎn dào yī diǎn bàn. Jiāyóu!","en":"From twelve to half past one. Good luck!","km":"ពីម៉ោងដប់ពីរ ដល់ម៉ោងមួយកន្លះ។ ខំប្រឹងណា!"}],"phrases":[{"hz":"公司","py":"gōngsī","en":"Company","km":"ក្រុមហ៊ុន"},{"hz":"办公桌","py":"bàngōngzhuō","en":"Office desk","km":"តុការិយាល័យ"},{"hz":"会议室","py":"huìyìshì","en":"Meeting room","km":"បន្ទប់ប្រជុំ"},{"hz":"同事","py":"tóngshì","en":"Colleague","km":"មិត្តរួមការងារ"},{"hz":"有问题可以问我","py":"yǒu wèntí kěyǐ wèn wǒ","en":"Ask me if you have questions","km":"មានសំណួរអាចសួរខ្ញុំបាន"},{"hz":"加油！","py":"jiāyóu!","en":"Go for it! / Good luck!","km":"ខំប្រឹងណា!"}],"tips":[{"label":"小 and 老","html":"Colleagues often call each other <span class=\"zh\">小</span> + surname (younger) or <span class=\"zh\">老</span> + surname (older): <span class=\"zh\">小王</span>, <span class=\"zh\">老李</span>.","culture":true}]},
{"n":62,"ch":6,"title":"A Job Interview","titleZh":"面试","titleKm":"សម្ភាសន៍ការងារ","art":"office clipboard suit m","scene":"You are being interviewed for a job at a Chinese trading company in Phnom Penh.","dialogue":[{"who":"Interviewer","hz":"请先简单介绍一下你自己。","py":"Qǐng xiān jiǎndān jièshào yíxià nǐ zìjǐ.","en":"First, please briefly introduce yourself.","km":"សូមណែនាំខ្លួនឯងដោយសង្ខេបជាមុនសិន។"},{"who":"You","hz":"我叫索披，大学学的是会计。","py":"Wǒ jiào Suǒ Pī, dàxué xué de shì kuàijì.","en":"My name is Sophy. I studied accounting at university.","km":"ខ្ញុំឈ្មោះសុភី នៅសាកលវិទ្យាល័យខ្ញុំរៀនគណនេយ្យ។"},{"who":"Interviewer","hz":"你有工作经验吗？","py":"Nǐ yǒu gōngzuò jīngyàn ma?","en":"Do you have work experience?","km":"អ្នកមានបទពិសោធន៍ការងារទេ?"},{"who":"You","hz":"有，我在一家银行工作了两年。","py":"Yǒu, wǒ zài yì jiā yínháng gōngzuò le liǎng nián.","en":"Yes, I worked at a bank for two years.","km":"មាន ខ្ញុំធ្វើការនៅធនាគារមួយរយៈពេលពីរឆ្នាំ។"},{"who":"Interviewer","hz":"你为什么想来我们公司？","py":"Nǐ wèishénme xiǎng lái wǒmen gōngsī?","en":"Why do you want to join our company?","km":"ហេតុអ្វីបានជាអ្នកចង់មកក្រុមហ៊ុនយើង?"},{"who":"You","hz":"因为我会说中文和英语，也想多学习国际贸易。","py":"Yīnwèi wǒ huì shuō Zhōngwén hé Yīngyǔ, yě xiǎng duō xuéxí guójì màoyì.","en":"Because I speak Chinese and English, and I want to learn more about international trade.","km":"ព្រោះខ្ញុំចេះនិយាយភាសាចិន និងអង់គ្លេស ហើយក៏ចង់រៀនបន្ថែមអំពីពាណិជ្ជកម្មអន្តរជាតិ។"},{"who":"Interviewer","hz":"很好。你什么时候可以开始上班？","py":"Hěn hǎo. Nǐ shénme shíhou kěyǐ kāishǐ shàngbān?","en":"Very good. When could you start?","km":"ល្អណាស់។ អ្នកអាចចាប់ផ្តើមធ្វើការនៅពេលណា?"},{"who":"You","hz":"下个月一号就可以。","py":"Xià ge yuè yī hào jiù kěyǐ.","en":"I can start on the first of next month.","km":"ថ្ងៃទីមួយខែក្រោយក៏បាន។"}],"phrases":[{"hz":"面试","py":"miànshì","en":"Job interview","km":"សម្ភាសន៍ការងារ"},{"hz":"工作经验","py":"gōngzuò jīngyàn","en":"Work experience","km":"បទពិសោធន៍ការងារ"},{"hz":"我学的是……","py":"wǒ xué de shì…","en":"I studied…","km":"ខ្ញុំរៀនជំនាញ…"},{"hz":"工作了两年","py":"gōngzuò le liǎng nián","en":"Worked for two years","km":"បានធ្វើការពីរឆ្នាំ"},{"hz":"开始上班","py":"kāishǐ shàngbān","en":"Start work","km":"ចាប់ផ្តើមធ្វើការ"},{"hz":"下个月","py":"xià ge yuè","en":"Next month","km":"ខែក្រោយ"}],"tips":[{"label":"How long: verb + 了 + time","html":"Duration comes after the verb: <span class=\"zh\">我学了三年中文</span> — I studied Chinese for three years.","culture":false}]},
{"n":63,"ch":6,"title":"Meeting a Client","titleZh":"见客户","titleKm":"ជួបអតិថិជន","art":"office card suit m","scene":"A client from Shanghai visits your office. You meet him at reception.","dialogue":[{"who":"You","hz":"张总，您好！欢迎您来金边。","py":"Zhāng zǒng, nín hǎo! Huānyíng nín lái Jīnbiān.","en":"Mr Zhang, hello! Welcome to Phnom Penh.","km":"លោកនាយកចាង ជម្រាបសួរ! សូមស្វាគមន៍មកកាន់ភ្នំពេញ។"},{"who":"Client","hz":"你好！这是我的名片。","py":"Nǐ hǎo! Zhè shì wǒ de míngpiàn.","en":"Hello! Here's my business card.","km":"សួស្តី! នេះជាកាតរបស់ខ្ញុំ។"},{"who":"You","hz":"谢谢。这是我的。我是销售部的经理。","py":"Xièxie. Zhè shì wǒ de. Wǒ shì xiāoshòubù de jīnglǐ.","en":"Thank you. Here's mine. I'm the sales manager.","km":"អរគុណ។ នេះជារបស់ខ្ញុំ។ ខ្ញុំជាប្រធានផ្នែកលក់។"},{"who":"Client","hz":"一路上很顺利。这里比上海热多了！","py":"Yílù shang hěn shùnlì. Zhèli bǐ Shànghǎi rè duō le!","en":"The trip went smoothly. It's much hotter here than in Shanghai!","km":"ការធ្វើដំណើររលូនល្អ។ នៅទីនេះក្តៅជាងសៀងហៃច្រើន!"},{"who":"You","hz":"是啊，请到会议室坐，喝杯咖啡。","py":"Shì a, qǐng dào huìyìshì zuò, hē bēi kāfēi.","en":"Yes! Please come and sit in the meeting room for a coffee.","km":"មែនហើយ អញ្ជើញទៅអង្គុយក្នុងបន្ទប់ប្រជុំ ពិសាកាហ្វេមួយកែវ។"},{"who":"Client","hz":"好，我们开始谈吧。","py":"Hǎo, wǒmen kāishǐ tán ba.","en":"Great, let's start talking business.","km":"ល្អ យើងចាប់ផ្តើមពិភាក្សាទៅ។"}],"phrases":[{"hz":"名片","py":"míngpiàn","en":"Business card","km":"កាតឈ្មោះ"},{"hz":"客户","py":"kèhù","en":"Client","km":"អតិថិជន"},{"hz":"经理","py":"jīnglǐ","en":"Manager","km":"អ្នកគ្រប់គ្រង"},{"hz":"销售部","py":"xiāoshòubù","en":"Sales department","km":"ផ្នែកលក់"},{"hz":"一路上顺利吗？","py":"yílù shang shùnlì ma?","en":"Did you have a good trip?","km":"ធ្វើដំណើររលូនទេ?"},{"hz":"比……热","py":"bǐ … rè","en":"Hotter than…","km":"ក្តៅជាង…"}],"tips":[{"label":"Cards with both hands","html":"Give and receive business cards with both hands, read the card for a moment, and don't put it straight into your back pocket.","culture":true},{"label":"Titles","html":"Bosses are often called by surname + <span class=\"zh\">总</span> (from <span class=\"zh\">总经理</span>, general manager): <span class=\"zh\">张总</span>.","culture":true}]},
{"n":64,"ch":6,"title":"Taking a Phone Message","titleZh":"接电话留言","titleKm":"ទទួលទូរសព្ទ និងកត់សារ","art":"office phone suit f","scene":"Your boss is out. A supplier calls the office.","dialogue":[{"who":"You","hz":"您好，亚太贸易公司。","py":"Nín hǎo, Yàtài Màoyì Gōngsī.","en":"Hello, Asia-Pacific Trading.","km":"ជម្រាបសួរ ក្រុមហ៊ុនពាណិជ្ជកម្មអាស៊ីប៉ាស៊ីហ្វិក។"},{"who":"Caller","hz":"你好，我找李经理。","py":"Nǐ hǎo, wǒ zhǎo Lǐ jīnglǐ.","en":"Hello, I'd like to speak to Manager Li.","km":"សួស្តី ខ្ញុំចង់និយាយជាមួយលោកប្រធានលី។"},{"who":"You","hz":"不好意思，他现在不在。请问您是哪位？","py":"Bù hǎoyìsi, tā xiànzài bú zài. Qǐngwèn nín shì nǎ wèi?","en":"Sorry, he's not in right now. May I ask who's calling?","km":"សុំទោស គាត់មិននៅទេឥឡូវនេះ។ សុំសួរ លោកជានរណា?"},{"who":"Caller","hz":"我是工厂的陈明。他什么时候回来？","py":"Wǒ shì gōngchǎng de Chén Míng. Tā shénme shíhou huílái?","en":"I'm Chen Ming from the factory. When will he be back?","km":"ខ្ញុំជាចិនមីញ មកពីរោងចក្រ។ គាត់ត្រឡប់មកវិញពេលណា?"},{"who":"You","hz":"下午三点左右。您要留言吗？","py":"Xiàwǔ sān diǎn zuǒyòu. Nín yào liúyán ma?","en":"Around 3 pm. Would you like to leave a message?","km":"ប្រហែលម៉ោងបីរសៀល។ លោកចង់ទុកសារទេ?"},{"who":"Caller","hz":"请他给我回个电话。","py":"Qǐng tā gěi wǒ huí ge diànhuà.","en":"Please ask him to call me back.","km":"សូមប្រាប់គាត់ឱ្យទូរសព្ទមកខ្ញុំវិញ។"},{"who":"You","hz":"好的，我一定转告他。","py":"Hǎo de, wǒ yídìng zhuǎngào tā.","en":"Certainly, I'll be sure to tell him.","km":"បាទ/ចាស ខ្ញុំនឹងប្រាប់គាត់ដាច់ខាត។"}],"phrases":[{"hz":"我找……","py":"wǒ zhǎo…","en":"I'm looking for… / May I speak to…","km":"ខ្ញុំរក… / ខ្ញុំចង់និយាយជាមួយ…"},{"hz":"他不在","py":"tā bú zài","en":"He's not in","km":"គាត់មិននៅទេ"},{"hz":"您是哪位？","py":"nín shì nǎ wèi?","en":"Who's calling, please?","km":"លោកជានរណា?"},{"hz":"留言","py":"liúyán","en":"Leave a message","km":"ទុកសារ"},{"hz":"回电话","py":"huí diànhuà","en":"Call back","km":"ទូរសព្ទមកវិញ"},{"hz":"我一定转告他","py":"wǒ yídìng zhuǎngào tā","en":"I'll be sure to pass it on","km":"ខ្ញុំនឹងប្រាប់គាត់ដាច់ខាត"}],"tips":[{"label":"Answer with the company","html":"At work, answer the phone with <span class=\"zh\">您好</span> + the company name, not <span class=\"zh\">喂</span>.","culture":true}]},
{"n":65,"ch":6,"title":"Arranging a Meeting","titleZh":"安排开会","titleKm":"រៀបចំការប្រជុំ","art":"office calendar suit f","scene":"You need to set up a project meeting with a colleague from another department.","dialogue":[{"who":"You","hz":"刘姐，我们下周开个会，讨论一下新项目。","py":"Liú jiě, wǒmen xià zhōu kāi ge huì, tǎolùn yíxià xīn xiàngmù.","en":"Sister Liu, let's have a meeting next week to discuss the new project.","km":"បងលីវ យើងប្រជុំមួយនៅសប្តាហ៍ក្រោយ ដើម្បីពិភាក្សាគម្រោងថ្មី។"},{"who":"Colleague","hz":"好啊。周二上午我有空。","py":"Hǎo a. Zhōu'èr shàngwǔ wǒ yǒu kòng.","en":"Sure. I'm free Tuesday morning.","km":"បាន។ ព្រឹកថ្ងៃអង្គារខ្ញុំទំនេរ។"},{"who":"You","hz":"周二上午我要见客户。周三下午呢？","py":"Zhōu'èr shàngwǔ wǒ yào jiàn kèhù. Zhōusān xiàwǔ ne?","en":"I'm seeing a client Tuesday morning. How about Wednesday afternoon?","km":"ព្រឹកថ្ងៃអង្គារខ្ញុំត្រូវជួបអតិថិជន។ ចុះរសៀលថ្ងៃពុធ?"},{"who":"Colleague","hz":"周三下午两点可以。开多长时间？","py":"Zhōusān xiàwǔ liǎng diǎn kěyǐ. Kāi duō cháng shíjiān?","en":"Wednesday at 2 pm works. How long will it be?","km":"រសៀលថ្ងៃពុធម៉ោងពីរបាន។ ប្រជុំប៉ុន្មានម៉ោង?"},{"who":"You","hz":"一个小时左右。我来订会议室。","py":"Yí ge xiǎoshí zuǒyòu. Wǒ lái dìng huìyìshì.","en":"About an hour. I'll book the meeting room.","km":"ប្រហែលមួយម៉ោង។ ខ្ញុំនឹងកក់បន្ទប់ប្រជុំ។"},{"who":"Colleague","hz":"好，你发个日程给我吧。","py":"Hǎo, nǐ fā ge rìchéng gěi wǒ ba.","en":"OK, send me a calendar invite.","km":"ល្អ ផ្ញើកាលវិភាគមកខ្ញុំផង។"}],"phrases":[{"hz":"开会","py":"kāihuì","en":"Have a meeting","km":"ប្រជុំ"},{"hz":"讨论","py":"tǎolùn","en":"Discuss","km":"ពិភាក្សា"},{"hz":"项目","py":"xiàngmù","en":"Project","km":"គម្រោង"},{"hz":"下周","py":"xià zhōu","en":"Next week","km":"សប្តាហ៍ក្រោយ"},{"hz":"订会议室","py":"dìng huìyìshì","en":"Book the meeting room","km":"កក់បន្ទប់ប្រជុំ"},{"hz":"我有空 / 我没空","py":"wǒ yǒu kòng / wǒ méi kòng","en":"I'm free / I'm busy","km":"ខ្ញុំទំនេរ / ខ្ញុំមិនទំនេរ"}],"tips":[{"label":"姐 and 哥 at work","html":"Friendly colleagues slightly older than you are often called surname + <span class=\"zh\">姐</span> (sister) or <span class=\"zh\">哥</span> (brother).","culture":true}]},
{"n":66,"ch":6,"title":"Asking a Colleague for Help","titleZh":"请同事帮忙","titleKm":"សុំជំនួយពីមិត្តរួមការងារ","art":"office chart suit m","scene":"You are stuck on a spreadsheet and ask the colleague at the next desk.","dialogue":[{"who":"You","hz":"小王，你现在忙吗？能帮我一个忙吗？","py":"Xiǎo Wáng, nǐ xiànzài máng ma? Néng bāng wǒ yí ge máng ma?","en":"Xiao Wang, are you busy? Could you do me a favour?","km":"សៅវ៉ាង ឥឡូវរវល់ទេ? អាចជួយខ្ញុំបន្តិចបានទេ?"},{"who":"Colleague","hz":"不忙，怎么了？","py":"Bù máng, zěnme le?","en":"Not busy. What's up?","km":"មិនរវល់ទេ មានរឿងអី?"},{"who":"You","hz":"这个表格的公式我不会用。","py":"Zhège biǎogé de gōngshì wǒ bú huì yòng.","en":"I don't know how to use the formula in this spreadsheet.","km":"រូបមន្តក្នុងតារាងនេះ ខ្ញុំមិនចេះប្រើទេ។"},{"who":"Colleague","hz":"我看看……你先选这一列，然后点这里。","py":"Wǒ kànkan… nǐ xiān xuǎn zhè yí liè, ránhòu diǎn zhèli.","en":"Let me see… first select this column, then click here.","km":"ខ្ញុំមើលសិន… អ្នកជ្រើសជួរឈរនេះសិន រួចចុចត្រង់នេះ។"},{"who":"You","hz":"哦，原来这么简单！","py":"Ò, yuánlái zhème jiǎndān!","en":"Oh, so it's that simple!","km":"អូ៎ តាមពិតងាយម្ល៉េះ!"},{"who":"Colleague","hz":"以后有问题随时问我。","py":"Yǐhòu yǒu wèntí suíshí wèn wǒ.","en":"Ask me any time you have a question.","km":"ពេលក្រោយមានបញ្ហា សួរខ្ញុំបានគ្រប់ពេល។"},{"who":"You","hz":"太感谢了，我请你喝咖啡！","py":"Tài gǎnxiè le, wǒ qǐng nǐ hē kāfēi!","en":"Thanks so much — coffee's on me!","km":"អរគុណច្រើន ខ្ញុំចេញកាហ្វេឱ្យ!"}],"phrases":[{"hz":"能帮我一个忙吗？","py":"néng bāng wǒ yí ge máng ma?","en":"Could you do me a favour?","km":"អាចជួយខ្ញុំបន្តិចបានទេ?"},{"hz":"怎么了？","py":"zěnme le?","en":"What's the matter?","km":"មានរឿងអី?"},{"hz":"我不会用","py":"wǒ bú huì yòng","en":"I don't know how to use it","km":"ខ្ញុំមិនចេះប្រើ"},{"hz":"原来这么简单","py":"yuánlái zhème jiǎndān","en":"So it's that simple","km":"តាមពិតងាយម្ល៉េះ"},{"hz":"随时","py":"suíshí","en":"At any time","km":"គ្រប់ពេល"},{"hz":"表格","py":"biǎogé","en":"Table / spreadsheet / form","km":"តារាង"}],"tips":[{"label":"会 = know how to","html":"<span class=\"zh\">会</span> is a learned skill: <span class=\"zh\">我会说中文</span>, <span class=\"zh\">我会开车</span>. <span class=\"zh\">能</span> is being able to in the situation.","culture":false}]},
{"n":67,"ch":6,"title":"Asking for Leave","titleZh":"请假","titleKm":"សុំច្បាប់","art":"office envelope suit f","scene":"Your sister is getting married and you need two days off.","dialogue":[{"who":"You","hz":"经理，我想请两天假。","py":"Jīnglǐ, wǒ xiǎng qǐng liǎng tiān jià.","en":"Manager, I'd like to ask for two days off.","km":"លោកប្រធាន ខ្ញុំចង់សុំច្បាប់ពីរថ្ងៃ។"},{"who":"Manager","hz":"什么事？","py":"Shénme shì?","en":"What's it for?","km":"មានរឿងអី?"},{"who":"You","hz":"我姐姐下周五结婚，我要回老家。","py":"Wǒ jiějie xià zhōuwǔ jiéhūn, wǒ yào huí lǎojiā.","en":"My older sister is getting married next Friday — I need to go back to my home town.","km":"បងស្រីខ្ញុំរៀបការថ្ងៃសុក្រក្រោយ ខ្ញុំត្រូវទៅស្រុកកំណើត។"},{"who":"Manager","hz":"恭喜！你的工作谁来做？","py":"Gōngxǐ! Nǐ de gōngzuò shéi lái zuò?","en":"Congratulations! Who will do your work?","km":"សូមអបអរ! ការងាររបស់អ្នក នរណាធ្វើជំនួស?"},{"who":"You","hz":"我已经跟小王说好了，他帮我。","py":"Wǒ yǐjīng gēn Xiǎo Wáng shuō hǎo le, tā bāng wǒ.","en":"I've already arranged it with Xiao Wang — he'll cover for me.","km":"ខ្ញុំបាននិយាយជាមួយសៅវ៉ាងរួចហើយ គាត់ជួយខ្ញុំ។"},{"who":"Manager","hz":"好，在系统里填一下请假单。","py":"Hǎo, zài xìtǒng li tián yíxià qǐngjià dān.","en":"OK, fill in a leave form in the system.","km":"បាន បំពេញពាក្យសុំច្បាប់ក្នុងប្រព័ន្ធ។"},{"who":"You","hz":"好的，谢谢经理！","py":"Hǎo de, xièxie jīnglǐ!","en":"Will do — thank you!","km":"បាទ/ចាស អរគុណលោកប្រធាន!"}],"phrases":[{"hz":"请假","py":"qǐngjià","en":"Ask for leave","km":"សុំច្បាប់"},{"hz":"请两天假","py":"qǐng liǎng tiān jià","en":"Ask for two days off","km":"សុំច្បាប់ពីរថ្ងៃ"},{"hz":"病假","py":"bìngjià","en":"Sick leave","km":"ច្បាប់ឈឺ"},{"hz":"回老家","py":"huí lǎojiā","en":"Go back to one's home town","km":"ទៅស្រុកកំណើត"},{"hz":"结婚","py":"jiéhūn","en":"Get married","km":"រៀបការ"},{"hz":"恭喜！","py":"gōngxǐ!","en":"Congratulations!","km":"សូមអបអរ!"}],"tips":[{"label":"Split verbs","html":"Some verbs split open: <span class=\"zh\">请假</span> → <span class=\"zh\">请两天假</span>; <span class=\"zh\">见面</span> → <span class=\"zh\">见个面</span>.","culture":false}]},
{"n":68,"ch":6,"title":"The Deadline","titleZh":"截止日期","titleKm":"ថ្ងៃផុតកំណត់","art":"office chart suit m","scene":"Your manager asks how the monthly report is going.","dialogue":[{"who":"Manager","hz":"月报写得怎么样了？","py":"Yuèbào xiě de zěnmeyàng le?","en":"How's the monthly report going?","km":"របាយការណ៍ប្រចាំខែសរសេរដល់ណាហើយ?"},{"who":"You","hz":"差不多了，还差最后一部分。","py":"Chàbuduō le, hái chà zuìhòu yí bùfen.","en":"Almost done — just the last section to go.","km":"ជិតរួចហើយ នៅខ្វះផ្នែកចុងក្រោយមួយទៀត។"},{"who":"Manager","hz":"星期五以前能交吗？","py":"Xīngqīwǔ yǐqián néng jiāo ma?","en":"Can you hand it in before Friday?","km":"អាចប្រគល់មុនថ្ងៃសុក្របានទេ?"},{"who":"You","hz":"没问题，我星期四下班前发给您。","py":"Méi wèntí, wǒ xīngqīsì xiàbān qián fā gěi nín.","en":"No problem — I'll send it to you before the end of Thursday.","km":"គ្មានបញ្ហា ខ្ញុំនឹងផ្ញើជូនលោកមុនចេញពីការងារថ្ងៃព្រហស្បតិ៍។"},{"who":"Manager","hz":"别忘了加上销售数据。","py":"Bié wàng le jiā shang xiāoshòu shùjù.","en":"Don't forget to add the sales figures.","km":"កុំភ្លេចបន្ថែមទិន្នន័យលក់។"},{"who":"You","hz":"好的，我记下来了。","py":"Hǎo de, wǒ jì xiàlái le.","en":"OK, I've made a note of it.","km":"បាទ/ចាស ខ្ញុំកត់ទុកហើយ។"}],"phrases":[{"hz":"报告","py":"bàogào","en":"Report","km":"របាយការណ៍"},{"hz":"差不多了","py":"chàbuduō le","en":"Almost done","km":"ជិតរួចហើយ"},{"hz":"……以前","py":"… yǐqián","en":"Before …","km":"មុន…"},{"hz":"交","py":"jiāo","en":"Hand in","km":"ប្រគល់"},{"hz":"别忘了","py":"bié wàng le","en":"Don't forget","km":"កុំភ្លេច"},{"hz":"我记下来了","py":"wǒ jì xiàlái le","en":"I've noted it down","km":"ខ្ញុំកត់ទុកហើយ"}],"tips":[{"label":"差 = short of","html":"<span class=\"zh\">差</span> means “lacking”: <span class=\"zh\">还差一点儿</span> — just a little left; <span class=\"zh\">差五分八点</span> — five to eight.","culture":false}]},
{"n":69,"ch":6,"title":"Lunch with Colleagues","titleZh":"和同事吃午饭","titleKm":"ញ៉ាំអាហារថ្ងៃត្រង់ជាមួយមិត្តរួមការងារ","art":"restaurant rice suit f","scene":"At noon your colleagues invite you to the noodle shop downstairs.","dialogue":[{"who":"Colleague","hz":"中午一起吃饭吗？","py":"Zhōngwǔ yìqǐ chī fàn ma?","en":"Shall we eat together at lunch?","km":"ថ្ងៃត្រង់ញ៉ាំបាយជាមួយគ្នាទេ?"},{"who":"You","hz":"好啊，去哪儿吃？","py":"Hǎo a, qù nǎr chī?","en":"Sure, where shall we go?","km":"បាន ទៅញ៉ាំនៅឯណា?"},{"who":"Colleague","hz":"楼下新开了一家面馆，听说不错。","py":"Lóuxià xīn kāi le yì jiā miànguǎn, tīngshuō búcuò.","en":"A new noodle shop opened downstairs — I hear it's good.","km":"នៅខាងក្រោមទើបបើកហាងមីថ្មីមួយ ឮថាល្អ។"},{"who":"You","hz":"我还没吃过。你们常吃什么？","py":"Wǒ hái méi chīguo. Nǐmen cháng chī shénme?","en":"I haven't tried it yet. What do you usually get?","km":"ខ្ញុំមិនទាន់ធ្លាប់ញ៉ាំទេ។ អ្នកទាំងអស់គ្នាតែងញ៉ាំអ្វី?"},{"who":"Colleague","hz":"牛肉面最有名，又便宜又好吃。","py":"Niúròu miàn zuì yǒumíng, yòu piányi yòu hǎochī.","en":"The beef noodles are the most famous — cheap and tasty.","km":"មីសាច់គោល្បីជាងគេ ទាំងថោក ទាំងឆ្ងាញ់។"},{"who":"You","hz":"那我也试试。我们几点下去？","py":"Nà wǒ yě shìshi. Wǒmen jǐ diǎn xiàqù?","en":"Then I'll try it too. What time shall we go down?","km":"អញ្ចឹងខ្ញុំក៏សាកដែរ។ យើងចុះទៅម៉ោងប៉ុន្មាន?"},{"who":"Colleague","hz":"十二点准时走，不然要排队。","py":"Shí'èr diǎn zhǔnshí zǒu, bùrán yào páiduì.","en":"Twelve on the dot, or we'll have to queue.","km":"ម៉ោងដប់ពីរគត់ ចេញដំណើរ បើមិនដូច្នោះទេត្រូវតម្រង់ជួរ។"}],"phrases":[{"hz":"一起吃饭吗？","py":"yìqǐ chī fàn ma?","en":"Shall we eat together?","km":"ញ៉ាំបាយជាមួយគ្នាទេ?"},{"hz":"听说","py":"tīngshuō","en":"I hear that…","km":"ឮថា…"},{"hz":"我还没……过","py":"wǒ hái méi … guo","en":"I haven't … yet","km":"ខ្ញុំមិនទាន់ធ្លាប់…"},{"hz":"又便宜又好吃","py":"yòu piányi yòu hǎochī","en":"Both cheap and tasty","km":"ទាំងថោក ទាំងឆ្ងាញ់"},{"hz":"准时","py":"zhǔnshí","en":"On time","km":"ទាន់ពេល"},{"hz":"排队","py":"páiduì","en":"Queue up","km":"តម្រង់ជួរ"}],"tips":[{"label":"又……又……","html":"“Both … and …”: <span class=\"zh\">又高又帅</span> tall and handsome, <span class=\"zh\">又快又好</span> fast and good.","culture":false}]},
{"n":70,"ch":6,"title":"Negotiating a Price","titleZh":"谈价格","titleKm":"ចរចាតម្លៃ","art":"office contract suit m","scene":"You are buying 2,000 T-shirts from a Chinese supplier for your company.","dialogue":[{"who":"Supplier","hz":"这款T恤每件二十五块。","py":"Zhè kuǎn T xù měi jiàn èrshíwǔ kuài.","en":"This T-shirt is 25 yuan each.","km":"អាវយឺតម៉ូដនេះ មួយ ម្ភៃប្រាំយ័ន។"},{"who":"You","hz":"我们要两千件，能打个折吗？","py":"Wǒmen yào liǎngqiān jiàn, néng dǎ ge zhé ma?","en":"We need two thousand — can you give us a discount?","km":"យើងត្រូវការពីរពាន់ អាចបញ្ចុះតម្លៃបានទេ?"},{"who":"Supplier","hz":"两千件的话，每件二十二。","py":"Liǎngqiān jiàn de huà, měi jiàn èrshí'èr.","en":"For two thousand, 22 each.","km":"បើពីរពាន់ មួយម្ភៃពីរ។"},{"who":"You","hz":"二十块可以吗？我们以后会长期合作。","py":"Èrshí kuài kěyǐ ma? Wǒmen yǐhòu huì chángqī hézuò.","en":"Could you do 20? We'll work together long-term.","km":"ម្ភៃយ័នបានទេ? យើងនឹងសហការគ្នារយៈពេលវែង។"},{"who":"Supplier","hz":"二十一，这是最低价了，包运费。","py":"Èrshíyī, zhè shì zuì dī jià le, bāo yùnfèi.","en":"Twenty-one — that's the lowest, shipping included.","km":"ម្ភៃមួយ នេះជាតម្លៃទាបបំផុតហើយ រួមទាំងថ្លៃដឹក។"},{"who":"You","hz":"好，成交。什么时候能交货？","py":"Hǎo, chéngjiāo. Shénme shíhou néng jiāohuò?","en":"OK, deal. When can you deliver?","km":"បាន ព្រមព្រៀង។ ពេលណាអាចប្រគល់ទំនិញបាន?"},{"who":"Supplier","hz":"签合同以后两个星期。","py":"Qiān hétong yǐhòu liǎng ge xīngqī.","en":"Two weeks after we sign the contract.","km":"ពីរសប្តាហ៍ក្រោយចុះហត្ថលេខាលើកិច្ចសន្យា។"}],"phrases":[{"hz":"打个折","py":"dǎ ge zhé","en":"Give a discount","km":"បញ្ចុះតម្លៃ"},{"hz":"每件","py":"měi jiàn","en":"Each (piece)","km":"មួយៗ"},{"hz":"长期合作","py":"chángqī hézuò","en":"Long-term cooperation","km":"សហការរយៈពេលវែង"},{"hz":"包运费","py":"bāo yùnfèi","en":"Shipping included","km":"រួមថ្លៃដឹក"},{"hz":"交货","py":"jiāohuò","en":"Deliver goods","km":"ប្រគល់ទំនិញ"},{"hz":"签合同","py":"qiān hétong","en":"Sign a contract","km":"ចុះហត្ថលេខាលើកិច្ចសន្យា"}],"tips":[{"label":"Relationships first","html":"In Chinese business, trust matters. Mentioning <span class=\"zh\">长期合作</span> (a long-term relationship) often helps more than pushing hard on price.","culture":true}]},
{"n":71,"ch":7,"title":"My First Chinese Class","titleZh":"第一节中文课","titleKm":"ថ្នាក់ភាសាចិនដំបូង","art":"classroom book shirt f","scene":"Your Chinese teacher starts the very first lesson.","dialogue":[{"who":"Teacher","hz":"同学们好！","py":"Tóngxuémen hǎo!","en":"Hello, class!","km":"សួស្តីសិស្សទាំងអស់គ្នា!"},{"who":"You","hz":"老师好！","py":"Lǎoshī hǎo!","en":"Hello, teacher!","km":"ជម្រាបសួរលោកគ្រូ!"},{"who":"Teacher","hz":"请打开书，翻到第五页。","py":"Qǐng dǎkāi shū, fān dào dì-wǔ yè.","en":"Please open your books to page five.","km":"សូមបើកសៀវភៅ ទៅទំព័រទីប្រាំ។"},{"who":"You","hz":"老师，第几页？","py":"Lǎoshī, dì jǐ yè?","en":"Teacher, which page?","km":"លោកគ្រូ ទំព័រទីប៉ុន្មាន?"},{"who":"Teacher","hz":"第五页。请跟我读：你好。","py":"Dì-wǔ yè. Qǐng gēn wǒ dú: nǐ hǎo.","en":"Page five. Please read after me: nǐ hǎo.","km":"ទំព័រទីប្រាំ។ សូមអានតាមខ្ញុំ៖ នី ហៅ។"},{"who":"You","hz":"你好。","py":"Nǐ hǎo.","en":"Nǐ hǎo.","km":"នី ហៅ។"},{"who":"Teacher","hz":"很好！声调很准。","py":"Hěn hǎo! Shēngdiào hěn zhǔn.","en":"Very good! Your tones are accurate.","km":"ល្អណាស់! សំនៀងត្រូវណាស់។"}],"phrases":[{"hz":"老师好！","py":"lǎoshī hǎo!","en":"Hello, teacher!","km":"ជម្រាបសួរលោកគ្រូ!"},{"hz":"打开书","py":"dǎkāi shū","en":"Open your book","km":"បើកសៀវភៅ"},{"hz":"第五页","py":"dì-wǔ yè","en":"Page five","km":"ទំព័រទីប្រាំ"},{"hz":"请跟我读","py":"qǐng gēn wǒ dú","en":"Please read after me","km":"សូមអានតាមខ្ញុំ"},{"hz":"声调","py":"shēngdiào","en":"Tone","km":"សំនៀង"},{"hz":"我有一个问题","py":"wǒ yǒu yí ge wèntí","en":"I have a question","km":"ខ្ញុំមានសំណួរមួយ"}],"tips":[{"label":"第 for order","html":"Put <span class=\"zh\">第</span> before a number to make it “-th”: <span class=\"zh\">第一</span> first, <span class=\"zh\">第三课</span> lesson three.","culture":false}]},
{"n":72,"ch":7,"title":"Asking the Teacher","titleZh":"问老师问题","titleKm":"សួរសំណួរលោកគ្រូ","art":"classroom question coat m","scene":"After class you go up to the teacher with a question about a word.","dialogue":[{"who":"You","hz":"老师，我有一个问题。","py":"Lǎoshī, wǒ yǒu yí ge wèntí.","en":"Teacher, I have a question.","km":"លោកគ្រូ ខ្ញុំមានសំណួរមួយ។"},{"who":"Teacher","hz":"请说。","py":"Qǐng shuō.","en":"Go ahead.","km":"និយាយមក។"},{"who":"You","hz":"“认识”和“知道”有什么区别？","py":"“Rènshi” hé “zhīdào” yǒu shénme qūbié?","en":"What's the difference between rènshi and zhīdào?","km":"«រ៉េនស៊ឺ» និង «ជឺតាវ» ខុសគ្នាយ៉ាងម៉េច?"},{"who":"Teacher","hz":"“认识”是认识人，“知道”是知道事情。","py":"“Rènshi” shì rènshi rén, “zhīdào” shì zhīdào shìqing.","en":"Rènshi is knowing a person; zhīdào is knowing a fact.","km":"«រ៉េនស៊ឺ» គឺស្គាល់មនុស្ស «ជឺតាវ» គឺដឹងរឿង។"},{"who":"You","hz":"我明白了。可以给我一个例子吗？","py":"Wǒ míngbai le. Kěyǐ gěi wǒ yí ge lìzi ma?","en":"I see. Could you give me an example?","km":"ខ្ញុំយល់ហើយ។ អាចឱ្យឧទាហរណ៍មួយបានទេ?"},{"who":"Teacher","hz":"我认识他，可是不知道他住在哪儿。","py":"Wǒ rènshi tā, kěshì bù zhīdào tā zhù zài nǎr.","en":"I know him, but I don't know where he lives.","km":"ខ្ញុំស្គាល់គាត់ ប៉ុន្តែមិនដឹងថាគាត់រស់នៅឯណាទេ។"},{"who":"You","hz":"太清楚了，谢谢老师！","py":"Tài qīngchu le, xièxie lǎoshī!","en":"That's very clear — thank you!","km":"ច្បាស់ណាស់ អរគុណលោកគ្រូ!"}],"phrases":[{"hz":"有什么区别？","py":"yǒu shénme qūbié?","en":"What's the difference?","km":"ខុសគ្នាយ៉ាងម៉េច?"},{"hz":"例子","py":"lìzi","en":"Example","km":"ឧទាហរណ៍"},{"hz":"认识","py":"rènshi","en":"To know (a person)","km":"ស្គាល់"},{"hz":"知道","py":"zhīdào","en":"To know (a fact)","km":"ដឹង"},{"hz":"我明白了","py":"wǒ míngbai le","en":"I understand now","km":"ខ្ញុំយល់ហើយ"},{"hz":"……用中文怎么说？","py":"… yòng Zhōngwén zěnme shuō?","en":"How do you say … in Chinese?","km":"…ជាភាសាចិននិយាយយ៉ាងម៉េច?"}],"tips":[{"label":"The question every learner needs","html":"<span class=\"zh\">“……”用中文怎么说？</span> — How do you say “…” in Chinese? Use it every day!","culture":false}]},
{"n":73,"ch":7,"title":"Doing Homework","titleZh":"写作业","titleKm":"ធ្វើកិច្ចការផ្ទះ","art":"home book shirt m c","scene":"Your little brother is doing his Chinese homework at the table.","dialogue":[{"who":"You","hz":"作业写完了吗？","py":"Zuòyè xiě wán le ma?","en":"Have you finished your homework?","km":"ធ្វើកិច្ចការផ្ទះរួចហើយឬនៅ?"},{"who":"Brother","hz":"还没有。这个字我不会写。","py":"Hái méiyǒu. Zhège zì wǒ bú huì xiě.","en":"Not yet. I can't write this character.","km":"មិនទាន់ទេ។ តួអក្សរនេះខ្ញុំមិនចេះសរសេរ។"},{"who":"You","hz":"哪个字？我看看。","py":"Nǎge zì? Wǒ kànkan.","en":"Which one? Let me see.","km":"តួអក្សរណា? ឱ្យបងមើល។"},{"who":"Brother","hz":"“谢谢”的“谢”，笔画太多了！","py":"“Xièxie” de “xiè”, bǐhuà tài duō le!","en":"The xiè in xièxie — it has too many strokes!","km":"តួ «សៀ» ក្នុង «សៀសៀ» មានខ្វាច់ច្រើនពេក!"},{"who":"You","hz":"别急，左边是“言”，中间是“身”，右边是“寸”。","py":"Bié jí, zuǒbian shì “yán”, zhōngjiān shì “shēn”, yòubian shì “cùn”.","en":"Take it easy: on the left is 言, in the middle 身, on the right 寸.","km":"កុំប្រញាប់ ខាងឆ្វេងជា «言» កណ្តាលជា «身» ខាងស្តាំជា «寸»។"},{"who":"Brother","hz":"哦！我会写了！","py":"Ò! Wǒ huì xiě le!","en":"Oh! Now I can write it!","km":"អូ! ខ្ញុំចេះសរសេរហើយ!"},{"who":"You","hz":"真棒！写完了我们去玩儿。","py":"Zhēn bàng! Xiě wán le wǒmen qù wánr.","en":"Brilliant! When you're done we'll go and play.","km":"ពូកែណាស់! សរសេររួចយើងទៅលេង។"}],"phrases":[{"hz":"作业","py":"zuòyè","en":"Homework","km":"កិច្ចការផ្ទះ"},{"hz":"写完了吗？","py":"xiě wán le ma?","en":"Have you finished writing?","km":"សរសេររួចហើយឬនៅ?"},{"hz":"还没有","py":"hái méiyǒu","en":"Not yet","km":"មិនទាន់ទេ"},{"hz":"这个字怎么写？","py":"zhège zì zěnme xiě?","en":"How do you write this character?","km":"តួអក្សរនេះសរសេរយ៉ាងម៉េច?"},{"hz":"笔画","py":"bǐhuà","en":"Stroke (of a character)","km":"ខ្វាច់"},{"hz":"真棒！","py":"zhēn bàng!","en":"Brilliant! Great job!","km":"ពូកែណាស់!"}],"tips":[{"label":"Characters in parts","html":"Most characters are built from smaller parts. Learn the parts and new characters become much easier to remember.","culture":false}]},
{"n":74,"ch":7,"title":"Before the Exam","titleZh":"考试前","titleKm":"មុនពេលប្រឡង","art":"classroom clipboard shirt f","scene":"Your classmate looks nervous the day before the final exam.","dialogue":[{"who":"Classmate","hz":"明天就考试了，我好紧张！","py":"Míngtiān jiù kǎoshì le, wǒ hǎo jǐnzhāng!","en":"The exam is tomorrow — I'm so nervous!","km":"ថ្ងៃស្អែកប្រឡងហើយ ខ្ញុំភ័យណាស់!"},{"who":"You","hz":"你复习得怎么样？","py":"Nǐ fùxí de zěnmeyàng?","en":"How's your revision going?","km":"អ្នករៀនរំលឹកមេរៀនបានដល់ណាហើយ?"},{"who":"Classmate","hz":"生词都记住了，可是语法还不太懂。","py":"Shēngcí dōu jìzhù le, kěshì yǔfǎ hái bú tài dǒng.","en":"I've memorised the new words, but I still don't really get the grammar.","km":"ពាក្យថ្មីចាំអស់ហើយ ប៉ុន្តែវេយ្យាករណ៍នៅមិនសូវយល់។"},{"who":"You","hz":"我们一起复习语法吧。","py":"Wǒmen yìqǐ fùxí yǔfǎ ba.","en":"Let's revise the grammar together.","km":"យើងរំលឹកវេយ្យាករណ៍ជាមួយគ្នាទៅ។"},{"who":"Classmate","hz":"太好了！考试几点开始？","py":"Tài hǎo le! Kǎoshì jǐ diǎn kāishǐ?","en":"Great! What time does the exam start?","km":"ល្អណាស់! ការប្រឡងចាប់ផ្តើមម៉ោងប៉ុន្មាន?"},{"who":"You","hz":"上午九点。早点儿睡，别熬夜。","py":"Shàngwǔ jiǔ diǎn. Zǎo diǎnr shuì, bié áoyè.","en":"Nine in the morning. Go to bed early — don't stay up late.","km":"ម៉ោងប្រាំបួនព្រឹក។ គេងឱ្យឆាប់បន្តិច កុំគេងយប់ជ្រៅ។"},{"who":"Classmate","hz":"好。祝我们考试顺利！","py":"Hǎo. Zhù wǒmen kǎoshì shùnlì!","en":"OK. Good luck to us both!","km":"បាន។ សូមឱ្យយើងប្រឡងបានល្អ!"}],"phrases":[{"hz":"考试","py":"kǎoshì","en":"Exam / take an exam","km":"ការប្រឡង"},{"hz":"复习","py":"fùxí","en":"Revise / review","km":"រំលឹកមេរៀន"},{"hz":"紧张","py":"jǐnzhāng","en":"Nervous","km":"ភ័យ"},{"hz":"生词","py":"shēngcí","en":"New words","km":"ពាក្យថ្មី"},{"hz":"语法","py":"yǔfǎ","en":"Grammar","km":"វេយ្យាករណ៍"},{"hz":"祝你考试顺利！","py":"zhù nǐ kǎoshì shùnlì!","en":"Good luck in your exam!","km":"សូមឱ្យប្រឡងបានល្អ!"}],"tips":[{"label":"祝 for wishes","html":"<span class=\"zh\">祝</span> + person + wish: <span class=\"zh\">祝你好运</span> good luck, <span class=\"zh\">祝你成功</span> wishing you success.","culture":false}]},
{"n":75,"ch":7,"title":"At the Library","titleZh":"在图书馆","titleKm":"នៅបណ្ណាល័យ","art":"classroom book uniform f","scene":"You want to borrow some books from the university library.","dialogue":[{"who":"You","hz":"你好，我想借这两本书。","py":"Nǐ hǎo, wǒ xiǎng jiè zhè liǎng běn shū.","en":"Hello, I'd like to borrow these two books.","km":"សួស្តី ខ្ញុំចង់ខ្ចីសៀវភៅពីរក្បាលនេះ។"},{"who":"Librarian","hz":"请给我你的学生证。","py":"Qǐng gěi wǒ nǐ de xuéshengzhèng.","en":"Your student card, please.","km":"សូមឱ្យកាតសិស្សរបស់អ្នកមកខ្ញុំ។"},{"who":"You","hz":"给您。可以借多长时间？","py":"Gěi nín. Kěyǐ jiè duō cháng shíjiān?","en":"Here you are. How long can I borrow them for?","km":"នេះ។ អាចខ្ចីបានប៉ុន្មានថ្ងៃ?"},{"who":"Librarian","hz":"一个月。到期以前可以在网上续借。","py":"Yí ge yuè. Dàoqī yǐqián kěyǐ zài wǎngshang xùjiè.","en":"One month. You can renew online before they're due.","km":"មួយខែ។ មុនផុតកំណត់ អាចបន្តការខ្ចីតាមអនឡាញ។"},{"who":"You","hz":"这儿可以复印吗？","py":"Zhèr kěyǐ fùyìn ma?","en":"Can I make photocopies here?","km":"នៅទីនេះអាចថតចម្លងបានទេ?"},{"who":"Librarian","hz":"可以，复印机在二楼。请小声一点儿。","py":"Kěyǐ, fùyìnjī zài èr lóu. Qǐng xiǎo shēng yìdiǎnr.","en":"Yes, the photocopier is on the second floor. Please keep your voice down.","km":"បាន ម៉ាស៊ីនថតចម្លងនៅជាន់ទីពីរ។ សូមនិយាយតិចៗបន្តិច។"},{"who":"You","hz":"不好意思！谢谢。","py":"Bù hǎoyìsi! Xièxie.","en":"Sorry! Thanks.","km":"សុំទោស! អរគុណ។"}],"phrases":[{"hz":"借书","py":"jiè shū","en":"Borrow books","km":"ខ្ចីសៀវភៅ"},{"hz":"还书","py":"huán shū","en":"Return books","km":"សងសៀវភៅ"},{"hz":"学生证","py":"xuéshengzhèng","en":"Student card","km":"កាតសិស្ស"},{"hz":"续借","py":"xùjiè","en":"Renew a loan","km":"បន្តការខ្ចី"},{"hz":"复印","py":"fùyìn","en":"Photocopy","km":"ថតចម្លង"},{"hz":"请小声一点儿","py":"qǐng xiǎo shēng yìdiǎnr","en":"Please be quieter","km":"សូមនិយាយតិចៗ"}],"tips":[{"label":"借 both ways","html":"<span class=\"zh\">借</span> means both borrow and lend: <span class=\"zh\">我借你的笔</span> I borrow your pen; <span class=\"zh\">借给你</span> lend it to you.","culture":false}]},
{"n":76,"ch":7,"title":"Making a Study Plan","titleZh":"做学习计划","titleKm":"បង្កើតផែនការសិក្សា","art":"cafe book shirt m","scene":"You and a language-exchange partner plan how to practise together.","dialogue":[{"who":"Partner","hz":"我们怎么练习比较好？","py":"Wǒmen zěnme liànxí bǐjiào hǎo?","en":"What's the best way for us to practise?","km":"តើយើងហាត់យ៉ាងម៉េចទើបល្អ?"},{"who":"You","hz":"每个星期见两次，一次说中文，一次说英语。","py":"Měi ge xīngqī jiàn liǎng cì, yí cì shuō Zhōngwén, yí cì shuō Yīngyǔ.","en":"Meet twice a week — once in Chinese, once in English.","km":"ជួបគ្នាពីរដងក្នុងមួយសប្តាហ៍ ម្តងនិយាយចិន ម្តងនិយាយអង់គ្លេស។"},{"who":"Partner","hz":"好主意！每次多长时间？","py":"Hǎo zhǔyi! Měi cì duō cháng shíjiān?","en":"Good idea! How long each time?","km":"គំនិតល្អ! ម្តងៗប៉ុន្មានម៉ោង?"},{"who":"You","hz":"一个小时吧。我们还可以一起看中国电影。","py":"Yí ge xiǎoshí ba. Wǒmen hái kěyǐ yìqǐ kàn Zhōngguó diànyǐng.","en":"An hour. We could also watch Chinese films together.","km":"មួយម៉ោងចុះ។ យើងក៏អាចមើលកុនចិនជាមួយគ្នាបានដែរ។"},{"who":"Partner","hz":"看电影学中文最有意思了。","py":"Kàn diànyǐng xué Zhōngwén zuì yǒu yìsi le.","en":"Learning Chinese through films is the most fun.","km":"រៀនភាសាចិនតាមរយៈមើលកុន គឺសប្បាយជាងគេ។"},{"who":"You","hz":"你说错了的时候，我可以帮你改。","py":"Nǐ shuō cuò le de shíhou, wǒ kěyǐ bāng nǐ gǎi.","en":"When you make a mistake, I can help correct it.","km":"ពេលអ្នកនិយាយខុស ខ្ញុំអាចជួយកែឱ្យ។"},{"who":"Partner","hz":"你也一样，有错就告诉我！","py":"Nǐ yě yíyàng, yǒu cuò jiù gàosu wǒ!","en":"Same for you — tell me whenever I'm wrong!","km":"អ្នកក៏ដូចគ្នា ខុសត្រង់ណាប្រាប់ខ្ញុំ!"}],"phrases":[{"hz":"练习","py":"liànxí","en":"Practise","km":"ហាត់"},{"hz":"好主意！","py":"hǎo zhǔyi!","en":"Good idea!","km":"គំនិតល្អ!"},{"hz":"一个星期两次","py":"yí ge xīngqī liǎng cì","en":"Twice a week","km":"ពីរដងក្នុងមួយសប្តាហ៍"},{"hz":"有意思","py":"yǒu yìsi","en":"Interesting / fun","km":"គួរឱ្យចាប់អារម្មណ៍"},{"hz":"说错了","py":"shuō cuò le","en":"Said it wrong","km":"និយាយខុស"},{"hz":"……的时候","py":"… de shíhou","en":"When…","km":"ពេល…"}],"tips":[{"label":"Frequency with 次","html":"<span class=\"zh\">次</span> counts times: <span class=\"zh\">一次</span> once, <span class=\"zh\">两次</span> twice, <span class=\"zh\">很多次</span> many times.","culture":false}]},
{"n":77,"ch":7,"title":"What Will You Study?","titleZh":"你想学什么专业？","titleKm":"តើអ្នកចង់រៀនជំនាញអ្វី?","art":"park book shirt f","scene":"A friend about to finish high school is thinking about university.","dialogue":[{"who":"You","hz":"你高中快毕业了吧？","py":"Nǐ gāozhōng kuài bìyè le ba?","en":"You're about to finish high school, aren't you?","km":"អ្នកជិតបញ្ចប់វិទ្យាល័យហើយមែនទេ?"},{"who":"Friend","hz":"对，明年就上大学了。","py":"Duì, míngnián jiù shàng dàxué le.","en":"Yes, I'll start university next year.","km":"ត្រូវ ឆ្នាំក្រោយចូលសាកលវិទ្យាល័យហើយ។"},{"who":"You","hz":"你想学什么专业？","py":"Nǐ xiǎng xué shénme zhuānyè?","en":"What do you want to study?","km":"អ្នកចង់រៀនជំនាញអ្វី?"},{"who":"Friend","hz":"我对电脑很感兴趣，想学软件工程。","py":"Wǒ duì diànnǎo hěn gǎn xìngqù, xiǎng xué ruǎnjiàn gōngchéng.","en":"I'm very interested in computers — I want to study software engineering.","km":"ខ្ញុំចាប់អារម្មណ៍នឹងកុំព្យូទ័រណាស់ ចង់រៀនវិស្វកម្មសូហ្វវែរ។"},{"who":"You","hz":"打算在国内读还是出国读？","py":"Dǎsuàn zài guónèi dú háishi chūguó dú?","en":"Are you planning to study here or abroad?","km":"គ្រោងរៀនក្នុងប្រទេស ឬទៅរៀនក្រៅប្រទេស?"},{"who":"Friend","hz":"想去中国留学，所以在学中文。","py":"Xiǎng qù Zhōngguó liúxué, suǒyǐ zài xué Zhōngwén.","en":"I want to study in China, so I'm learning Chinese.","km":"ចង់ទៅសិក្សានៅប្រទេសចិន ដូច្នេះកំពុងរៀនភាសាចិន។"},{"who":"You","hz":"加油，你一定可以的！","py":"Jiāyóu, nǐ yídìng kěyǐ de!","en":"Go for it — you can definitely do it!","km":"ខំប្រឹងណា អ្នកពិតជាអាចធ្វើបាន!"}],"phrases":[{"hz":"专业","py":"zhuānyè","en":"Major / field of study","km":"ជំនាញ"},{"hz":"毕业","py":"bìyè","en":"Graduate","km":"បញ្ចប់ការសិក្សា"},{"hz":"上大学","py":"shàng dàxué","en":"Go to university","km":"ចូលសាកលវិទ្យាល័យ"},{"hz":"对……感兴趣","py":"duì … gǎn xìngqù","en":"Be interested in…","km":"ចាប់អារម្មណ៍នឹង…"},{"hz":"留学","py":"liúxué","en":"Study abroad","km":"សិក្សានៅបរទេស"},{"hz":"所以","py":"suǒyǐ","en":"So / therefore","km":"ដូច្នេះ"}],"tips":[{"label":"在 + verb = -ing","html":"<span class=\"zh\">在</span> before a verb shows it's happening now: <span class=\"zh\">我在学中文</span> — I'm learning Chinese.","culture":false}]},
{"n":78,"ch":7,"title":"Signing Up for HSK","titleZh":"报名HSK考试","titleKm":"ចុះឈ្មោះប្រឡង HSK","art":"office clipboard uniform f","scene":"You go to the Confucius Institute office to register for the HSK test.","dialogue":[{"who":"You","hz":"你好，我想报名参加HSK考试。","py":"Nǐ hǎo, wǒ xiǎng bàomíng cānjiā HSK kǎoshì.","en":"Hello, I'd like to register for the HSK test.","km":"សួស្តី ខ្ញុំចង់ចុះឈ្មោះប្រឡង HSK។"},{"who":"Staff","hz":"你想考几级？","py":"Nǐ xiǎng kǎo jǐ jí?","en":"Which level do you want to take?","km":"អ្នកចង់ប្រឡងកម្រិតប៉ុន្មាន?"},{"who":"You","hz":"三级。下次考试是什么时候？","py":"Sān jí. Xià cì kǎoshì shì shénme shíhou?","en":"Level 3. When is the next test?","km":"កម្រិតបី។ ការប្រឡងលើកក្រោយនៅពេលណា?"},{"who":"Staff","hz":"十二月六号。报名截止到十一月十号。","py":"Shí'èr yuè liù hào. Bàomíng jiézhǐ dào shíyī yuè shí hào.","en":"December 6th. Registration closes on November 10th.","km":"ថ្ងៃទីប្រាំមួយ ខែធ្នូ។ ការចុះឈ្មោះផុតកំណត់ថ្ងៃទីដប់ ខែវិច្ឆិកា។"},{"who":"You","hz":"报名费多少钱？","py":"Bàomíngfèi duōshao qián?","en":"How much is the fee?","km":"ថ្លៃចុះឈ្មោះប៉ុន្មាន?"},{"who":"Staff","hz":"三十五美元。请带护照照片来。","py":"Sānshíwǔ měiyuán. Qǐng dài hùzhào zhàopiàn lái.","en":"Thirty-five dollars. Please bring a passport photo.","km":"សាមសិបប្រាំដុល្លារ។ សូមយករូបថតលិខិតឆ្លងដែនមក។"},{"who":"You","hz":"好的，我明天带来。","py":"Hǎo de, wǒ míngtiān dài lái.","en":"OK, I'll bring it tomorrow.","km":"បាទ/ចាស ថ្ងៃស្អែកខ្ញុំយកមក។"}],"phrases":[{"hz":"报名","py":"bàomíng","en":"Register / sign up","km":"ចុះឈ្មោះ"},{"hz":"参加","py":"cānjiā","en":"Take part in","km":"ចូលរួម"},{"hz":"几级？","py":"jǐ jí?","en":"Which level?","km":"កម្រិតប៉ុន្មាន?"},{"hz":"截止","py":"jiézhǐ","en":"Deadline / closing","km":"ផុតកំណត់"},{"hz":"报名费","py":"bàomíngfèi","en":"Registration fee","km":"ថ្លៃចុះឈ្មោះ"},{"hz":"照片","py":"zhàopiàn","en":"Photo","km":"រូបថត"}],"tips":[{"label":"HSK levels","html":"HSK is the official Chinese test. This course covers most words for HSK 1–3. Try the HSK 1 chapter tests on this site too!","culture":false}]},
{"n":79,"ch":7,"title":"Making a New Friend at School","titleZh":"交新朋友","titleKm":"រាប់អានមិត្តថ្មីនៅសាលា","art":"park ball shirt m c","scene":"At break time, a new boy is standing alone in the playground. You go over to him.","dialogue":[{"who":"You","hz":"你好！你是新来的同学吗？","py":"Nǐ hǎo! Nǐ shì xīn lái de tóngxué ma?","en":"Hi! Are you the new student?","km":"សួស្តី! ប្អូនជាសិស្សថ្មីមែនទេ?"},{"who":"Boy","hz":"是的，我叫乐乐。我是三年级二班的。","py":"Shì de, wǒ jiào Lèle. Wǒ shì sān niánjí èr bān de.","en":"Yes, I'm Lele. I'm in Year 3, Class 2.","km":"បាទ ខ្ញុំឈ្មោះឡឺឡឺ។ ខ្ញុំរៀនថ្នាក់ទីបី ក្រុមពីរ។"},{"who":"You","hz":"我们是一个班的！你喜欢踢足球吗？","py":"Wǒmen shì yí ge bān de! Nǐ xǐhuan tī zúqiú ma?","en":"We're in the same class! Do you like playing football?","km":"យើងរៀនថ្នាក់ជាមួយគ្នា! ប្អូនចូលចិត្តលេងបាល់ទាត់ទេ?"},{"who":"Boy","hz":"喜欢！我踢得不太好。","py":"Xǐhuan! Wǒ tī de bú tài hǎo.","en":"Yes! But I'm not very good.","km":"ចូលចិត្ត! ប៉ុន្តែខ្ញុំទាត់មិនសូវពូកែទេ។"},{"who":"You","hz":"没关系，跟我们一起玩儿吧！","py":"Méi guānxi, gēn wǒmen yìqǐ wánr ba!","en":"That's OK — come and play with us!","km":"មិនអីទេ មកលេងជាមួយយើងមក!"},{"who":"Boy","hz":"好啊！谢谢你！","py":"Hǎo a! Xièxie nǐ!","en":"OK! Thank you!","km":"បាន! អរគុណ!"}],"phrases":[{"hz":"新来的同学","py":"xīn lái de tóngxué","en":"New classmate","km":"សិស្សថ្មី"},{"hz":"三年级","py":"sān niánjí","en":"Year / Grade 3","km":"ថ្នាក់ទីបី"},{"hz":"一个班","py":"yí ge bān","en":"The same class","km":"ថ្នាក់តែមួយ"},{"hz":"踢足球","py":"tī zúqiú","en":"Play football","km":"លេងបាល់ទាត់"},{"hz":"一起玩儿吧！","py":"yìqǐ wánr ba!","en":"Let's play together!","km":"លេងជាមួយគ្នាមក!"},{"hz":"好朋友","py":"hǎo péngyou","en":"Good friend","km":"មិត្តល្អ"}],"tips":[{"label":"Kids' names","html":"Chinese children often have doubled nicknames: <span class=\"zh\">乐乐</span>, <span class=\"zh\">豆豆</span>, <span class=\"zh\">明明</span>. They sound friendly and cute.","culture":true}]},
{"n":80,"ch":7,"title":"Meeting the Teacher","titleZh":"家长会","titleKm":"ជួបគ្រូរបស់កូន","art":"classroom book coat f","scene":"You meet your daughter's class teacher at a parents' evening.","dialogue":[{"who":"Teacher","hz":"您好，您是美美的家长吧？","py":"Nín hǎo, nín shì Měiměi de jiāzhǎng ba?","en":"Hello, you're Meimei's parent, aren't you?","km":"ជម្រាបសួរ លោកជាអាណាព្យាបាលរបស់ម៉ីម៉ីមែនទេ?"},{"who":"You","hz":"是的，我是她爸爸。她最近表现怎么样？","py":"Shì de, wǒ shì tā bàba. Tā zuìjìn biǎoxiàn zěnmeyàng?","en":"Yes, I'm her dad. How has she been doing lately?","km":"បាទ ខ្ញុំជាឪពុកនាង។ ថ្មីៗនេះនាងរៀនយ៉ាងម៉េចដែរ?"},{"who":"Teacher","hz":"她很聪明，上课很认真。","py":"Tā hěn cōngming, shàngkè hěn rènzhēn.","en":"She's very bright and works hard in class.","km":"នាងឆ្លាតណាស់ ហើយយកចិត្តទុកដាក់ក្នុងថ្នាក់។"},{"who":"You","hz":"有什么需要提高的地方吗？","py":"Yǒu shénme xūyào tígāo de dìfang ma?","en":"Is there anything she needs to improve?","km":"មានចំណុចណាដែលត្រូវកែលម្អទេ?"},{"who":"Teacher","hz":"她的数学很好，可是写字有点儿马虎。","py":"Tā de shùxué hěn hǎo, kěshì xiě zì yǒudiǎnr mǎhu.","en":"Her maths is very good, but her handwriting is a bit careless.","km":"គណិតវិទ្យានាងល្អណាស់ ប៉ុន្តែសរសេរអក្សរធ្វេសប្រហែសបន្តិច។"},{"who":"You","hz":"明白了，我们在家会让她多练习。","py":"Míngbai le, wǒmen zài jiā huì ràng tā duō liànxí.","en":"I see — we'll have her practise more at home.","km":"ខ្ញុំយល់ហើយ នៅផ្ទះយើងនឹងឱ្យនាងហាត់បន្ថែម។"},{"who":"Teacher","hz":"好的，有问题随时联系我。","py":"Hǎo de, yǒu wèntí suíshí liánxì wǒ.","en":"Good — contact me any time if there's a problem.","km":"ល្អ មានបញ្ហាទាក់ទងខ្ញុំបានគ្រប់ពេល។"}],"phrases":[{"hz":"家长","py":"jiāzhǎng","en":"Parent / guardian","km":"អាណាព្យាបាល"},{"hz":"表现怎么样？","py":"biǎoxiàn zěnmeyàng?","en":"How is (s)he doing?","km":"រៀនយ៉ាងម៉េចដែរ?"},{"hz":"聪明","py":"cōngming","en":"Clever, bright","km":"ឆ្លាត"},{"hz":"认真","py":"rènzhēn","en":"Serious, hard-working","km":"យកចិត្តទុកដាក់"},{"hz":"提高","py":"tígāo","en":"Improve","km":"កែលម្អ"},{"hz":"数学","py":"shùxué","en":"Maths","km":"គណិតវិទ្យា"}],"tips":[{"label":"让 = make / let","html":"<span class=\"zh\">让</span> + person + verb: <span class=\"zh\">让她多练习</span> — have her practise more; <span class=\"zh\">让我看看</span> — let me see.","culture":false}]},
{"n":81,"ch":8,"title":"I Don't Feel Well","titleZh":"我不舒服","titleKm":"ខ្ញុំមិនស្រួលខ្លួន","art":"office thermo suit f","scene":"You arrive at work looking pale. A colleague notices.","dialogue":[{"who":"Colleague","hz":"你脸色不太好，怎么了？","py":"Nǐ liǎnsè bú tài hǎo, zěnme le?","en":"You look a bit pale — what's wrong?","km":"មុខអ្នកមើលទៅមិនសូវល្អ មានរឿងអី?"},{"who":"You","hz":"我有点儿不舒服，头疼。","py":"Wǒ yǒudiǎnr bù shūfu, tóu téng.","en":"I don't feel very well — I have a headache.","km":"ខ្ញុំមិនសូវស្រួលខ្លួន ឈឺក្បាល។"},{"who":"Colleague","hz":"发烧吗？","py":"Fāshāo ma?","en":"Do you have a fever?","km":"ក្តៅខ្លួនទេ?"},{"who":"You","hz":"好像有一点儿，还咳嗽。","py":"Hǎoxiàng yǒu yìdiǎnr, hái késou.","en":"I think a little, and I'm coughing too.","km":"ដូចជាក្តៅបន្តិច ហើយក្អកទៀត។"},{"who":"Colleague","hz":"可能是感冒了。你回家休息吧，我跟经理说。","py":"Kěnéng shì gǎnmào le. Nǐ huí jiā xiūxi ba, wǒ gēn jīnglǐ shuō.","en":"It might be a cold. Go home and rest — I'll tell the manager.","km":"ប្រហែលជាផ្តាសាយហើយ។ ទៅផ្ទះសម្រាកទៅ ខ្ញុំប្រាប់ប្រធានឱ្យ។"},{"who":"You","hz":"谢谢你。我去医院看看。","py":"Xièxie nǐ. Wǒ qù yīyuàn kànkan.","en":"Thank you. I'll go to the hospital and get checked.","km":"អរគុណ។ ខ្ញុំទៅមន្ទីរពេទ្យពិនិត្យមើល។"},{"who":"Colleague","hz":"多喝水，早点儿好起来！","py":"Duō hē shuǐ, zǎo diǎnr hǎo qǐlai!","en":"Drink lots of water — get well soon!","km":"ផឹកទឹកច្រើនៗ សូមឱ្យឆាប់ជា!"}],"phrases":[{"hz":"我不舒服","py":"wǒ bù shūfu","en":"I don't feel well","km":"ខ្ញុំមិនស្រួលខ្លួន"},{"hz":"头疼","py":"tóu téng","en":"Headache","km":"ឈឺក្បាល"},{"hz":"发烧","py":"fāshāo","en":"Have a fever","km":"ក្តៅខ្លួន"},{"hz":"咳嗽","py":"késou","en":"Cough","km":"ក្អក"},{"hz":"感冒了","py":"gǎnmào le","en":"Caught a cold","km":"ផ្តាសាយហើយ"},{"hz":"早点儿好起来！","py":"zǎo diǎnr hǎo qǐlai!","en":"Get well soon!","km":"សូមឱ្យឆាប់ជា!"}],"tips":[{"label":"Body part + 疼","html":"Say where it hurts with body part + <span class=\"zh\">疼</span>: <span class=\"zh\">肚子疼</span> stomach ache, <span class=\"zh\">牙疼</span> toothache, <span class=\"zh\">嗓子疼</span> sore throat.","culture":false}]},
{"n":82,"ch":8,"title":"At the Doctor's","titleZh":"看医生","titleKm":"ជួបគ្រូពេទ្យ","art":"clinic stetho coat m","scene":"You are seeing a doctor at a clinic.","dialogue":[{"who":"Doctor","hz":"你哪儿不舒服？","py":"Nǐ nǎr bù shūfu?","en":"What seems to be the problem?","km":"អ្នកមិនស្រួលត្រង់ណា?"},{"who":"You","hz":"我肚子疼，还拉肚子。","py":"Wǒ dùzi téng, hái lā dùzi.","en":"I have a stomach ache and diarrhoea.","km":"ខ្ញុំឈឺពោះ ហើយរាគផង។"},{"who":"Doctor","hz":"从什么时候开始的？","py":"Cóng shénme shíhou kāishǐ de?","en":"Since when?","km":"ចាប់ផ្តើមតាំងពីពេលណា?"},{"who":"You","hz":"昨天晚上。我吃了路边的烧烤。","py":"Zuótiān wǎnshang. Wǒ chī le lùbiān de shāokǎo.","en":"Since last night. I ate barbecue from a street stall.","km":"តាំងពីយប់មិញ។ ខ្ញុំញ៉ាំសាច់អាំងតាមចិញ្ចើមផ្លូវ។"},{"who":"Doctor","hz":"我给你检查一下……不严重，是肠胃炎。","py":"Wǒ gěi nǐ jiǎnchá yíxià… bù yánzhòng, shì chángwèiyán.","en":"Let me examine you… It's not serious — it's gastroenteritis.","km":"ខ្ញុំពិនិត្យអ្នកបន្តិច… មិនធ្ងន់ធ្ងរទេ គឺរលាកក្រពះពោះវៀន។"},{"who":"You","hz":"需要打针吗？","py":"Xūyào dǎzhēn ma?","en":"Do I need an injection?","km":"ត្រូវចាក់ថ្នាំទេ?"},{"who":"Doctor","hz":"不用，吃药就行。这几天吃清淡一点儿。","py":"Búyòng, chī yào jiù xíng. Zhè jǐ tiān chī qīngdàn yìdiǎnr.","en":"No, medicine is enough. Eat plain food for the next few days.","km":"មិនបាច់ទេ លេបថ្នាំក៏បាន។ ប៉ុន្មានថ្ងៃនេះញ៉ាំម្ហូបស្រាលៗ។"}],"phrases":[{"hz":"你哪儿不舒服？","py":"nǐ nǎr bù shūfu?","en":"What's the problem? (Where don't you feel well?)","km":"អ្នកមិនស្រួលត្រង់ណា?"},{"hz":"肚子疼","py":"dùzi téng","en":"Stomach ache","km":"ឈឺពោះ"},{"hz":"从什么时候开始的？","py":"cóng shénme shíhou kāishǐ de?","en":"Since when?","km":"ចាប់ផ្តើមពីពេលណា?"},{"hz":"检查","py":"jiǎnchá","en":"Examine / check-up","km":"ពិនិត្យ"},{"hz":"不严重","py":"bù yánzhòng","en":"Not serious","km":"មិនធ្ងន់ធ្ងរ"},{"hz":"吃药","py":"chī yào","en":"Take medicine","km":"លេបថ្នាំ"}],"tips":[{"label":"Registering first","html":"In Chinese hospitals you first <span class=\"zh\">挂号</span> <em>guàhào</em> (register at the desk or on the app), then wait for your number to be called.","culture":true}]},
{"n":83,"ch":8,"title":"At the Pharmacy","titleZh":"在药店","titleKm":"នៅឱសថស្ថាន","art":"pharmacy pill coat f","scene":"You need something for a sore throat.","dialogue":[{"who":"Pharmacist","hz":"您需要什么？","py":"Nín xūyào shénme?","en":"What do you need?","km":"តើអ្នកត្រូវការអ្វី?"},{"who":"You","hz":"我嗓子疼，有什么药吗？","py":"Wǒ sǎngzi téng, yǒu shénme yào ma?","en":"I have a sore throat — what medicine do you have?","km":"ខ្ញុំឈឺបំពង់ក មានថ្នាំអ្វីទេ?"},{"who":"Pharmacist","hz":"这种含片不错。您对什么药过敏吗？","py":"Zhè zhǒng hánpiàn búcuò. Nín duì shénme yào guòmǐn ma?","en":"These lozenges are good. Are you allergic to any medicine?","km":"គ្រាប់អមប្រភេទនេះល្អ។ តើអ្នកមានប្រតិកម្មនឹងថ្នាំអ្វីទេ?"},{"who":"You","hz":"没有。一天吃几次？","py":"Méiyǒu. Yì tiān chī jǐ cì?","en":"No. How many times a day?","km":"អត់ទេ។ មួយថ្ងៃលេបប៉ុន្មានដង?"},{"who":"Pharmacist","hz":"一天三次，一次一片，饭后吃。","py":"Yì tiān sān cì, yí cì yí piàn, fàn hòu chī.","en":"Three times a day, one tablet each time, after meals.","km":"មួយថ្ងៃបីដង ម្តងមួយគ្រាប់ ក្រោយអាហារ។"},{"who":"You","hz":"好的。要是三天还不好呢？","py":"Hǎo de. Yàoshi sān tiān hái bù hǎo ne?","en":"OK. And if it's not better in three days?","km":"បាទ/ចាស។ បើបីថ្ងៃហើយនៅមិនទាន់ជាវិញ?"},{"who":"Pharmacist","hz":"那就要去医院看看了。","py":"Nà jiù yào qù yīyuàn kànkan le.","en":"Then you should go to the hospital.","km":"អញ្ចឹងត្រូវទៅមន្ទីរពេទ្យពិនិត្យហើយ។"}],"phrases":[{"hz":"药店","py":"yàodiàn","en":"Pharmacy","km":"ឱសថស្ថាន"},{"hz":"嗓子疼","py":"sǎngzi téng","en":"Sore throat","km":"ឈឺបំពង់ក"},{"hz":"过敏","py":"guòmǐn","en":"Allergic","km":"ប្រតិកម្ម / អាឡែកហ្ស៊ី"},{"hz":"一天三次","py":"yì tiān sān cì","en":"Three times a day","km":"មួយថ្ងៃបីដង"},{"hz":"饭后吃","py":"fàn hòu chī","en":"Take after meals","km":"លេបក្រោយអាហារ"},{"hz":"要是……","py":"yàoshi…","en":"If…","km":"បើ…"}],"tips":[{"label":"Read the label","html":"<span class=\"zh\">饭前</span> = before meals, <span class=\"zh\">饭后</span> = after meals, <span class=\"zh\">每次</span> = each time, <span class=\"zh\">片</span> = tablet.","culture":false}]},
{"n":84,"ch":8,"title":"At the Dentist","titleZh":"看牙医","titleKm":"ជួបពេទ្យធ្មេញ","art":"clinic tooth coat f","scene":"One of your back teeth hurts when you drink something cold.","dialogue":[{"who":"Dentist","hz":"请坐，张开嘴。哪颗牙疼？","py":"Qǐng zuò, zhāngkāi zuǐ. Nǎ kē yá téng?","en":"Please sit down and open your mouth. Which tooth hurts?","km":"អញ្ជើញអង្គុយ ហាមាត់។ ធ្មេញណាឈឺ?"},{"who":"You","hz":"右边下面这颗。喝冷水的时候特别疼。","py":"Yòubian xiàmiàn zhè kē. Hē lěng shuǐ de shíhou tèbié téng.","en":"This one, bottom right. It really hurts when I drink cold water.","km":"ធ្មេញខាងស្តាំខាងក្រោមនេះ។ ពេលផឹកទឹកត្រជាក់ឈឺខ្លាំង។"},{"who":"Dentist","hz":"有一个小洞，需要补牙。","py":"Yǒu yí ge xiǎo dòng, xūyào bǔ yá.","en":"There's a small cavity — it needs a filling.","km":"មានរន្ធតូចមួយ ត្រូវប៉ះធ្មេញ។"},{"who":"You","hz":"疼不疼？","py":"Téng bu téng?","en":"Will it hurt?","km":"ឈឺទេ?"},{"who":"Dentist","hz":"别担心，我会给你打麻药。","py":"Bié dānxīn, wǒ huì gěi nǐ dǎ máyào.","en":"Don't worry, I'll give you an anaesthetic.","km":"កុំបារម្ភ ខ្ញុំនឹងចាក់ថ្នាំស្ពឹកឱ្យ។"},{"who":"You","hz":"好的。以后我要少吃糖了。","py":"Hǎo de. Yǐhòu wǒ yào shǎo chī táng le.","en":"OK. I'll eat fewer sweets from now on.","km":"បាទ/ចាស។ ពីនេះទៅខ្ញុំនឹងញ៉ាំស្ករតិច។"}],"phrases":[{"hz":"牙医","py":"yáyī","en":"Dentist","km":"ពេទ្យធ្មេញ"},{"hz":"牙疼","py":"yá téng","en":"Toothache","km":"ឈឺធ្មេញ"},{"hz":"张开嘴","py":"zhāngkāi zuǐ","en":"Open your mouth","km":"ហាមាត់"},{"hz":"补牙","py":"bǔ yá","en":"Fill a tooth","km":"ប៉ះធ្មេញ"},{"hz":"别担心","py":"bié dānxīn","en":"Don't worry","km":"កុំបារម្ភ"},{"hz":"刷牙","py":"shuā yá","en":"Brush your teeth","km":"ដុសធ្មេញ"}],"tips":[{"label":"Two “don't worry”s","html":"<span class=\"zh\">别担心</span> = don't be worried; <span class=\"zh\">别着急</span> = don't rush / don't panic.","culture":false}]},
{"n":85,"ch":8,"title":"My Wallet Was Stolen","titleZh":"我的钱包被偷了","titleKm":"កាបូបរបស់ខ្ញុំត្រូវគេលួច","art":"police bag uniform m","scene":"Someone took your wallet on a crowded bus. You go to the police station.","dialogue":[{"who":"Officer","hz":"你好，有什么事？","py":"Nǐ hǎo, yǒu shénme shì?","en":"Hello, what's happened?","km":"សួស្តី មានរឿងអី?"},{"who":"You","hz":"我的钱包被偷了。","py":"Wǒ de qiánbāo bèi tōu le.","en":"My wallet has been stolen.","km":"កាបូបរបស់ខ្ញុំត្រូវគេលួចហើយ។"},{"who":"Officer","hz":"在哪儿被偷的？什么时候？","py":"Zài nǎr bèi tōu de? Shénme shíhou?","en":"Where was it stolen? When?","km":"ត្រូវគេលួចនៅឯណា? ពេលណា?"},{"who":"You","hz":"一个小时以前，在十路公交车上。","py":"Yí ge xiǎoshí yǐqián, zài shí lù gōngjiāochē shang.","en":"An hour ago, on the number 10 bus.","km":"មួយម៉ោងមុន នៅលើឡានក្រុងខ្សែលេខដប់។"},{"who":"Officer","hz":"钱包里有什么？","py":"Qiánbāo li yǒu shénme?","en":"What was in the wallet?","km":"ក្នុងកាបូបមានអ្វីខ្លះ?"},{"who":"You","hz":"有八百块钱、一张银行卡和我的学生证。","py":"Yǒu bābǎi kuài qián, yì zhāng yínhángkǎ hé wǒ de xuéshengzhèng.","en":"800 yuan, a bank card and my student card.","km":"មានលុយប្រាំបីរយយ័ន កាតធនាគារមួយ និងកាតសិស្សរបស់ខ្ញុំ។"},{"who":"Officer","hz":"请填这张表。你先给银行打电话，把卡挂失。","py":"Qǐng tián zhè zhāng biǎo. Nǐ xiān gěi yínháng dǎ diànhuà, bǎ kǎ guàshī.","en":"Please fill in this form. First call your bank and report the card lost.","km":"សូមបំពេញទម្រង់នេះ។ ទូរសព្ទទៅធនាគារសិន ដើម្បីរាយការណ៍ថាកាតបាត់។"}],"phrases":[{"hz":"被偷了","py":"bèi tōu le","en":"Was stolen","km":"ត្រូវគេលួច"},{"hz":"钱包","py":"qiánbāo","en":"Wallet / purse","km":"កាបូបលុយ"},{"hz":"报警","py":"bàojǐng","en":"Call / report to the police","km":"រាយការណ៍ប៉ូលិស"},{"hz":"派出所","py":"pàichūsuǒ","en":"Local police station","km":"ប៉ុស្តិ៍ប៉ូលិស"},{"hz":"挂失","py":"guàshī","en":"Report (a card) lost","km":"រាយការណ៍ថាបាត់"},{"hz":"救命！","py":"jiùmìng!","en":"Help!","km":"ជួយផង!"}],"tips":[{"label":"Emergency numbers in China","html":"<span class=\"zh\">110</span> police, <span class=\"zh\">120</span> ambulance, <span class=\"zh\">119</span> fire. In Cambodia: 117 police, 119 ambulance, 118 fire.","culture":true},{"label":"被 for bad luck","html":"<span class=\"zh\">被</span> makes a passive, usually for unlucky events: <span class=\"zh\">被偷了</span> was stolen, <span class=\"zh\">被雨淋了</span> got caught in the rain.","culture":false}]},
{"n":86,"ch":8,"title":"I Lost My Phone","titleZh":"我的手机丢了","titleKm":"ទូរសព្ទរបស់ខ្ញុំបាត់","art":"cafe phone apron f","scene":"You left a café ten minutes ago and realise your phone is missing. You run back.","dialogue":[{"who":"You","hz":"不好意思，我的手机丢了，可能落在这儿了。","py":"Bù hǎoyìsi, wǒ de shǒujī diū le, kěnéng là zài zhèr le.","en":"Excuse me, I've lost my phone — I might have left it here.","km":"សុំទោស ទូរសព្ទខ្ញុំបាត់ ប្រហែលជាភ្លេចទុកនៅទីនេះ។"},{"who":"Staff","hz":"什么样的手机？","py":"Shénme yàng de shǒujī?","en":"What does it look like?","km":"ទូរសព្ទបែបណា?"},{"who":"You","hz":"黑色的，手机壳上有一只熊猫。","py":"Hēisè de, shǒujīké shang yǒu yì zhī xióngmāo.","en":"Black — with a panda on the case.","km":"ពណ៌ខ្មៅ ស្រោមទូរសព្ទមានរូបខ្លាឃ្មុំផេនដាមួយ។"},{"who":"Staff","hz":"你坐在哪儿？","py":"Nǐ zuò zài nǎr?","en":"Where were you sitting?","km":"អ្នកអង្គុយនៅឯណា?"},{"who":"You","hz":"窗户旁边那张桌子。","py":"Chuānghu pángbiān nà zhāng zhuōzi.","en":"At that table by the window.","km":"តុនោះក្បែរបង្អួច។"},{"who":"Staff","hz":"是这个吗？服务员刚才捡到的。","py":"Shì zhège ma? Fúwùyuán gāngcái jiǎn dào de.","en":"Is this it? One of the staff just found it.","km":"មួយនេះមែនទេ? អ្នកបម្រើទើបតែរើសបាន។"},{"who":"You","hz":"就是它！太感谢你们了！","py":"Jiù shì tā! Tài gǎnxiè nǐmen le!","en":"That's it! Thank you all so much!","km":"ហ្នឹងហើយ! អរគុណអ្នកទាំងអស់គ្នាច្រើនណាស់!"}],"phrases":[{"hz":"丢了","py":"diū le","en":"Lost","km":"បាត់"},{"hz":"落在这儿了","py":"là zài zhèr le","en":"Left (it) behind here","km":"ភ្លេចទុកនៅទីនេះ"},{"hz":"什么样的？","py":"shénme yàng de?","en":"What kind? / What does it look like?","km":"បែបណា?"},{"hz":"刚才","py":"gāngcái","en":"Just now","km":"មុននេះបន្តិច"},{"hz":"捡到","py":"jiǎn dào","en":"Pick up / find","km":"រើសបាន"},{"hz":"就是它！","py":"jiù shì tā!","en":"That's it!","km":"ហ្នឹងហើយ!"}],"tips":[{"label":"Lost and found","html":"Large stations and malls have a <span class=\"zh\">失物招领处</span> <em>shīwù zhāolǐng chù</em> — lost-and-found office.","culture":true}]},
{"n":87,"ch":8,"title":"At the Gym","titleZh":"在健身房","titleKm":"នៅកន្លែងហាត់ប្រាណ","art":"gym dumbbell shirt m","scene":"You have just joined a gym and talk to a trainer.","dialogue":[{"who":"Trainer","hz":"你平时运动吗？","py":"Nǐ píngshí yùndòng ma?","en":"Do you usually exercise?","km":"ជាធម្មតាអ្នកហាត់ប្រាណទេ?"},{"who":"You","hz":"不常运动，我想锻炼身体。","py":"Bù cháng yùndòng, wǒ xiǎng duànliàn shēntǐ.","en":"Not often — I want to get fit.","km":"មិនសូវហាត់ទេ ខ្ញុំចង់ហាត់ប្រាណឱ្យរឹងមាំ។"},{"who":"Trainer","hz":"你可以先跑步二十分钟，再练力量。","py":"Nǐ kěyǐ xiān pǎobù èrshí fēnzhōng, zài liàn lìliàng.","en":"You could run for twenty minutes first, then do strength training.","km":"អ្នកអាចរត់ម្ភៃនាទីសិន រួចហាត់កម្លាំង។"},{"who":"You","hz":"一个星期来几次比较好？","py":"Yí ge xīngqī lái jǐ cì bǐjiào hǎo?","en":"How many times a week is best?","km":"មួយសប្តាហ៍មកប៉ុន្មានដងទើបល្អ?"},{"who":"Trainer","hz":"三次左右。别忘了运动前热身。","py":"Sān cì zuǒyòu. Bié wàng le yùndòng qián rèshēn.","en":"About three. And don't forget to warm up before exercise.","km":"ប្រហែលបីដង។ កុំភ្លេចកម្តៅសាច់ដុំមុនហាត់។"},{"who":"You","hz":"好的，我试试。","py":"Hǎo de, wǒ shìshi.","en":"OK, I'll give it a go.","km":"បាទ ខ្ញុំសាកមើល។"},{"who":"Trainer","hz":"坚持下去，一定有效果！","py":"Jiānchí xiàqù, yídìng yǒu xiàoguǒ!","en":"Keep at it and you'll definitely see results!","km":"តស៊ូបន្ត ពិតជាមានលទ្ធផល!"}],"phrases":[{"hz":"运动","py":"yùndòng","en":"Exercise / sport","km":"ហាត់ប្រាណ / កីឡា"},{"hz":"锻炼身体","py":"duànliàn shēntǐ","en":"Keep fit / work out","km":"ហាត់ប្រាណ"},{"hz":"跑步","py":"pǎobù","en":"Run / jog","km":"រត់"},{"hz":"热身","py":"rèshēn","en":"Warm up","km":"កម្តៅសាច់ដុំ"},{"hz":"先……再……","py":"xiān … zài…","en":"First … then…","km":"…សិន រួច…"},{"hz":"坚持","py":"jiānchí","en":"Keep at it, persist","km":"តស៊ូ"}],"tips":[{"label":"先……再……","html":"For steps in order: <span class=\"zh\">先洗手，再吃饭</span> — wash your hands first, then eat.","culture":false}]},
{"n":88,"ch":8,"title":"Feeling Tired","titleZh":"我太累了","titleKm":"ខ្ញុំហត់ពេក","art":"home moon shirt f","scene":"Your friend calls late at night. You have been working long hours.","dialogue":[{"who":"Friend","hz":"你最近怎么样？好久没见了！","py":"Nǐ zuìjìn zěnmeyàng? Hǎo jiǔ méi jiàn le!","en":"How have you been? Long time no see!","km":"ថ្មីៗនេះយ៉ាងម៉េចដែរ? យូរហើយមិនបានជួបគ្នា!"},{"who":"You","hz":"太忙了，每天加班，累死了。","py":"Tài máng le, měi tiān jiābān, lèi sǐ le.","en":"Too busy — overtime every day. I'm exhausted.","km":"រវល់ពេក ធ្វើការថែមម៉ោងរាល់ថ្ងៃ ហត់ស្លាប់ហើយ។"},{"who":"Friend","hz":"你睡得够吗？","py":"Nǐ shuì de gòu ma?","en":"Are you getting enough sleep?","km":"អ្នកគេងគ្រប់គ្រាន់ទេ?"},{"who":"You","hz":"不够，每天只睡五个小时。","py":"Bú gòu, měi tiān zhǐ shuì wǔ ge xiǎoshí.","en":"No, only five hours a night.","km":"មិនគ្រប់ទេ គេងតែប្រាំម៉ោងក្នុងមួយថ្ងៃ។"},{"who":"Friend","hz":"这样不行，身体最重要！","py":"Zhèyàng bù xíng, shēntǐ zuì zhòngyào!","en":"That's no good — your health comes first!","km":"បែបនេះមិនបានទេ សុខភាពសំខាន់ជាងគេ!"},{"who":"You","hz":"你说得对。这个周末我要好好休息。","py":"Nǐ shuō de duì. Zhège zhōumò wǒ yào hǎohāo xiūxi.","en":"You're right. This weekend I'm going to have a proper rest.","km":"អ្នកនិយាយត្រូវ។ ចុងសប្តាហ៍នេះខ្ញុំនឹងសម្រាកឱ្យបានល្អ។"}],"phrases":[{"hz":"好久没见了","py":"hǎo jiǔ méi jiàn le","en":"Long time no see","km":"យូរហើយមិនបានជួបគ្នា"},{"hz":"累死了","py":"lèi sǐ le","en":"Dead tired","km":"ហត់ស្លាប់ហើយ"},{"hz":"加班","py":"jiābān","en":"Work overtime","km":"ធ្វើការថែមម៉ោង"},{"hz":"睡得够吗？","py":"shuì de gòu ma?","en":"Are you sleeping enough?","km":"គេងគ្រប់គ្រាន់ទេ?"},{"hz":"身体最重要","py":"shēntǐ zuì zhòngyào","en":"Health comes first","km":"សុខភាពសំខាន់ជាងគេ"},{"hz":"你说得对","py":"nǐ shuō de duì","en":"You're right","km":"អ្នកនិយាយត្រូវ"}],"tips":[{"label":"……死了 for emphasis","html":"In casual speech <span class=\"zh\">死了</span> after an adjective means “extremely”: <span class=\"zh\">热死了</span> boiling hot, <span class=\"zh\">饿死了</span> starving.","culture":false}]},
{"n":89,"ch":8,"title":"Visiting a Sick Friend","titleZh":"看望病人","titleKm":"សួរសុខទុក្ខមិត្តដែលឈឺ","art":"clinic flowers shirt m","scene":"Your classmate is in hospital after an operation. You visit with flowers.","dialogue":[{"who":"You","hz":"听说你住院了，我来看看你。","py":"Tīngshuō nǐ zhùyuàn le, wǒ lái kànkan nǐ.","en":"I heard you were in hospital, so I came to see you.","km":"ឮថាអ្នកសម្រាកពេទ្យ ខ្ញុំមកសួរសុខទុក្ខ។"},{"who":"Classmate","hz":"谢谢你来！花真漂亮。","py":"Xièxie nǐ lái! Huā zhēn piàoliang.","en":"Thanks for coming! The flowers are beautiful.","km":"អរគុណដែលបានមក! ផ្កាស្អាតណាស់។"},{"who":"You","hz":"你现在感觉怎么样？","py":"Nǐ xiànzài gǎnjué zěnmeyàng?","en":"How are you feeling now?","km":"ឥឡូវអ្នកមានអារម្មណ៍យ៉ាងម៉េចដែរ?"},{"who":"Classmate","hz":"好多了。医生说下个星期可以出院。","py":"Hǎo duō le. Yīshēng shuō xià ge xīngqī kěyǐ chūyuàn.","en":"Much better. The doctor says I can go home next week.","km":"ប្រសើរច្រើនហើយ។ គ្រូពេទ្យថាសប្តាហ៍ក្រោយអាចចេញពីពេទ្យបាន។"},{"who":"You","hz":"太好了！上课的笔记我帮你记好了。","py":"Tài hǎo le! Shàngkè de bǐjì wǒ bāng nǐ jì hǎo le.","en":"Great! I've taken the class notes for you.","km":"ល្អណាស់! កំណត់ត្រាមេរៀនខ្ញុំកត់ទុកឱ្យអ្នករួចហើយ។"},{"who":"Classmate","hz":"你真是我的好朋友！","py":"Nǐ zhēn shì wǒ de hǎo péngyou!","en":"You're a real friend!","km":"អ្នកពិតជាមិត្តល្អរបស់ខ្ញុំ!"},{"who":"You","hz":"好好养病，早日康复！","py":"Hǎohāo yǎng bìng, zǎorì kāngfù!","en":"Take good care of yourself — get well soon!","km":"សម្រាកព្យាបាលឱ្យបានល្អ សូមឱ្យឆាប់ជាសះស្បើយ!"}],"phrases":[{"hz":"住院","py":"zhùyuàn","en":"Be in hospital","km":"សម្រាកពេទ្យ"},{"hz":"出院","py":"chūyuàn","en":"Leave hospital","km":"ចេញពីពេទ្យ"},{"hz":"感觉怎么样？","py":"gǎnjué zěnmeyàng?","en":"How do you feel?","km":"មានអារម្មណ៍យ៉ាងម៉េច?"},{"hz":"好多了","py":"hǎo duō le","en":"Much better","km":"ប្រសើរច្រើនហើយ"},{"hz":"笔记","py":"bǐjì","en":"Notes","km":"កំណត់ត្រា"},{"hz":"早日康复！","py":"zǎorì kāngfù!","en":"Get well soon!","km":"សូមឱ្យឆាប់ជាសះស្បើយ!"}],"tips":[{"label":"Gifts for patients","html":"Fruit, flowers and milk are common gifts for someone in hospital. Avoid white flowers — they are for funerals.","culture":true}]},
{"n":90,"ch":8,"title":"A Sprained Ankle","titleZh":"脚扭伤了","titleKm":"កជើងរបួស","art":"park ball shirt m","scene":"You twist your ankle playing football. A teammate runs over.","dialogue":[{"who":"Teammate","hz":"你没事吧？伤到哪儿了？","py":"Nǐ méi shì ba? Shāng dào nǎr le?","en":"Are you OK? Where are you hurt?","km":"អ្នកមិនអីទេឬ? របួសត្រង់ណា?"},{"who":"You","hz":"哎哟，我的脚扭了，好疼！","py":"Āiyō, wǒ de jiǎo niǔ le, hǎo téng!","en":"Ouch, I've twisted my ankle — it really hurts!","km":"អូយ ជើងខ្ញុំរមួល ឈឺណាស់!"},{"who":"Teammate","hz":"别动，我去拿冰块。","py":"Bié dòng, wǒ qù ná bīngkuài.","en":"Don't move — I'll get some ice.","km":"កុំកម្រើក ខ្ញុំទៅយកទឹកកក។"},{"who":"You","hz":"能站起来，但是走路很疼。","py":"Néng zhàn qǐlai, dànshì zǒulù hěn téng.","en":"I can stand up, but walking really hurts.","km":"អាចក្រោកឈរបាន ប៉ុន្តែដើរឈឺណាស់។"},{"who":"Teammate","hz":"肿了。我们还是去医院拍个片子吧。","py":"Zhǒng le. Wǒmen háishi qù yīyuàn pāi ge piānzi ba.","en":"It's swollen. We'd better go to the hospital for an X-ray.","km":"ហើមហើយ។ យើងទៅមន្ទីរពេទ្យថតកាំរស្មីអ៊ិចប្រសើរជាង។"},{"who":"You","hz":"好吧，你能扶我一下吗？","py":"Hǎo ba, nǐ néng fú wǒ yíxià ma?","en":"All right — could you help me walk?","km":"ក៏បាន អ្នកអាចជួយទ្រខ្ញុំបន្តិចបានទេ?"},{"who":"Teammate","hz":"当然，慢慢走。","py":"Dāngrán, mànmàn zǒu.","en":"Of course — slowly does it.","km":"ពិតជាបាន ដើរយឺតៗ។"}],"phrases":[{"hz":"伤到哪儿了？","py":"shāng dào nǎr le?","en":"Where are you hurt?","km":"របួសត្រង់ណា?"},{"hz":"扭伤","py":"niǔshāng","en":"Sprain","km":"រមួល / របួសរមួល"},{"hz":"别动","py":"bié dòng","en":"Don't move","km":"កុំកម្រើក"},{"hz":"肿了","py":"zhǒng le","en":"It's swollen","km":"ហើមហើយ"},{"hz":"拍片子","py":"pāi piānzi","en":"Have an X-ray","km":"ថតកាំរស្មីអ៊ិច"},{"hz":"扶我一下","py":"fú wǒ yíxià","en":"Help me up / support me","km":"ជួយទ្រខ្ញុំបន្តិច"}],"tips":[{"label":"还是 = had better","html":"At the start of a suggestion, <span class=\"zh\">还是</span> means “it would be better to”: <span class=\"zh\">我们还是走吧</span> — we'd better go.","culture":false}]},
{"n":91,"ch":9,"title":"Talking About Hobbies","titleZh":"聊爱好","titleKm":"និយាយអំពីចំណូលចិត្ត","art":"park book shirt f","scene":"You are getting to know a new friend over a walk in the park.","dialogue":[{"who":"Friend","hz":"你有什么爱好？","py":"Nǐ yǒu shénme àihào?","en":"What are your hobbies?","km":"អ្នកមានចំណូលចិត្តអ្វីខ្លះ?"},{"who":"You","hz":"我喜欢看书和听音乐。你呢？","py":"Wǒ xǐhuan kàn shū hé tīng yīnyuè. Nǐ ne?","en":"I like reading and listening to music. And you?","km":"ខ្ញុំចូលចិត្តអានសៀវភៅ និងស្តាប់តន្ត្រី។ ចុះអ្នក?"},{"who":"Friend","hz":"我喜欢画画儿，也喜欢游泳。","py":"Wǒ xǐhuan huà huàr, yě xǐhuan yóuyǒng.","en":"I like painting, and swimming too.","km":"ខ្ញុំចូលចិត្តគូររូប ហើយក៏ចូលចិត្តហែលទឹកដែរ។"},{"who":"You","hz":"你画画儿画了多长时间了？","py":"Nǐ huà huàr huà le duō cháng shíjiān le?","en":"How long have you been painting?","km":"អ្នកគូររូបបានប៉ុន្មានឆ្នាំហើយ?"},{"who":"Friend","hz":"五年了。周末我常常去公园画风景。","py":"Wǔ nián le. Zhōumò wǒ chángcháng qù gōngyuán huà fēngjǐng.","en":"Five years. At weekends I often paint landscapes in the park.","km":"ប្រាំឆ្នាំហើយ។ ចុងសប្តាហ៍ខ្ញុំតែងទៅគូរទេសភាពនៅសួន។"},{"who":"You","hz":"真厉害！下次可以带我一起去吗？","py":"Zhēn lìhai! Xià cì kěyǐ dài wǒ yìqǐ qù ma?","en":"Impressive! Could you take me along next time?","km":"ពូកែមែន! លើកក្រោយអាចនាំខ្ញុំទៅជាមួយបានទេ?"},{"who":"Friend","hz":"当然可以！","py":"Dāngrán kěyǐ!","en":"Of course!","km":"ពិតជាបាន!"}],"phrases":[{"hz":"爱好","py":"àihào","en":"Hobby","km":"ចំណូលចិត្ត"},{"hz":"听音乐","py":"tīng yīnyuè","en":"Listen to music","km":"ស្តាប់តន្ត្រី"},{"hz":"看书","py":"kàn shū","en":"Read (books)","km":"អានសៀវភៅ"},{"hz":"画画儿","py":"huà huàr","en":"Draw / paint","km":"គូររូប"},{"hz":"游泳","py":"yóuyǒng","en":"Swim","km":"ហែលទឹក"},{"hz":"常常","py":"chángcháng","en":"Often","km":"តែង / ញឹកញាប់"}],"tips":[{"label":"How long so far","html":"Verb + <span class=\"zh\">了</span> + time + <span class=\"zh\">了</span> means “have been doing for”: <span class=\"zh\">我学了两年了</span> — I've been learning for two years (and still am).","culture":false}]},
{"n":92,"ch":9,"title":"Going to the Movies","titleZh":"约看电影","titleKm":"ណាត់មើលកុន","art":"night ticket shirt m","scene":"You call a friend to invite him to see a new film.","dialogue":[{"who":"You","hz":"今天晚上有空吗？我们去看电影吧！","py":"Jīntiān wǎnshang yǒu kòng ma? Wǒmen qù kàn diànyǐng ba!","en":"Are you free tonight? Let's go and see a film!","km":"យប់នេះទំនេរទេ? យើងទៅមើលកុនណា!"},{"who":"Friend","hz":"好啊！看什么电影？","py":"Hǎo a! Kàn shénme diànyǐng?","en":"Sure! Which film?","km":"បាន! មើលរឿងអ្វី?"},{"who":"You","hz":"新出的那个动作片，听说很好看。","py":"Xīn chū de nàge dòngzuòpiàn, tīngshuō hěn hǎokàn.","en":"That new action film — I hear it's really good.","km":"រឿងបែបវាយប្រហារដែលទើបចេញ ឮថាល្អមើលណាស់។"},{"who":"Friend","hz":"几点的？","py":"Jǐ diǎn de?","en":"What time?","km":"ម៉ោងប៉ុន្មាន?"},{"who":"You","hz":"七点半的。我已经在网上买好票了。","py":"Qī diǎn bàn de. Wǒ yǐjīng zài wǎngshang mǎi hǎo piào le.","en":"The 7:30 show. I've already bought tickets online.","km":"ម៉ោងប្រាំពីរកន្លះ។ ខ្ញុំទិញសំបុត្រតាមអនឡាញរួចហើយ។"},{"who":"Friend","hz":"太好了！我们在电影院门口见。","py":"Tài hǎo le! Wǒmen zài diànyǐngyuàn ménkǒu jiàn.","en":"Great! Let's meet at the cinema entrance.","km":"ល្អណាស់! យើងជួបគ្នានៅមុខរោងកុន។"},{"who":"You","hz":"好，我请你吃爆米花！","py":"Hǎo, wǒ qǐng nǐ chī bàomǐhuā!","en":"OK — the popcorn's on me!","km":"បាន ខ្ញុំចេញពោតលីងឱ្យ!"}],"phrases":[{"hz":"看电影","py":"kàn diànyǐng","en":"Watch a film","km":"មើលកុន"},{"hz":"电影院","py":"diànyǐngyuàn","en":"Cinema","km":"រោងកុន"},{"hz":"好看","py":"hǎokàn","en":"Good to watch / good-looking","km":"ល្អមើល"},{"hz":"动作片","py":"dòngzuòpiàn","en":"Action film","km":"រឿងបែបវាយប្រហារ"},{"hz":"买好票了","py":"mǎi hǎo piào le","en":"Already bought the tickets","km":"ទិញសំបុត្ររួចហើយ"},{"hz":"爆米花","py":"bàomǐhuā","en":"Popcorn","km":"ពោតលីង"}],"tips":[{"label":"好 + verb","html":"<span class=\"zh\">好看</span> good to look at, <span class=\"zh\">好听</span> nice to hear, <span class=\"zh\">好吃</span> tasty, <span class=\"zh\">好喝</span> nice to drink.","culture":false}]},
{"n":93,"ch":9,"title":"A Birthday Party","titleZh":"生日聚会","titleKm":"ពិធីជប់លៀងខួបកំណើត","art":"home gift shirt f","scene":"You arrive at your friend Xiaomei's birthday party with a present.","dialogue":[{"who":"You","hz":"小美，生日快乐！这是送给你的礼物。","py":"Xiǎoměi, shēngrì kuàilè! Zhè shì sòng gěi nǐ de lǐwù.","en":"Xiaomei, happy birthday! This present is for you.","km":"សៅម៉ី រីករាយថ្ងៃកំណើត! នេះជាកាដូជូនអ្នក។"},{"who":"Xiaomei","hz":"谢谢！你太客气了。我可以打开吗？","py":"Xièxie! Nǐ tài kèqi le. Wǒ kěyǐ dǎkāi ma?","en":"Thank you! You shouldn't have. Can I open it?","km":"អរគុណ! អ្នកគួរសមពេកហើយ។ ខ្ញុំអាចបើកមើលបានទេ?"},{"who":"You","hz":"当然，希望你喜欢。","py":"Dāngrán, xīwàng nǐ xǐhuan.","en":"Of course — I hope you like it.","km":"ពិតជាបាន សង្ឃឹមថាអ្នកចូលចិត្ត។"},{"who":"Xiaomei","hz":"哇，是一条丝巾！好漂亮啊！","py":"Wā, shì yì tiáo sījīn! Hǎo piàoliang a!","en":"Wow, a silk scarf! It's beautiful!","km":"វ៉ាវ កន្សែងសូត្រ! ស្អាតណាស់!"},{"who":"You","hz":"这是柬埔寨的丝绸，我特意带来的。","py":"Zhè shì Jiǎnpǔzhài de sīchóu, wǒ tèyì dài lái de.","en":"It's Cambodian silk — I brought it specially.","km":"នេះជាសូត្រខ្មែរ ខ្ញុំយកមកពិសេស។"},{"who":"Xiaomei","hz":"我太喜欢了！快来吃蛋糕吧。","py":"Wǒ tài xǐhuan le! Kuài lái chī dàngāo ba.","en":"I love it! Come and have some cake.","km":"ខ្ញុំចូលចិត្តណាស់! មកញ៉ាំនំខេកលឿនៗ។"},{"who":"You","hz":"先许个愿，再吹蜡烛！","py":"Xiān xǔ ge yuàn, zài chuī làzhú!","en":"Make a wish first, then blow out the candles!","km":"ធ្វើបណ្តាំសិន រួចផ្លុំទៀន!"}],"phrases":[{"hz":"生日快乐！","py":"shēngrì kuàilè!","en":"Happy birthday!","km":"រីករាយថ្ងៃកំណើត!"},{"hz":"礼物","py":"lǐwù","en":"Present / gift","km":"កាដូ"},{"hz":"送给你","py":"sòng gěi nǐ","en":"(It's) for you","km":"ជូនអ្នក"},{"hz":"希望你喜欢","py":"xīwàng nǐ xǐhuan","en":"Hope you like it","km":"សង្ឃឹមថាអ្នកចូលចិត្ត"},{"hz":"许愿","py":"xǔyuàn","en":"Make a wish","km":"ធ្វើបណ្តាំ"},{"hz":"吹蜡烛","py":"chuī làzhú","en":"Blow out the candles","km":"ផ្លុំទៀន"}],"tips":[{"label":"Opening presents","html":"Traditionally, Chinese people don't open a gift in front of the giver. Younger people often ask <span class=\"zh\">我可以打开吗？</span> first.","culture":true}]},
{"n":94,"ch":9,"title":"Watching the Match","titleZh":"看球赛","titleKm":"មើលការប្រកួតបាល់","art":"night ball shirt m","scene":"You are watching a football match on TV with a friend.","dialogue":[{"who":"Friend","hz":"快看！要进球了！","py":"Kuài kàn! Yào jìn qiú le!","en":"Look! They're about to score!","km":"មើលលឿន! ជិតស៊ុតបញ្ចូលទីហើយ!"},{"who":"You","hz":"进了！太棒了！","py":"Jìn le! Tài bàng le!","en":"Goal! Fantastic!","km":"ចូលហើយ! អស្ចារ្យណាស់!"},{"who":"Friend","hz":"现在几比几？","py":"Xiànzài jǐ bǐ jǐ?","en":"What's the score now?","km":"ឥឡូវពិន្ទុប៉ុន្មានទល់ប៉ុន្មាន?"},{"who":"You","hz":"二比一，我们领先！","py":"Èr bǐ yī, wǒmen lǐngxiān!","en":"Two-one — we're ahead!","km":"ពីរទល់មួយ យើងនាំមុខ!"},{"who":"Friend","hz":"你支持哪个队？","py":"Nǐ zhīchí nǎge duì?","en":"Which team do you support?","km":"អ្នកគាំទ្រក្រុមណា?"},{"who":"You","hz":"我一直支持这个队，从小就喜欢。","py":"Wǒ yìzhí zhīchí zhège duì, cóng xiǎo jiù xǐhuan.","en":"I've always supported this team — since I was little.","km":"ខ្ញុំគាំទ្រក្រុមនេះរហូត ចូលចិត្តតាំងពីតូច។"},{"who":"Friend","hz":"还有十分钟，加油！","py":"Hái yǒu shí fēnzhōng, jiāyóu!","en":"Ten minutes to go — come on!","km":"នៅសល់ដប់នាទីទៀត ខំប្រឹងឡើង!"}],"phrases":[{"hz":"比赛","py":"bǐsài","en":"Match / competition","km":"ការប្រកួត"},{"hz":"进球了！","py":"jìn qiú le!","en":"Goal!","km":"ចូលទីហើយ!"},{"hz":"几比几？","py":"jǐ bǐ jǐ?","en":"What's the score?","km":"ពិន្ទុប៉ុន្មានទល់ប៉ុន្មាន?"},{"hz":"二比一","py":"èr bǐ yī","en":"Two-one","km":"ពីរទល់មួយ"},{"hz":"支持","py":"zhīchí","en":"Support (a team)","km":"គាំទ្រ"},{"hz":"从小","py":"cóng xiǎo","en":"Since childhood","km":"តាំងពីតូច"}],"tips":[{"label":"加油! at games","html":"Fans shout <span class=\"zh\">加油！</span> — literally “add fuel!” — to cheer on players, students before exams, anyone trying hard.","culture":true}]},
{"n":95,"ch":9,"title":"Could You Take a Photo?","titleZh":"帮我们拍张照","titleKm":"ជួយថតរូបឱ្យយើងបានទេ?","art":"temple camera shirt f","scene":"You and a friend are at a famous temple and want a photo together.","dialogue":[{"who":"You","hz":"你好，能帮我们拍张照吗？","py":"Nǐ hǎo, néng bāng wǒmen pāi zhāng zhào ma?","en":"Hello, could you take a photo of us?","km":"សួស្តី អាចជួយថតរូបឱ្យយើងបន្តិចបានទេ?"},{"who":"Tourist","hz":"没问题。按这里吗？","py":"Méi wèntí. Àn zhèli ma?","en":"No problem. Do I press here?","km":"គ្មានបញ្ហា។ ចុចត្រង់នេះមែនទេ?"},{"who":"You","hz":"对，按这个白色的圆圈。","py":"Duì, àn zhège báisè de yuánquān.","en":"Yes, press this white circle.","km":"ត្រូវ ចុចរង្វង់ពណ៌សនេះ។"},{"who":"Tourist","hz":"往左边站一点儿，要把寺庙拍进去。","py":"Wǎng zuǒbian zhàn yìdiǎnr, yào bǎ sìmiào pāi jìnqù.","en":"Stand a bit to the left — I want to get the temple in.","km":"ឈរទៅខាងឆ្វេងបន្តិច ចង់ថតឱ្យជាប់វត្តផង។"},{"who":"You","hz":"这样可以吗？","py":"Zhèyàng kěyǐ ma?","en":"Is this OK?","km":"បែបនេះបានទេ?"},{"who":"Tourist","hz":"很好。一、二、三，茄子！","py":"Hěn hǎo. Yī, èr, sān, qiézi!","en":"Great. One, two, three — say cheese!","km":"ល្អណាស់។ មួយ ពីរ បី ឈីស!"},{"who":"You","hz":"拍得真好，谢谢你！","py":"Pāi de zhēn hǎo, xièxie nǐ!","en":"That's a great shot — thank you!","km":"ថតបានល្អណាស់ អរគុណ!"}],"phrases":[{"hz":"拍照","py":"pāizhào","en":"Take a photo","km":"ថតរូប"},{"hz":"能帮我们拍张照吗？","py":"néng bāng wǒmen pāi zhāng zhào ma?","en":"Could you take our photo?","km":"អាចជួយថតរូបឱ្យយើងបានទេ?"},{"hz":"按这里","py":"àn zhèli","en":"Press here","km":"ចុចត្រង់នេះ"},{"hz":"往左边站","py":"wǎng zuǒbian zhàn","en":"Stand to the left","km":"ឈរទៅខាងឆ្វេង"},{"hz":"这样可以吗？","py":"zhèyàng kěyǐ ma?","en":"Is this OK?","km":"បែបនេះបានទេ?"},{"hz":"茄子！","py":"qiézi!","en":"Cheese! (literally “aubergine”)","km":"ឈីស! (ត្រង់ន័យ «ត្រប់»)"}],"tips":[{"label":"Aubergine smile","html":"Chinese photographers say <span class=\"zh\">茄子</span> <em>qiézi</em> (aubergine) because the <em>-ie</em> sound makes people smile.","culture":true}]},
{"n":96,"ch":9,"title":"Planning a Trip","titleZh":"计划旅行","titleKm":"គម្រោងដំណើរកម្សាន្ត","art":"cafe globe shirt m","scene":"Your Chinese friend is planning a holiday and asks for ideas.","dialogue":[{"who":"Friend","hz":"国庆节放假七天，我想去旅游。","py":"Guóqìng Jié fàngjià qī tiān, wǒ xiǎng qù lǚyóu.","en":"We have seven days off for National Day — I want to travel.","km":"បុណ្យជាតិឈប់សម្រាកប្រាំពីរថ្ងៃ ខ្ញុំចង់ទៅដើរលេង។"},{"who":"You","hz":"你来柬埔寨吧！可以去吴哥窟和海边。","py":"Nǐ lái Jiǎnpǔzhài ba! Kěyǐ qù Wúgē Kū hé hǎibiān.","en":"Come to Cambodia! You can visit Angkor Wat and the beach.","km":"មកកម្ពុជាមក! អាចទៅអង្គរវត្ត និងមាត់សមុទ្របាន។"},{"who":"Friend","hz":"好主意！需要签证吗？","py":"Hǎo zhǔyi! Xūyào qiānzhèng ma?","en":"Good idea! Do I need a visa?","km":"គំនិតល្អ! ត្រូវការទិដ្ឋាការទេ?"},{"who":"You","hz":"需要，可以在网上办电子签证。","py":"Xūyào, kěyǐ zài wǎngshang bàn diànzǐ qiānzhèng.","en":"Yes, you can get an e-visa online.","km":"ត្រូវការ អាចធ្វើទិដ្ឋាការអេឡិចត្រូនិកតាមអនឡាញ។"},{"who":"Friend","hz":"那时候天气怎么样？","py":"Nà shíhou tiānqì zěnmeyàng?","en":"What's the weather like then?","km":"ពេលនោះអាកាសធាតុយ៉ាងម៉េច?"},{"who":"You","hz":"十月还是雨季，最好带把伞。","py":"Shí yuè hái shì yǔjì, zuìhǎo dài bǎ sǎn.","en":"October is still the rainy season — best bring an umbrella.","km":"ខែតុលានៅរដូវវស្សា គួរតែយកឆ័ត្រមួយមក។"},{"who":"Friend","hz":"好，我现在就订机票！","py":"Hǎo, wǒ xiànzài jiù dìng jīpiào!","en":"OK, I'll book my flight right now!","km":"បាន ខ្ញុំកក់សំបុត្រយន្តហោះឥឡូវនេះ!"}],"phrases":[{"hz":"旅游","py":"lǚyóu","en":"Travel / tourism","km":"ទេសចរណ៍ / ដើរលេង"},{"hz":"放假","py":"fàngjià","en":"Have a holiday","km":"ឈប់សម្រាក"},{"hz":"签证","py":"qiānzhèng","en":"Visa","km":"ទិដ្ឋាការ"},{"hz":"好主意！","py":"hǎo zhǔyi!","en":"Good idea!","km":"គំនិតល្អ!"},{"hz":"雨季","py":"yǔjì","en":"Rainy season","km":"រដូវវស្សា"},{"hz":"订机票","py":"dìng jīpiào","en":"Book a flight","km":"កក់សំបុត្រយន្តហោះ"}],"tips":[{"label":"Golden Week","html":"China's National Day (1 October) gives a week-long holiday called <span class=\"zh\">黄金周</span> “Golden Week” — the busiest time to travel.","culture":true}]},
{"n":97,"ch":9,"title":"Buying Tickets at a Sight","titleZh":"买门票","titleKm":"ទិញសំបុត្រចូលទស្សនា","art":"temple ticket uniform f","scene":"You arrive at a museum with your younger cousin.","dialogue":[{"who":"You","hz":"你好，买两张门票。","py":"Nǐ hǎo, mǎi liǎng zhāng ménpiào.","en":"Hello, two tickets please.","km":"សួស្តី ទិញសំបុត្រចូលពីរ។"},{"who":"Staff","hz":"成人票六十，学生票半价。","py":"Chéngrén piào liùshí, xuésheng piào bànjià.","en":"Adults are 60, students half price.","km":"សំបុត្រមនុស្សពេញវ័យ ហុកសិប សិស្សពាក់កណ្តាលតម្លៃ។"},{"who":"You","hz":"她是小学生，这是她的学生证。","py":"Tā shì xiǎoxuéshēng, zhè shì tā de xuéshengzhèng.","en":"She's at primary school — here's her student card.","km":"នាងជាសិស្សបឋមសិក្សា នេះជាកាតសិស្សរបស់នាង។"},{"who":"Staff","hz":"好的，一共九十块。","py":"Hǎo de, yígòng jiǔshí kuài.","en":"OK, ninety altogether.","km":"បាទ/ចាស សរុបកៅសិបយ័ន។"},{"who":"You","hz":"有中文讲解吗？","py":"Yǒu Zhōngwén jiǎngjiě ma?","en":"Is there a guided tour in Chinese?","km":"មានការពន្យល់ជាភាសាចិនទេ?"},{"who":"Staff","hz":"有，每个小时一次。也可以租语音导览。","py":"Yǒu, měi ge xiǎoshí yí cì. Yě kěyǐ zū yǔyīn dǎolǎn.","en":"Yes, once an hour. You can also rent an audio guide.","km":"មាន មួយម៉ោងម្តង។ ក៏អាចជួលឧបករណ៍ណែនាំជាសំឡេងបានដែរ។"},{"who":"You","hz":"几点关门？","py":"Jǐ diǎn guānmén?","en":"What time do you close?","km":"បិទម៉ោងប៉ុន្មាន?"},{"who":"Staff","hz":"下午五点，四点停止入场。","py":"Xiàwǔ wǔ diǎn, sì diǎn tíngzhǐ rùchǎng.","en":"5 pm — last entry is at 4.","km":"ម៉ោងប្រាំល្ងាច ម៉ោងបួនឈប់ឱ្យចូល។"}],"phrases":[{"hz":"门票","py":"ménpiào","en":"Entrance ticket","km":"សំបុត្រចូល"},{"hz":"成人票","py":"chéngrén piào","en":"Adult ticket","km":"សំបុត្រមនុស្សពេញវ័យ"},{"hz":"半价","py":"bànjià","en":"Half price","km":"ពាក់កណ្តាលតម្លៃ"},{"hz":"讲解","py":"jiǎngjiě","en":"Guided explanation","km":"ការពន្យល់"},{"hz":"几点关门？","py":"jǐ diǎn guānmén?","en":"What time does it close?","km":"បិទម៉ោងប៉ុន្មាន?"},{"hz":"几点开门？","py":"jǐ diǎn kāimén?","en":"What time does it open?","km":"បើកម៉ោងប៉ុន្មាន?"}],"tips":[{"label":"Book ahead","html":"Many famous sights in China need tickets booked online a day or more before — and your passport to get in.","culture":true}]},
{"n":98,"ch":9,"title":"A Night at Karaoke","titleZh":"去唱K","titleKm":"ទៅច្រៀងខារ៉ាអូខេ","art":"night mic shirt f","scene":"Your colleagues take you to a karaoke room to celebrate the end of a project.","dialogue":[{"who":"Colleague","hz":"该你唱了！你想唱什么歌？","py":"Gāi nǐ chàng le! Nǐ xiǎng chàng shénme gē?","en":"Your turn to sing! What song do you want?","km":"ដល់វេនអ្នកច្រៀងហើយ! ចង់ច្រៀងបទអ្វី?"},{"who":"You","hz":"我不太会唱中文歌……","py":"Wǒ bú tài huì chàng Zhōngwén gē…","en":"I can't really sing Chinese songs…","km":"ខ្ញុំមិនសូវចេះច្រៀងបទចិនទេ…"},{"who":"Colleague","hz":"没关系，唱一首简单的吧！","py":"Méi guānxi, chàng yì shǒu jiǎndān de ba!","en":"Never mind — sing an easy one!","km":"មិនអីទេ ច្រៀងបទងាយៗមួយមក!"},{"who":"You","hz":"那我唱《月亮代表我的心》吧，我妈妈很喜欢这首歌。","py":"Nà wǒ chàng “Yuèliang Dàibiǎo Wǒ de Xīn” ba, wǒ māma hěn xǐhuan zhè shǒu gē.","en":"Then I'll sing “The Moon Represents My Heart” — my mum loves this song.","km":"អញ្ចឹងខ្ញុំច្រៀងបទ «ព្រះចន្ទតំណាងចិត្តខ្ញុំ» ម្តាយខ្ញុំចូលចិត្តបទនេះណាស់។"},{"who":"Colleague","hz":"好啊！这是经典老歌。","py":"Hǎo a! Zhè shì jīngdiǎn lǎo gē.","en":"Great! That's a classic.","km":"ល្អ! នេះជាបទចាស់ល្បី។"},{"who":"You","hz":"唱得不好，大家别笑我啊！","py":"Chàng de bù hǎo, dàjiā bié xiào wǒ a!","en":"I'm not a good singer — don't laugh at me, everyone!","km":"ខ្ញុំច្រៀងមិនពិរោះទេ ទាំងអស់គ្នាកុំសើចខ្ញុំណា!"},{"who":"Colleague","hz":"你唱得很好听！再来一首！","py":"Nǐ chàng de hěn hǎotīng! Zài lái yì shǒu!","en":"You sing beautifully! Another one!","km":"អ្នកច្រៀងពិរោះណាស់! មួយបទទៀត!"}],"phrases":[{"hz":"唱歌","py":"chàng gē","en":"Sing (a song)","km":"ច្រៀង"},{"hz":"该你了","py":"gāi nǐ le","en":"It's your turn","km":"ដល់វេនអ្នកហើយ"},{"hz":"一首歌","py":"yì shǒu gē","en":"A song","km":"ចម្រៀងមួយបទ"},{"hz":"好听","py":"hǎotīng","en":"Nice to listen to","km":"ពិរោះ"},{"hz":"别笑我","py":"bié xiào wǒ","en":"Don't laugh at me","km":"កុំសើចខ្ញុំ"},{"hz":"再来一首！","py":"zài lái yì shǒu!","en":"Another song!","km":"មួយបទទៀត!"}],"tips":[{"label":"KTV","html":"Karaoke in China is called <span class=\"zh\">KTV</span> and is a favourite way for friends and colleagues to celebrate — in a private room.","culture":true}]},
{"n":99,"ch":9,"title":"Congratulations!","titleZh":"祝贺你！","titleKm":"សូមអបអរសាទរ!","art":"office gift suit m","scene":"A friend tells you he got a promotion and is getting married.","dialogue":[{"who":"Friend","hz":"告诉你一个好消息，我升职了！","py":"Gàosu nǐ yí ge hǎo xiāoxi, wǒ shēngzhí le!","en":"I've got good news — I've been promoted!","km":"ប្រាប់អ្នកដំណឹងល្អមួយ ខ្ញុំឡើងតំណែងហើយ!"},{"who":"You","hz":"真的吗？祝贺你！","py":"Zhēn de ma? Zhùhè nǐ!","en":"Really? Congratulations!","km":"ពិតមែនឬ? សូមអបអរសាទរ!"},{"who":"Friend","hz":"还有，我下个月结婚。","py":"Hái yǒu, wǒ xià ge yuè jiéhūn.","en":"And — I'm getting married next month.","km":"ហើយមួយទៀត ខែក្រោយខ្ញុំរៀបការ។"},{"who":"You","hz":"双喜临门啊！新娘是谁？","py":"Shuāngxǐ línmén a! Xīnniáng shì shéi?","en":"Double happiness! Who's the bride?","km":"សុភមង្គលពីរជាន់! កូនក្រមុំជានរណា?"},{"who":"Friend","hz":"是我大学同学。这是请柬，你一定要来！","py":"Shì wǒ dàxué tóngxué. Zhè shì qǐngjiǎn, nǐ yídìng yào lái!","en":"My university classmate. Here's the invitation — you must come!","km":"ជាមិត្តរួមថ្នាក់សាកលវិទ្យាល័យ។ នេះជាសំបុត្រអញ្ជើញ អ្នកត្រូវតែមក!"},{"who":"You","hz":"一定去！祝你们白头偕老！","py":"Yídìng qù! Zhù nǐmen báitóu xiélǎo!","en":"I'll definitely be there! Wishing you a long life together!","km":"ពិតជាទៅ! សូមឱ្យអ្នកទាំងពីររស់នៅជាមួយគ្នារហូតដល់ចាស់!"}],"phrases":[{"hz":"祝贺你！","py":"zhùhè nǐ!","en":"Congratulations!","km":"សូមអបអរសាទរ!"},{"hz":"好消息","py":"hǎo xiāoxi","en":"Good news","km":"ដំណឹងល្អ"},{"hz":"升职","py":"shēngzhí","en":"Be promoted","km":"ឡើងតំណែង"},{"hz":"请柬","py":"qǐngjiǎn","en":"Invitation card","km":"សំបុត្រអញ្ជើញ"},{"hz":"一定去","py":"yídìng qù","en":"I'll definitely go","km":"ពិតជាទៅ"},{"hz":"白头偕老","py":"báitóu xiélǎo","en":"Grow old together (wedding wish)","km":"រស់នៅជាមួយគ្នារហូតដល់ចាស់"}],"tips":[{"label":"Wedding red envelopes","html":"At Chinese weddings guests give money in a red envelope. Even amounts are lucky; avoid amounts with 4, which sounds like “death”.","culture":true}]},
{"n":100,"ch":9,"title":"Saying Goodbye to a Friend","titleZh":"送别朋友","titleKm":"ជូនដំណើរមិត្ត","art":"airport plane shirt f","scene":"Your Chinese friend is flying home after a year in Cambodia. You see her off at the airport.","dialogue":[{"who":"You","hz":"时间过得真快，你要回国了。","py":"Shíjiān guò de zhēn kuài, nǐ yào huí guó le.","en":"Time flies — you're going home already.","km":"ពេលវេលាកន្លងទៅលឿនណាស់ អ្នកត្រូវត្រឡប់ទៅប្រទេសវិញហើយ។"},{"who":"Friend","hz":"是啊，我会想你的。","py":"Shì a, wǒ huì xiǎng nǐ de.","en":"Yes — I'll miss you.","km":"មែនហើយ ខ្ញុំនឹងនឹកអ្នក។"},{"who":"You","hz":"我也会想你。到了给我发个消息。","py":"Wǒ yě huì xiǎng nǐ. Dào le gěi wǒ fā ge xiāoxi.","en":"I'll miss you too. Send me a message when you arrive.","km":"ខ្ញុំក៏នឹងនឹកអ្នកដែរ។ ទៅដល់ផ្ញើសារមកខ្ញុំផង។"},{"who":"Friend","hz":"一定。欢迎你以后来中国找我！","py":"Yídìng. Huānyíng nǐ yǐhòu lái Zhōngguó zhǎo wǒ!","en":"I will. Come and visit me in China one day!","km":"ពិតជាផ្ញើ។ សូមស្វាគមន៍ពេលក្រោយមកលេងខ្ញុំនៅចិន!"},{"who":"You","hz":"好！我会继续学中文的。","py":"Hǎo! Wǒ huì jìxù xué Zhōngwén de.","en":"I will! And I'll keep learning Chinese.","km":"បាន! ខ្ញុំនឹងបន្តរៀនភាសាចិន។"},{"who":"Friend","hz":"你的中文已经很好了。保重！","py":"Nǐ de Zhōngwén yǐjīng hěn hǎo le. Bǎozhòng!","en":"Your Chinese is already very good. Take care!","km":"ភាសាចិនរបស់អ្នកល្អណាស់ហើយ។ ថែរក្សាខ្លួនផង!"},{"who":"You","hz":"一路平安！保持联系！","py":"Yílù píng'ān! Bǎochí liánxì!","en":"Have a safe trip! Keep in touch!","km":"សូមធ្វើដំណើរប្រកបដោយសុវត្ថិភាព! ទាក់ទងគ្នាជានិច្ច!"}],"phrases":[{"hz":"我会想你的","py":"wǒ huì xiǎng nǐ de","en":"I'll miss you","km":"ខ្ញុំនឹងនឹកអ្នក"},{"hz":"时间过得真快","py":"shíjiān guò de zhēn kuài","en":"Time flies","km":"ពេលវេលាកន្លងទៅលឿនណាស់"},{"hz":"保重","py":"bǎozhòng","en":"Take care","km":"ថែរក្សាខ្លួន"},{"hz":"一路平安！","py":"yílù píng'ān!","en":"Have a safe journey!","km":"សូមធ្វើដំណើរប្រកបដោយសុវត្ថិភាព!"},{"hz":"保持联系","py":"bǎochí liánxì","en":"Keep in touch","km":"ទាក់ទងគ្នាជានិច្ច"},{"hz":"继续学中文","py":"jìxù xué Zhōngwén","en":"Keep learning Chinese","km":"បន្តរៀនភាសាចិន"}],"tips":[{"label":"Well done!","html":"You've reached lesson 100! <span class=\"zh\">恭喜你！</span> Go back to any lesson for more role-play — practice is how Chinese sticks.","culture":false},{"label":"Travel wishes","html":"<span class=\"zh\">一路平安</span> (safe journey) and <span class=\"zh\">一路顺风</span> (smooth trip) are said to people leaving — but never <span class=\"zh\">一路顺风</span> to someone about to fly.","culture":true}]}]};
